// src/styles/theme.js
import { createTheme } from '@mui/material/styles';
import { alpha } from '@mui/material';

// --- CONSTANTES DE DISEÑO ---
const PRIMARY_COLOR = '#1B396A'; // Azul oscuro
const SECONDARY_COLOR = '#FBBE18'; // Amarillo/Dorado
const ERROR_COLOR = '#D32F2F';
const SUCCESS_COLOR = '#388E3C';
const WARNING_COLOR = '#F57C00';
const INFO_COLOR = '#1976D2';
const GREY_TEXT = '#555E68'; // Gris para texto secundario
const GREY_BORDER = '#DDE1E6'; // Gris claro para bordes
const BACKGROUND_DEFAULT = '#F8F9FA'; // Gris muy claro para fondo general
const BACKGROUND_PAPER = '#FFFFFF'; // Blanco para superficies elevadas
const BASE_BORDER_RADIUS = 12; // Bordes más redondeados

// --- CREACIÓN DEL TEMA ---
export const theme = createTheme({
    // --- PALETA DE COLORES ---
    palette: {
        mode: 'light', // Modo claro por defecto
        primary: {
            main: PRIMARY_COLOR,
            light: alpha(PRIMARY_COLOR, 0.8),
            dark: alpha(PRIMARY_COLOR, 0.9),
            contrastText: '#FFFFFF'
        },
        secondary: {
            main: SECONDARY_COLOR,
            light: alpha(SECONDARY_COLOR, 0.8),
            dark: alpha(SECONDARY_COLOR, 0.9),
            contrastText: PRIMARY_COLOR // Contraste con el primario
        },
        error: {
            main: ERROR_COLOR,
            light: alpha(ERROR_COLOR, 0.8),
            dark: alpha(ERROR_COLOR, 0.9),
            contrastText: '#FFFFFF'
        },
        warning: {
            main: WARNING_COLOR,
            light: alpha(WARNING_COLOR, 0.8),
            dark: alpha(WARNING_COLOR, 0.9),
            contrastText: '#FFFFFF'
        },
        success: {
            main: SUCCESS_COLOR,
            light: alpha(SUCCESS_COLOR, 0.8),
            dark: alpha(SUCCESS_COLOR, 0.9),
            contrastText: '#FFFFFF'
        },
        info: {
            main: INFO_COLOR,
            light: alpha(INFO_COLOR, 0.8),
            dark: alpha(INFO_COLOR, 0.9),
            contrastText: '#FFFFFF'
        },
        grey: { // Escala de grises
            50: '#F8F9FA',
            100: '#F3F5F7',
            200: '#EAECEF',
            300: '#DDE1E6', // GREY_BORDER
            400: '#C4CDD5',
            500: '#919EAB',
            600: '#637381', // GREY_TEXT (más oscuro que 500)
            700: '#454F5B',
            800: '#212B36',
            900: '#161C24',
        },
        text: {
            primary: alpha('#000000', 0.87), // Casi negro para contraste
            secondary: GREY_TEXT,
            disabled: alpha(GREY_TEXT, 0.5)
        },
        background: {
            default: BACKGROUND_DEFAULT,
            paper: BACKGROUND_PAPER,
        },
        action: { // Colores para estados de interacción
            active: alpha(GREY_TEXT, 0.54),
            hover: alpha(GREY_TEXT, 0.06), // Hover muy sutil
            selected: alpha(PRIMARY_COLOR, 0.08), // Selección con color primario
            disabled: alpha(GREY_TEXT, 0.80),
            disabledBackground: alpha(GREY_TEXT, 0.12), // Fondo deshabilitado más claro
            focus: alpha(PRIMARY_COLOR, 0.12), // Foco con color primario
            hoverOpacity: 0.06,
            disabledOpacity: 0.48,
        },
        divider: GREY_BORDER, // Color para divisores
    },

    // --- TIPOGRAFÍA ---
    typography: {
        fontFamily: '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"',
        fontWeightLight: 300,
        fontWeightRegular: 400,
        fontWeightMedium: 500,
        fontWeightBold: 700,
        // Ajustes de tamaño y peso para encabezados y cuerpo
        h1: { fontWeight: 700, fontSize: '2.25rem', lineHeight: 1.2, letterSpacing: '-0.015em' },
        h2: { fontWeight: 700, fontSize: '1.875rem', lineHeight: 1.25, letterSpacing: '-0.01em' },
        h3: { fontWeight: 600, fontSize: '1.5rem', lineHeight: 1.3, letterSpacing: '-0.005em' },
        h4: { fontWeight: 600, fontSize: '1.25rem', lineHeight: 1.35 },
        h5: { fontWeight: 600, fontSize: '1.125rem', lineHeight: 1.4 }, // Usado en DashboardPage title
        h6: { fontWeight: 600, fontSize: '1rem', lineHeight: 1.4 }, // Usado en AppBar/Sidebar title
        subtitle1: { fontWeight: 500, fontSize: '1rem', lineHeight: 1.5 }, // Usado en títulos de sección Paper
        subtitle2: { fontWeight: 500, fontSize: '0.875rem', color: GREY_TEXT, lineHeight: 1.5 }, // Usado en info de usuario
        body1: { fontWeight: 400, fontSize: '1rem', lineHeight: 1.5 },
        body2: { fontWeight: 400, fontSize: '0.875rem', lineHeight: 1.45 },
        button: {
            fontWeight: 600, // Botones semibold
            textTransform: 'none', // Sin mayúsculas
            fontSize: '0.9rem',
            letterSpacing: '0.01em',
        },
        caption: { fontWeight: 400, fontSize: '0.75rem', color: GREY_TEXT, lineHeight: 1.4 },
        overline: { fontWeight: 600, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.08em', color: GREY_TEXT },
    },

    // --- FORMA (BORDES) ---
    shape: {
        borderRadius: BASE_BORDER_RADIUS, // Radio de borde base
    },

    // --- SOMBRAS ---
    shadows: [
        "none",
        `0px 1px 3px ${alpha('#555E68', 0.1)}`, // Sombra muy sutil
        `0px 3px 8px ${alpha('#555E68', 0.12)}`, // Sombra base para cards/papers
        `0px 4px 12px ${alpha('#555E68', 0.14)}`,
        `0px 5px 16px ${alpha('#555E68', 0.16)}`, // Sombra media
        ...createTheme().shadows.slice(5).map((s) => // Mantener las demás sombras por defecto
            s.replace(/rgba\(0,0,0,(.*?)\)/g, (match, p1) => `rgba(85, 94, 104, ${parseFloat(p1) * 0.8})`) // Hacerlas un poco más suaves
        ),
    ],


    // --- SOBREESCRITURAS DE COMPONENTES ---
    components: {
        // Estilos globales para scrollbar
        MuiCssBaseline: {
            styleOverrides: {
                body: {
                    scrollbarColor: `${alpha(GREY_TEXT, 0.5)} ${BACKGROUND_DEFAULT}`, // Color thumb y track
                    '&::-webkit-scrollbar, & *::-webkit-scrollbar': {
                        width: '8px',
                        height: '8px',
                        backgroundColor: alpha(BACKGROUND_DEFAULT, 0.5),
                    },
                    '&::-webkit-scrollbar-thumb, & *::-webkit-scrollbar-thumb': {
                        borderRadius: 8,
                        backgroundColor: alpha(GREY_TEXT, 0.5), // Thumb más claro
                        minHeight: 24,
                        border: `2px solid ${BACKGROUND_DEFAULT}`, // Borde para efecto "flotante"
                    },
                    '&::-webkit-scrollbar-thumb:focus, & *::-webkit-scrollbar-thumb:focus': {
                        backgroundColor: alpha(GREY_TEXT, 0.7),
                    },
                    '&::-webkit-scrollbar-thumb:active, & *::-webkit-scrollbar-thumb:active': {
                        backgroundColor: alpha(GREY_TEXT, 0.8),
                    },
                    '&::-webkit-scrollbar-thumb:hover, & *::-webkit-scrollbar-thumb:hover': {
                        backgroundColor: alpha(GREY_TEXT, 0.6),
                    },
                    '&::-webkit-scrollbar-corner, & *::-webkit-scrollbar-corner': {
                        backgroundColor: BACKGROUND_DEFAULT,
                    },
                },
            },
        },
        // Botones
        MuiButton: {
            defaultProps: {
                disableElevation: true, // Sin sombra por defecto
            },
            styleOverrides: {
                root: ({ theme, ownerState }) => ({
                    fontWeight: theme.typography.button.fontWeight,
                    // Radio de borde ligeramente menor para botones
                    borderRadius: theme.shape.borderRadius * 0.75,
                    padding: ownerState.size === 'large' ? '10px 22px' : ownerState.size === 'small' ? '4px 10px' : '6px 16px', // Ajustar padding
                    transition: theme.transitions.create(['background-color', 'box-shadow', 'border-color', 'color', 'transform'], {
                        duration: theme.transitions.duration.short,
                    }),
                    '&:active': {
                        transform: 'scale(0.98)', // Efecto de clic sutil
                    }
                }),
                containedPrimary: ({ theme }) => ({
                    '&:hover': {
                        backgroundColor: theme.palette.primary.dark,
                    },
                }),
                outlined: ({ theme }) => ({
                    borderColor: alpha(theme.palette.divider, 0.8), // Borde más visible
                }),
                sizeSmall: { // Asegurar que sizeSmall tenga estilos consistentes
                    fontSize: '0.8125rem',
                    padding: '4px 10px',
                },
            }
        },
        // Inputs
        MuiTextField: {
            defaultProps: {
                variant: 'outlined',
                size: 'medium', // Tamaño por defecto
            },
        },
        MuiInputLabel: {
            styleOverrides: {
                root: ({ theme }) => ({
                    fontSize: '1rem',
                    fontWeight: 400,
                    color: theme.palette.text.secondary,
                    '&.Mui-focused': {
                        fontWeight: 500, // Medium al enfocar
                    },
                }),
                outlined: ({ theme, ownerState }) => ({ // Ajustes de posición para Outlined
                    transform: 'translate(14px, 16px) scale(1)', // Posición inicial medium
                    '&.MuiInputLabel-shrink': {
                        transform: 'translate(14px, -9px) scale(0.75)', // Posición encogida
                    },
                    ...(ownerState.size === 'small' && { // Ajuste si se usa small
                        transform: 'translate(14px, 8px) scale(1)',
                        '&.MuiInputLabel-shrink': {
                            transform: 'translate(14px, -9px) scale(0.75)',
                        },
                    }),
                }),
            }
        },
        MuiOutlinedInput: {
            styleOverrides: {
                root: ({ theme, ownerState }) => ({
                    borderRadius: theme.shape.borderRadius * 0.75, // Radio menor
                    backgroundColor: theme.palette.background.paper, // Fondo blanco
                    transition: theme.transitions.create(['border-color', 'box-shadow', 'background-color']),
                    '&:hover .MuiOutlinedInput-notchedOutline': {
                        borderColor: alpha(theme.palette.primary.main, 0.5), // Borde hover primario
                    },
                    '&.Mui-focused': { // Foco
                        '& .MuiOutlinedInput-notchedOutline': {
                            borderColor: theme.palette.primary.main,
                            borderWidth: '1px',
                        },
                        boxShadow: `0 0 0 3px ${alpha(theme.palette.primary.main, 0.15)}`, // Brillo
                    },
                    '&.Mui-disabled': { // Deshabilitado
                        backgroundColor: alpha(theme.palette.action.disabledBackground, 0.8),
                        '& .MuiOutlinedInput-notchedOutline': {
                            borderColor: alpha(theme.palette.divider, 0.8),
                        }
                    },
                    // Padding interno según tamaño
                    '.MuiInputBase-input': {
                        padding: ownerState.size === 'small' ? '8.5px 14px' : '16.5px 14px',
                    },
                }),
                notchedOutline: ({ theme }) => ({
                    borderColor: theme.palette.divider, // Borde por defecto
                    transition: theme.transitions.create('border-color'),
                }),
            }
        },
        // Paper (Cards, etc.)
        MuiPaper: {
            defaultProps: {
                elevation: 0, // Sin sombra por defecto
            },
            styleOverrides: {
                root: ({ theme }) => ({
                    backgroundColor: theme.palette.background.paper,
                    borderRadius: theme.shape.borderRadius,
                    backgroundImage: 'none', // Asegurar sin gradientes por defecto
                }),
                outlined: ({ theme }) => ({ // Variante outlined
                    border: `1px solid ${theme.palette.divider}`,
                    backgroundColor: 'transparent',
                }),
            }
        },
        // Alertas
        MuiAlert: {
            styleOverrides: {
                root: ({ theme, ownerState }) => ({
                    borderRadius: theme.shape.borderRadius * 0.75, // Radio menor
                    // Estilos por severidad
                    ...(ownerState.severity === 'error' && {
                        backgroundColor: alpha(theme.palette.error.main, 0.08), // Fondo más claro
                        color: theme.palette.error.dark,
                        '& .MuiAlert-icon': { color: theme.palette.error.main },
                    }),
                    ...(ownerState.severity === 'success' && {
                        backgroundColor: alpha(theme.palette.success.main, 0.08),
                        color: theme.palette.success.dark,
                        '& .MuiAlert-icon': { color: theme.palette.success.main },
                    }),
                    ...(ownerState.severity === 'warning' && {
                        backgroundColor: alpha(theme.palette.warning.main, 0.08),
                        color: theme.palette.warning.dark,
                        '& .MuiAlert-icon': { color: theme.palette.warning.main },
                    }),
                    ...(ownerState.severity === 'info' && {
                        backgroundColor: alpha(theme.palette.info.main, 0.08),
                        color: theme.palette.info.dark,
                        '& .MuiAlert-icon': { color: theme.palette.info.main },
                    }),
                }),
                // Estilos para variantes outlined
                outlinedError: ({ theme }) => ({
                    borderColor: alpha(theme.palette.error.main, 0.5),
                    color: theme.palette.error.dark,
                    '& .MuiAlert-icon': { color: theme.palette.error.main },
                }),
                outlinedSuccess: ({ theme }) => ({
                    borderColor: alpha(theme.palette.success.main, 0.5),
                    color: theme.palette.success.dark,
                    '& .MuiAlert-icon': { color: theme.palette.success.main },
                }),
                // ... otros outlined (warning, info si se usan)
            },
        },
        // Enlaces
        MuiLink: {
            defaultProps: {
                underline: 'hover', // Subrayado solo al pasar el ratón
            },
            styleOverrides: {
                root: ({ theme }) => ({
                    color: theme.palette.primary.main,
                    fontWeight: theme.typography.fontWeightMedium,
                    textDecorationColor: alpha(theme.palette.primary.main, 0.4), // Subrayado sutil
                    '&:hover': {
                        textDecorationColor: theme.palette.primary.main, // Subrayado normal en hover
                    },
                }),
            },
        },
        // Avatares
        MuiAvatar: {
            styleOverrides: {
                root: ({ theme }) => ({
                    fontWeight: theme.typography.fontWeightMedium,
                }),
            },
        },
        // AppBar (Navbar)
        MuiAppBar: {
            defaultProps: {
                elevation: 0, // Sin sombra por defecto
                color: 'inherit', // Hereda color, permite fondo de papel
            },
            styleOverrides: {
                root: ({ theme }) => ({
                    // Estilos base aplicados en Navbar.js con styled()
                    // Aquí podrías poner estilos que SIEMPRE apliquen a todos los AppBars
                }),
            },
        },
        // Drawer (Sidebar)
        MuiDrawer: {
            styleOverrides: {
                paper: ({ theme }) => ({
                    backgroundColor: theme.palette.background.paper,
                    borderRight: `1px solid ${theme.palette.divider}`, // Borde derecho
                    boxShadow: 'none', // Sin sombra
                }),
            },
        },
        // Tooltips
        MuiTooltip: {
            styleOverrides: {
                tooltip: ({ theme }) => ({
                    backgroundColor: alpha(theme.palette.grey[800], 0.95), // Fondo oscuro
                    borderRadius: theme.shape.borderRadius * 0.5, // Radio menor
                    fontSize: '0.75rem',
                    padding: '4px 8px', // Padding ajustado
                }),
                arrow: ({ theme }) => ({
                    color: alpha(theme.palette.grey[800], 0.95), // Color de la flecha
                }),
            },
        },
        // ListItems (Sidebar)
        MuiListItemButton: {
            styleOverrides: {
                root: ({ theme }) => ({
                    borderRadius: theme.shape.borderRadius * 0.75, // Radio menor
                    margin: '2px 8px', // Espacio vertical e horizontal
                    padding: '8px 12px', // Padding interno
                    color: theme.palette.text.secondary, // Color de texto secundario por defecto
                    '& .MuiListItemIcon-root': { // Estilo del icono
                        color: theme.palette.text.secondary, // Mismo color que el texto
                        minWidth: 'auto', // Ajustar ancho
                        marginRight: theme.spacing(1.5), // Espacio a la derecha del icono
                    },
                    '&.Mui-selected': { // Estilo cuando está seleccionado (activo)
                        backgroundColor: theme.palette.action.selected, // Usar color de selección del tema
                        color: theme.palette.primary.main, // Color primario para texto e icono
                        fontWeight: theme.typography.fontWeightMedium,
                        '& .MuiListItemIcon-root': {
                            color: theme.palette.primary.main,
                        },
                    },
                    '&:hover': {
                        backgroundColor: theme.palette.action.hover, // Usar color hover del tema
                        color: theme.palette.text.primary, // Texto primario en hover
                         '& .MuiListItemIcon-root': {
                            color: theme.palette.text.primary, // Icono primario en hover
                         },
                    },
                }),
            },
        },
        MuiListSubheader: {
            styleOverrides: {
                root: ({ theme }) => ({
                    ...theme.typography.overline, // Usar estilo overline
                    lineHeight: 'initial', // Resetear line-height
                    padding: '8px 16px', // Padding
                    marginBottom: theme.spacing(0.5), // Margen inferior
                    color: theme.palette.text.secondary, // Color secundario
                }),
            },
        },
    }
});