// src/pages/GestionEquiposPage.js
import React, { useState, useEffect, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import {
    Container,
    Typography,
    Box,
    Button,
    CircularProgress,
    Alert,
    Snackbar
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import EquipoList from '../features/equipos/components/EquipoList.js';
import AddMiembroDialog from '../features/equipos/components/AddMiembroDialog.js';
import EditRolDialog from '../features/equipos/components/EditRolDialog.js';
import * as equiposService from '../features/equipos/services/equiposService.js';
import { useProject } from '../contexts/ProjectContext.js';

const GestionEquiposPage = () => {
    const { idProyecto: idProyectoParam } = useParams();
    const idProyecto = parseInt(idProyectoParam, 10);
    const { setCurrentProjectId, refreshMembers: refreshMembersFromContext } = useProject(); // Obtener refreshMembers si existe

    const [miembros, setMiembros] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
    const [miembroParaEditar, setMiembroParaEditar] = useState(null);
    const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

    // Efecto para actualizar el contexto del proyecto (SIN CAMBIOS)
    useEffect(() => {
        if (idProyecto && !isNaN(idProyecto)) {
            console.log(`GestionEquiposPage: Setting current project ID to ${idProyecto}`);
            setCurrentProjectId(idProyecto);
        } else {
             console.log("GestionEquiposPage: Invalid or missing project ID, clearing context.");
             setCurrentProjectId(null);
        }
        return () => {
            console.log("GestionEquiposPage: Unmounting, clearing current project ID.");
            setCurrentProjectId(null);
        };
    }, [idProyecto, setCurrentProjectId]);


    // Función para cargar miembros (SIN CAMBIOS EN SU LÓGICA INTERNA, pero envuelta en useCallback)
    const cargarMiembros = useCallback(async () => {
        if (!idProyecto || isNaN(idProyecto)) {
            setError("ID de proyecto inválido.");
            setLoading(false);
            setMiembros([]); // Asegurar que esté vacío si el ID es inválido
            return;
        }
        setLoading(true);
        setError(null);
        try {
            const data = await equiposService.fetchMiembrosProyecto(idProyecto);
            setMiembros(data);
            // Opcional: Si el contexto tiene una función para refrescar, llamarla
            if (typeof refreshMembersFromContext === 'function') {
                refreshMembersFromContext();
            }
        } catch (err) {
            setError(err.message || 'Error al cargar los miembros del equipo.');
            setMiembros([]);
        } finally {
            setLoading(false);
        }
    }, [idProyecto, refreshMembersFromContext]); // Añadir refreshMembersFromContext a dependencias

    // Carga inicial (SIN CAMBIOS)
    useEffect(() => {
        if (idProyecto && !isNaN(idProyecto)) {
            cargarMiembros();
        }
    }, [cargarMiembros, idProyecto]);

    // --- Handlers para acciones CRUD (ENVUELTOS EN useCallback) ---
    const handleAddMiembro = useCallback(async (proyectoId, usuarioId, rol) => {
        // Asegurarse que el proyectoId coincide con el de la página
        if (proyectoId !== idProyecto) {
            throw new Error("Discrepancia en el ID del proyecto.");
        }
        try {
            await equiposService.addMiembroEquipo(proyectoId, usuarioId, rol);
            setSnackbar({ open: true, message: 'Miembro añadido exitosamente.', severity: 'success' });
            cargarMiembros(); // Recarga la lista
        } catch (err) {
            console.error("Error en handleAddMiembro:", err);
            setSnackbar({ open: true, message: err.message || 'Error al añadir miembro.', severity: 'error' });
            throw err; // Relanza para que el diálogo muestre su propio error
        }
    }, [idProyecto, cargarMiembros]); // Depende de idProyecto y cargarMiembros

    const handleUpdateRol = useCallback(async (proyectoId, usuarioId, nuevoRol) => {
        if (proyectoId !== idProyecto) {
            throw new Error("Discrepancia en el ID del proyecto.");
        }
        try {
            await equiposService.updateRolMiembro(proyectoId, usuarioId, nuevoRol);
            setSnackbar({ open: true, message: 'Rol actualizado exitosamente.', severity: 'success' });
            cargarMiembros();
        } catch (err) {
            console.error("Error en handleUpdateRol:", err);
            setSnackbar({ open: true, message: err.message || 'Error al actualizar rol.', severity: 'error' });
            throw err; // Relanza para el diálogo
        }
    }, [idProyecto, cargarMiembros]); // Depende de idProyecto y cargarMiembros

    const handleRemoveMiembro = useCallback(async (proyectoId, usuarioId) => {
        if (proyectoId !== idProyecto) {
             console.error("Discrepancia en el ID del proyecto al intentar eliminar.");
             setSnackbar({ open: true, message: 'Error interno al intentar eliminar.', severity: 'error' });
             return; // No continuar si los IDs no coinciden
        }
        try {
            await equiposService.removeMiembroEquipo(proyectoId, usuarioId);
            setSnackbar({ open: true, message: 'Miembro eliminado exitosamente.', severity: 'success' });
            cargarMiembros();
        } catch (err) {
            console.error("Error en handleRemoveMiembro:", err);
            setError(err.message || 'Error al eliminar miembro.'); // Mostrar error en la página
            setSnackbar({ open: true, message: err.message || 'Error al eliminar miembro.', severity: 'error' });
        }
    }, [idProyecto, cargarMiembros]); // Depende de idProyecto y cargarMiembros

    // --- Handlers para Diálogos (openEditDialog envuelto en useCallback) ---
    const openEditDialog = useCallback((miembro) => {
        setMiembroParaEditar(miembro);
        setIsEditDialogOpen(true);
    }, []); // No tiene dependencias externas

    const handleCloseSnackbar = useCallback((event, reason) => { // Envuelto en useCallback
        if (reason === 'clickaway') {
            return;
        }
        setSnackbar(prev => ({ ...prev, open: false })); // Usar forma funcional para actualizar estado
    }, []); // No tiene dependencias

    // --- Renderizado (SIN CAMBIOS SIGNIFICATIVOS) ---
    return (
        <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}> {/* Usar lg para más espacio */}
            <Typography variant="h4" component="h1" gutterBottom>
                Gestión de Equipo del Proyecto {idProyecto && !isNaN(idProyecto) ? idProyecto : '(Inválido)'}
            </Typography>

            <Box sx={{ mb: 2, display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setIsAddDialogOpen(true)}
                    disabled={loading || !!error || !idProyecto || isNaN(idProyecto)}
                >
                    Añadir Miembro
                </Button>
            </Box>

            {loading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                    <CircularProgress />
                </Box>
            )}

            {error && !loading && (
                <Alert severity="error" sx={{ mt: 2 }}>
                    {error} {idProyecto && !isNaN(idProyecto) && <Button onClick={cargarMiembros} size="small">Reintentar</Button>}
                </Alert>
            )}

            {!loading && !error && idProyecto && !isNaN(idProyecto) && (
                 miembros.length > 0 ? (
                    <EquipoList
                        miembros={miembros}
                        onEditMiembro={openEditDialog}
                        // Pasar idProyecto explícitamente si EquipoList lo necesita
                        onRemoveMiembro={(usuarioId) => handleRemoveMiembro(idProyecto, usuarioId)}
                    />
                 ) : (
                    <Typography sx={{ mt: 3, textAlign: 'center', color: 'text.secondary' }}>
                        Este proyecto aún no tiene miembros asignados.
                    </Typography>
                 )
            )}
             {!loading && !error && (!idProyecto || isNaN(idProyecto)) && (
                 <Typography sx={{ mt: 3, textAlign: 'center', color: 'text.secondary' }}>
                     No se ha especificado un ID de proyecto válido en la URL.
                 </Typography>
             )}


            {/* Diálogos */}
            {idProyecto && !isNaN(idProyecto) && (
                <>
                    <AddMiembroDialog
                        open={isAddDialogOpen}
                        onClose={() => setIsAddDialogOpen(false)}
                        onAdd={handleAddMiembro} // Pasa la función memoizada
                        idProyecto={idProyecto}
                        miembrosActuales={miembros}
                    />
                    {miembroParaEditar && (
                        <EditRolDialog
                            open={isEditDialogOpen}
                            onClose={() => setIsEditDialogOpen(false)}
                            onUpdate={handleUpdateRol} // Pasa la función memoizada
                            miembro={miembroParaEditar}
                        />
                    )}
                </>
            )}

            {/* Snackbar */}
            <Snackbar
                open={snackbar.open}
                autoHideDuration={6000}
                onClose={handleCloseSnackbar}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }} variant="filled">
                    {snackbar.message}
                </Alert>
            </Snackbar>

        </Container>
    );
};

export default GestionEquiposPage;
