// src/layouts/Sidebar.js
import React, { useState, useCallback } from 'react';
import {
    Drawer as MuiDrawer, List, ListItemButton, ListItemIcon, ListItemText,
    Divider, IconButton, Box, Typography, Tooltip, Collapse, useTheme, alpha, Avatar,
    ListSubheader,
    CircularProgress,
    Alert,
    Button,
    styled
} from '@mui/material';
import {
    Dashboard as DashboardIcon,
    Folder as FolderIcon,
    AddTask as AddTaskIcon,
    CalendarMonth as CalendarIcon,
    Settings as SettingsIcon,
    Logout as LogoutIcon,
    ExpandLess, ExpandMore,
    AccountCircle as AccountCircleIcon,
    Science as ScienceIcon,
    Groups as GroupsIcon,
    Person as PersonIcon,
    Edit as EditIcon
} from '@mui/icons-material';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext.js';
import { useProject } from '../contexts/ProjectContext.js';

// --- Componente Miembro (Fondo Oscuro) ---
const SidebarMiembroItem = ({ miembro }) => {
    const theme = useTheme();
    const textColor = theme.palette.common.white; // Texto blanco sobre fondo oscuro

    return (
        <ListItemButton dense sx={{
            pl: 3,
            py: 0.75,
            mx: 1,
            mb: 0.5,
            // borderRadius: 0, // Ya quitado de aquí
            transition: theme.transitions.create(['background-color'], {
                duration: theme.transitions.duration.short,
            }),
            '&:hover': {
                backgroundColor: alpha(theme.palette.common.white, 0.08), // Overlay blanco
            }
        }}>
            <ListItemIcon sx={{ minWidth: 28, mr: 1.5 }}>
                <Avatar
                    alt={miembro.nombre}
                    src={miembro.avatar || undefined}
                    sx={{
                        width: 24, height: 24, fontSize: '0.7rem',
                        bgcolor: alpha(textColor, 0.15), // Fondo basado en texto
                        color: textColor // Icono/Texto blanco
                    }}
                >
                    {!miembro.avatar && <PersonIcon sx={{ fontSize: '1rem' }} />}
                </Avatar>
            </ListItemIcon>
            <ListItemText
                primary={miembro.nombre}
                secondary={miembro.rol}
                primaryTypographyProps={{ variant: 'body2', fontWeight: 500, noWrap: true, color: textColor }}
                secondaryTypographyProps={{ variant: 'caption', noWrap: true, fontSize: '0.7rem', color: alpha(textColor, 0.7) }} // Secundario semi-transparente
            />
        </ListItemButton>
    );
};
// --- Fin Componente Miembro ---

// --- Componente NavItem (Fondo Oscuro) ---
const NavItem = ({ item, isSubItem = false, collapsed, showText, variant, onClose, handleNavigationAndClearProject }) => {
    const theme = useTheme();
    const textColor = theme.palette.common.white; // Texto blanco
    const selectedColor = theme.palette.primary.light; // Usar color primario claro para selección
    const handleClick = item.clearProject
        ? () => handleNavigationAndClearProject(item.path)
        : (variant === 'temporary' ? onClose : undefined);

    return (
        <Tooltip title={collapsed ? item.text : ""} placement="right" arrow>
            <ListItemButton
                component={NavLink}
                to={item.path}
                end={item.path === '/dashboard' || item.path === '/'}
                onClick={handleClick}
                sx={{
                    justifyContent: 'initial',
                    px: collapsed ? 2 : 2.5,
                    py: 1.2,
                    mb: 0.75,
                    // borderRadius: 0, // Ya quitado de aquí
                    color: alpha(textColor, 0.7), // Default semi-transparente
                    transition: theme.transitions.create(['background-color', 'color', 'padding-left'], {
                        duration: theme.transitions.duration.short,
                    }),
                    '&:hover': {
                        backgroundColor: alpha(theme.palette.common.white, 0.08), // Overlay blanco
                        color: textColor, // Texto completo en hover
                    },
                    '&.Mui-selected': {
                        backgroundColor: alpha(selectedColor, 0.12), // Fondo primario claro suave
                        color: selectedColor, // Color primario claro
                        fontWeight: 600,
                        // Indicador visual
                        '&::before': {
                            content: '""',
                            position: 'absolute',
                            left: 0,
                            top: '20%',
                            bottom: '20%',
                            width: '3px',
                            bgcolor: selectedColor,
                            // No necesitamos border radius aquí tampoco
                        },
                        '& .MuiListItemIcon-root': {
                            color: selectedColor, // Icono primario claro
                        },
                        '&:hover': {
                            backgroundColor: alpha(selectedColor, 0.18), // Hover sobre seleccionado
                        }
                    },
                    ...(isSubItem && showText && { pl: 4 }),
                }}
            >
                <ListItemIcon sx={{
                    minWidth: 0,
                    mr: showText ? 2 : 'auto',
                    justifyContent: 'center',
                    color: 'inherit',
                    transition: theme.transitions.create('color', { duration: theme.transitions.duration.short }),
                }}>
                    {React.cloneElement(item.icon, { sx: { fontSize: '1.3rem', color: 'inherit' } })}
                </ListItemIcon>
                {showText && (
                    <ListItemText
                        primary={item.text}
                        primaryTypographyProps={{
                            variant: 'body2',
                            fontWeight: 'inherit',
                            whiteSpace: 'nowrap',
                            color: 'inherit',
                            sx: { transition: 'opacity 0.2s' }
                         }}
                        sx={{ opacity: showText ? 1 : 0 }}
                    />
                  )}
            </ListItemButton>
        </Tooltip>
    );
};
// --- Fin NavItem ---


const Sidebar = ({
    drawerWidth,
    collapsedWidth,
    variant,
    open,
    collapsed,
    onClose,
    ModalProps,
}) => {
    const theme = useTheme();
    const navigate = useNavigate();
    const { user, logout } = useAuth();
    const {
        currentProjectId,
        currentProjectMembers,
        loadingMembers,
        errorMembers,
        openTeamPanel,
        setActiveProject
    } = useProject();
    const [projectsOpen, setProjectsOpen] = useState(true);

    const showText = !collapsed;
    const textColor = theme.palette.common.white; // Texto blanco

    const handleProjectsClick = useCallback(() => {
        setProjectsOpen(prev => !prev);
    }, []);

    const handleLogout = useCallback(async () => {
        await logout();
    }, [logout]);

    const getInitials = (name) => {
        if (!name) return '?';
        const names = name.split(' ');
        if (names.length === 1) return names[0][0].toUpperCase();
        return (names[0][0] + names[names.length - 1][0]).toUpperCase();
    };

    const handleNavigationAndClearProject = useCallback((path) => {
        console.log(`Sidebar: Navigating to ${path} and clearing project context.`);
        setActiveProject(null);
        if (variant === 'temporary' && onClose) {
            onClose();
        }
    }, [setActiveProject, variant, onClose]);

    const menuItems = [
        { text: 'Dashboard', icon: <DashboardIcon />, path: '/dashboard', clearProject: true },
        { text: 'Calendario', icon: <CalendarIcon />, path: '/schedule' },
    ];

    const projectSubMenuItems = [
         { text: 'Ver Proyectos', icon: <FolderIcon />, path: '/projects', clearProject: true },
         { text: 'Nuevo Proyecto', icon: <AddTaskIcon />, path: '/projects/new' },
    ];


    const drawerContent = (
        <>
            {/* Encabezado */}
            <Box sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: showText ? 'flex-start' : 'center',
                px: 1 ,
                height: '64px',
                mb: 1.5,
                bgcolor: theme.palette.background.paper
            }}>
                <Box component={NavLink} to="/" onClick={() => handleNavigationAndClearProject('/')} sx={{
                    display: 'flex',
                    alignItems: 'center',
                    textDecoration: 'none',
                    color: 'inherit',
                }}>
                    <Box
                        component="img"
                        src="/logo ito.png" // Asegúrate que el logo se vea bien en fondo oscuro
                        alt="Logo Control de Proyectos"
                        sx={{
                            height: 38,
                            width: 'auto',
                            mr: showText ? 1.5 : 0,
                            transition: theme.transitions.create(['margin']),
                        }}
                    />
                    {showText && (
                        <Typography variant="h6" noWrap sx={{
                            fontWeight: 700,
                            fontSize: '1.15rem',
                            color: 'inherit',
                            letterSpacing: '0.5px',
                            transition: 'opacity 0.2s'
                        }}>
                            Control de proyectos
                        </Typography>
                    )}
                </Box>
            </Box>

            {/* Info Usuario */}
            <Box sx={{
                textAlign: showText ? 'left' : 'center',
                px: 2, mb: 2.5, mt: 1,
                bgcolor: showText ? alpha(theme.palette.common.white, 0.05) : 'transparent',
                py: showText ? 1.5 : 0,
                // borderRadius: 0, // Ya quitado de aquí
                mx: showText ? 1.5 : 0,
                transition: theme.transitions.create(['padding', 'margin', 'background-color']),
                color: textColor, // Texto blanco
            }}>
                 <Tooltip title={collapsed && user ? (user.nombre || user.email) : ""} placement="right" arrow>
                     <Avatar sx={{
                         width: showText ? 42 : 36,
                         height: showText ? 42 : 36,
                         mb: showText ? 1 : 0.5,
                         mx: showText ? 0 : 'auto',
                         bgcolor: alpha(textColor, 0.15), // Fondo basado en texto
                         color: textColor, // Texto blanco
                         fontSize: showText ? '0.95rem' : '0.85rem',
                         fontWeight: 600,
                         border: `1.5px solid ${alpha(textColor, 0.3)}`, // Borde blanco translúcido
                         transition: theme.transitions.create(['width', 'height', 'margin', 'font-size']),
                     }}>
                         {getInitials(user?.nombre)}
                     </Avatar>
                 </Tooltip>
                {showText && (
                    <Box sx={{ transition: 'opacity 0.2s', opacity: showText ? 1 : 0 }}>
                        <Typography variant="subtitle1" noWrap sx={{ fontWeight: 600, color: 'inherit', lineHeight: 1.3 }}>
                            {user?.nombre || 'Usuario'}
                        </Typography>
                        <Typography variant="caption" color={alpha(textColor, 0.7)} noWrap>
                            {user?.email || ''}
                        </Typography>
                    </Box>
                )}
            </Box>

            {/* Lista Principal */}
            <List sx={{
                flexGrow: 1, px: 1.5,
                overflowY: 'auto', overflowX: 'hidden',
                // Scrollbar
                '&::-webkit-scrollbar': { width: '8px' },
                '&::-webkit-scrollbar-track': { bgcolor: 'transparent', },
                '&::-webkit-scrollbar-thumb': {
                    backgroundColor: alpha(textColor, 0.3), // Thumb blanco translúcido
                    borderRadius: '4px',
                    '&:hover': {
                         backgroundColor: alpha(textColor, 0.5),
                    }
                }
            }}>
                {menuItems.map((item) => (
                    <NavItem
                        key={item.text}
                        item={item}
                        collapsed={collapsed}
                        showText={showText}
                        variant={variant}
                        onClose={onClose}
                        handleNavigationAndClearProject={handleNavigationAndClearProject}
                    />
                ))}

                {/* Sección Proyectos */}
                <Tooltip title={collapsed ? "Proyectos" : ""} placement="right" arrow>
                    <ListItemButton onClick={handleProjectsClick} sx={{
                         px: collapsed ? 2 : 2.5,
                         py: 1.2, mb: 0.75,
                         // borderRadius: 0, // Ya quitado de aquí
                         color: alpha(textColor, 0.7),
                         transition: theme.transitions.create(['background-color', 'color']),
                         '&:hover': { backgroundColor: alpha(theme.palette.common.white, 0.08), color: textColor }
                    }}>
                        <ListItemIcon sx={{ minWidth: 0, mr: showText ? 2 : 'auto', justifyContent: 'center', color: 'inherit' }}>
                            <FolderIcon sx={{ fontSize: '1.3rem', color: 'inherit' }} />
                        </ListItemIcon>
                        {showText && (
                            <ListItemText primary="Proyectos" primaryTypographyProps={{ variant: 'body2', fontWeight: 500 }} sx={{ opacity: showText ? 1 : 0, color: 'inherit' }}/>
                        )}
                        {showText ? (projectsOpen ? <ExpandLess sx={{ color: textColor }}/> : <ExpandMore sx={{ color: textColor }}/>) : null}
                    </ListItemButton>
                </Tooltip>
                <Collapse in={projectsOpen && showText} timeout="auto" unmountOnExit>
                    <List component="div" disablePadding sx={{ pl: 0, pt: 0.5 }}>
                        {projectSubMenuItems.map((item) => (
                             <NavItem
                                key={item.text}
                                item={item}
                                isSubItem={true}
                                collapsed={collapsed}
                                showText={showText}
                                variant={variant}
                                onClose={onClose}
                                handleNavigationAndClearProject={handleNavigationAndClearProject}
                            />
                        ))}
                    </List>
                </Collapse>

                {/* Sección Equipo */}
                {currentProjectId && showText && (
                    <>
                        <Divider variant="middle" sx={{ my: 1.5, borderColor: alpha(textColor, 0.2) }} />
                        <List
                            subheader={
                                <ListSubheader component="div" sx={{
                                    bgcolor: 'transparent', lineHeight: '24px', mx: 1, mb: 1,
                                    fontSize: '0.8rem', fontWeight: 600,
                                    color: alpha(textColor, 0.6), // Subheader color
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.5px'
                                }}>
                                    Equipo del Proyecto
                                </ListSubheader>
                            }
                            sx={{
                                maxHeight: 'calc(100vh - 600px)',
                                overflowY: 'auto', pb: 1,
                                // Scrollbar
                                '&::-webkit-scrollbar': { width: '6px' },
                                '&::-webkit-scrollbar-track': { bgcolor: 'transparent', },
                                '&::-webkit-scrollbar-thumb': {
                                    backgroundColor: alpha(textColor, 0.25),
                                    borderRadius: '3px',
                                    '&:hover': { backgroundColor: alpha(textColor, 0.4), }
                                }
                            }}
                        >
                            {loadingMembers && ( <Box sx={{ display: 'flex', justifyContent: 'center', p: 1 }}><CircularProgress size={24} color="inherit" /></Box> )}
                            {errorMembers && !loadingMembers && ( <Alert severity="warning" variant="outlined" sx={{ mx: 1, fontSize: '0.75rem', p: '2px 8px', color: textColor, borderColor: alpha(textColor, 0.5) }}>{errorMembers}</Alert> )}
                            {!loadingMembers && !errorMembers && currentProjectMembers.length === 0 && ( <Typography variant="caption" color={alpha(textColor, 0.7)} sx={{ display: 'block', textAlign: 'center', px: 1, py: 0.5, fontStyle: 'italic' }}> No hay miembros asignados. </Typography> )}
                            {!loadingMembers && !errorMembers && currentProjectMembers.map((miembro) => ( <SidebarMiembroItem key={miembro.id_equipo || `user-${miembro.id_usuario}`} miembro={miembro} /> ))}
                        </List>
                        <Box sx={{ px: 1.5, mt: 1.5 }}>
                             <Button
                                onClick={openTeamPanel}
                                size="small"
                                fullWidth
                                variant="outlined" // Outlined
                                color="inherit" // Color blanco
                                startIcon={<GroupsIcon />}
                                disabled={!currentProjectId || loadingMembers}
                                sx={{
                                    fontSize: '0.8rem', py: 0.8,
                                    borderColor: alpha(textColor, 0.5),
                                    '&:hover': {
                                        borderColor: textColor,
                                        bgcolor: alpha(theme.palette.common.white, 0.08)
                                    }
                                }}
                             >
                                Gestionar Equipo
                             </Button>
                        </Box>
                    </>
                )}
            </List>

            {/* Sección Inferior */}
            <Box sx={{ mt: 'auto', mb: 1.5, flexShrink: 0 }}>
                 <Divider variant="middle" sx={{ my: 1.5, borderColor: alpha(textColor, 0.2) }}/>
                 <List sx={{ px: 1.5 }}>
                     <NavItem
                        item={{ text: 'Configuración', icon: <SettingsIcon />, path: '/settings' }}
                        collapsed={collapsed}
                        showText={showText}
                        variant={variant}
                        onClose={onClose}
                        handleNavigationAndClearProject={handleNavigationAndClearProject}
                     />
                     <Tooltip title={collapsed ? "Cerrar Sesión" : ""} placement="right" arrow>
                         <ListItemButton onClick={handleLogout} sx={{
                             px: collapsed ? 2 : 2.5, py: 1.2, mb: 0.5,
                             // borderRadius: 0, // Ya quitado de aquí
                             color: theme.palette.error.light, // Error claro para contraste
                             transition: theme.transitions.create(['background-color', 'color']),
                             '&:hover': {
                                 backgroundColor: alpha(theme.palette.error.dark, 0.25), // Fondo error oscuro
                                 color: theme.palette.error.light,
                             }
                         }}>
                             <ListItemIcon sx={{ minWidth: 0, mr: showText ? 2 : 'auto', justifyContent: 'center', color: 'inherit' }}>
                                 <LogoutIcon sx={{ fontSize: '1.3rem', color: 'inherit' }} />
                             </ListItemIcon>
                             {showText && (
                                <ListItemText primary="Cerrar Sesión" primaryTypographyProps={{ variant: 'body2', fontWeight: 500 }} sx={{ opacity: showText ? 1 : 0, color: 'inherit' }} />
                             )}
                         </ListItemButton>
                     </Tooltip>
                 </List>
            </Box>
        </>
    );

    // MuiDrawer Minimalista (Fondo Oscuro)
    return (
        <MuiDrawer
            variant={variant}
            open={open}
            onClose={onClose}
            ModalProps={ModalProps}
            PaperProps={{
                sx: {
                    width: collapsed ? collapsedWidth : drawerWidth,
                    transition: theme.transitions.create('width', {
                        easing: theme.transitions.easing.sharp,
                        duration: theme.transitions.duration.enteringScreen,
                    }),
                    overflowX: 'hidden',
                    display: 'flex',
                    flexDirection: 'column',
                    height: '100vh',
                    // *** Fondo Oscuro ***
                    bgcolor: theme.palette.grey[900], // O un gris oscuro de tu tema
                    borderRight: 'none',
                    boxShadow: 'none',
                    borderRadius: 0, // <--- AÑADIDO AQUÍ
                }
            }}
        >
            {drawerContent}
        </MuiDrawer>
    );
};

export default Sidebar;
