// src/features/tasks/hooks/useTareas.js
import { useState, useEffect, useCallback } from 'react';
import * as taskService from '../services/taskService.js';
import { useAuth } from '../../../contexts/AuthContext.js'; // Para obtener el token
import { isValidProjectId } from '../../../utils/validation.js'; // Para validar el ID del proyecto

// Estado inicial para el formulario de tareas
const initialFormData = {
    id_tarea: null,
    titulo: '',
    descripcion: '',
    fecha_inicio: '', // Usar string vacío para input date
    fecha_vencimiento: '', // Usar string vacío para input date
    prioridad: 'media',
    estado: 'pendiente',
    id_proyecto: null,
};

export const useTareas = (idProyectoContext = null, onAllTasksCompleted = () => {}) => {
    const [tareas, setTareas] = useState([]);
    const [loading, setLoading] = useState(false); // Solo para carga inicial de tareas
    const [error, setError] = useState(null); // Solo para error de carga inicial

    // Estados para diálogos y operaciones CUD
    const [dialogOpen, setDialogOpen] = useState(false);
    const [formData, setFormData] = useState(initialFormData);
    const [isEditing, setIsEditing] = useState(false);
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
    const [tareaToDelete, setTareaToDelete] = useState(null);
    const [operationLoading, setOperationLoading] = useState(false); // Loading para CUD
    const [operationError, setOperationError] = useState(null); // Error para CUD

    const { token } = useAuth(); // Obtiene el token del contexto de autenticación

    // Función para cargar/recargar tareas
    const cargarTareas = useCallback(async () => {
        // Siempre se necesita token para cargar tareas
        if (!token) {
            console.warn("useTareas - cargarTareas: No hay token, no se pueden cargar tareas.");
            if(tareas.length > 0) setTareas([]);
            setLoading(false);
            setError("Autenticación requerida para ver tareas.");
            return;
        }

        setLoading(true);
        setError(null);

        // Determina si buscar por proyecto específico o todas las del usuario
        const buscarPorProyecto = isValidProjectId(idProyectoContext);
        const logContext = buscarPorProyecto ? `proyecto ID ${idProyectoContext}` : 'todas del usuario';

        console.log(`useTareas - cargarTareas: Cargando tareas (${logContext})`);

        try {
            let data;
            if (buscarPorProyecto) {
                // Llama al servicio pasando el projectId.
                // taskService.getTareas usa el token internamente.
                data = await taskService.getTareas(idProyectoContext);
            } else {
                // Llama al servicio sin projectId para obtener todas las del usuario.
                // taskService.getTareas usa el token internamente.
                data = await taskService.getTareas(); // <--- LLAMADA SIN ARGUMENTOS
            }
            setTareas(data || []); // Asegura que sea un array

            // Verificar si todas las tareas están completadas (solo si se buscó por proyecto específico)
            if (buscarPorProyecto && data && data.length > 0 && data.every(t => t.estado === 'completada')) {
                console.log(`useTareas: Todas las tareas del proyecto ${idProyectoContext} están completadas.`);
                if (typeof onAllTasksCompleted === 'function') {
                    onAllTasksCompleted(idProyectoContext);
                }
            }

        } catch (err) {
            console.error(`useTareas - cargarTareas: Error cargando tareas (${logContext}):`, err);
            setError(err.message || 'Error al cargar las tareas.');
            setTareas([]); // Limpia en caso de error
        } finally {
            setLoading(false);
        }
    }, [idProyectoContext, token, onAllTasksCompleted]); // Dependencias correctas

    // Efecto para cargar tareas cuando cambia el ID del proyecto o el token
    useEffect(() => {
        if(token) {
            cargarTareas();
        } else {
            setTareas([]);
            setLoading(false);
            setError(null);
        }
    }, [cargarTareas, token]); // cargarTareas ya tiene idProyectoContext y token como dependencias

    // --- Handlers para Diálogo de Tarea (Crear/Editar) ---
    const openCreateDialog = useCallback(() => {
        // Permitir crear tarea solo si hay un proyecto seleccionado
        if (!isValidProjectId(idProyectoContext)) {
            console.error("useTareas - openCreateDialog: Intento de abrir diálogo sin ID de proyecto válido.");
            setOperationError("Se necesita seleccionar un proyecto válido para crear una tarea.");
            return;
        }
        setFormData({ ...initialFormData, id_proyecto: idProyectoContext }); // Asigna el ID del proyecto actual
        setIsEditing(false);
        setOperationError(null); // Limpia errores previos
        setDialogOpen(true);
    }, [idProyectoContext]); // Depende del ID del proyecto actual

    const openEditDialog = useCallback((tarea) => {
        if (!tarea) return;
        setFormData({
            ...tarea,
            // Asegura formato YYYY-MM-DD para inputs date
            fecha_inicio: tarea.fecha_inicio_orig || '',
            fecha_vencimiento: tarea.fecha_vencimiento_orig || '',
        });
        setIsEditing(true);
        setOperationError(null);
        setDialogOpen(true);
    }, []);

    const handleCloseDialog = useCallback(() => {
        setDialogOpen(false);
        setFormData(initialFormData); // Resetea formulario al cerrar
        setOperationError(null); // Limpia error al cerrar
    }, []);

    const handleInputChange = useCallback((event) => {
        const { name, value } = event.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    }, []);

    // Handler específico para date-fns o MUI Date Pickers si se usan
    const handleDateChange = useCallback((name, date) => {
        // Formatea a YYYY-MM-DD antes de guardar en el estado si viene de un picker
        const formattedDate = date instanceof Date && !isNaN(date)
            ? date.toISOString().split('T')[0]
            : null; // o '' si prefieres string vacío
        setFormData(prev => ({ ...prev, [name]: formattedDate }));
    }, []);

    const handleSubmit = useCallback(async (event) => {
        if (event) event.preventDefault();
        // El token se verifica internamente en el servicio
        if (!formData) {
            setOperationError("Error interno: Faltan datos del formulario.");
            return Promise.reject(new Error("Error interno: Faltan datos del formulario."));
        }

        setOperationLoading(true);
        setOperationError(null);

        try {
            let result;
            if (isEditing) {
                // Actualizar Tarea
                if (!formData.id_tarea) throw new Error("Falta ID de tarea para actualizar.");
                // taskService usa el token internamente
                result = await taskService.updateTarea(formData.id_tarea, formData);
            } else {
                // Crear Tarea
                if (!isValidProjectId(formData.id_proyecto)) throw new Error("Falta ID de proyecto para crear tarea.");
                // taskService usa el token internamente
                result = await taskService.createTarea(formData);
            }
            console.log("Resultado operación tarea:", result);
            handleCloseDialog();
            await cargarTareas(); // Recarga la lista
            return Promise.resolve(result); // Devuelve promesa resuelta
        } catch (err) {
            console.error("useTareas - handleSubmit: Error guardando tarea:", err);
            setOperationError(err.message || 'Error al guardar la tarea.');
            return Promise.reject(err); // Devuelve promesa rechazada
        } finally {
            setOperationLoading(false);
        }
    }, [formData, isEditing, cargarTareas, handleCloseDialog]); // No necesita token aquí

    // --- Handlers para Diálogo de Eliminación ---
    const openDeleteConfirm = useCallback((tarea) => {
        if (!tarea) return;
        setTareaToDelete(tarea);
        setOperationError(null); // Limpia errores previos
        setIsDeleteDialogOpen(true);
    }, []);

    const handleCloseDeleteDialog = useCallback(() => {
        setIsDeleteDialogOpen(false);
        setTareaToDelete(null);
        setOperationError(null);
    }, []);

    const handleDeleteConfirm = useCallback(async () => {
        // El token se verifica internamente en el servicio
        if (!tareaToDelete?.id_tarea) {
            setOperationError("Error interno: No hay tarea seleccionada para eliminar.");
            return Promise.reject(new Error("Error interno: No hay tarea seleccionada para eliminar."));
        }

        setOperationLoading(true);
        setOperationError(null);

        try {
            // taskService usa el token internamente
            const result = await taskService.deleteTarea(tareaToDelete.id_tarea);
            console.log("Resultado eliminación tarea:", result);
            handleCloseDeleteDialog();
            await cargarTareas(); // Recarga la lista
            return Promise.resolve(result); // Devuelve promesa resuelta
        } catch (err) {
            console.error("useTareas - handleDeleteConfirm: Error eliminando tarea:", err);
            setOperationError(err.message || 'Error al eliminar la tarea.');
            // No cierres el diálogo automáticamente en caso de error, para que el usuario vea el mensaje
            return Promise.reject(err); // Devuelve promesa rechazada
        } finally {
            setOperationLoading(false);
        }
    }, [tareaToDelete, cargarTareas, handleCloseDeleteDialog]); // No necesita token aquí

    // --- Devuelve el estado y los handlers ---
    return {
        tareas,
        loading, // Loading inicial
        error,   // Error inicial
        // Estados y handlers para diálogos y operaciones CUD
        dialogOpen,
        formData,
        isEditing,
        isDeleteDialogOpen,
        tareaToDelete,
        operationLoading, // Loading para CUD
        operationError,   // Error para CUD
        // Funciones para abrir/cerrar diálogos y manejar submits
        openCreateDialog,
        openEditDialog,
        handleCloseDialog,
        openDeleteConfirm,
        handleCloseDeleteDialog,
        handleSubmit,
        handleDeleteConfirm,
        handleInputChange,
        handleDateChange,
        // Función para recargar manualmente si es necesario
        refreshTareas: cargarTareas
    };
};
