// src/services/documentService.js
import { useAuth } from '../contexts/AuthContext.js'; // Asegúrate que la ruta sea correcta
import { useCallback } from 'react';

// Ajusta esta URL a la ubicación real de tu backend
const API_URL = 'http://localhost/xampp/back/documentos.php';

/**
 * Función helper para realizar peticiones fetch con manejo de token y errores.
 * @param {string} url - La URL del endpoint.
 * @param {object} options - Opciones para fetch (method, body, etc.).
 * @param {function} getToken - Función para obtener el token JWT.
 * @returns {Promise<any>} - Promesa que resuelve con los datos o la respuesta (para blobs).
 */
const request = async (url, options = {}, getToken) => {
    const token = typeof getToken === 'function' ? getToken() : null; // Obtiene el token actual
    const headers = {
        ...(options.headers || {}),
        ...(token && { 'Authorization': `Bearer ${token}` }),
        // NO añadir 'Content-Type': 'application/json' si el body es FormData
    };

    // Si el body NO es FormData y no hay Content-Type explícito, asumir JSON
    if (!(options.body instanceof FormData) && !headers['Content-Type']) {
        headers['Content-Type'] = 'application/json';
    }

    try {
        const response = await fetch(url, { ...options, headers });

        const contentType = response.headers.get('content-type');
        if (url.includes('?id=') && options.method !== 'DELETE' && response.ok && contentType && !contentType.includes('application/json')) {
            return response;
        }
        // --- Fin manejo especial para descargas ---

        // Para todas las demás respuestas (listas, uploads, deletes, errores), parsear JSON
        const data = await response.json();

        if (!response.ok) {
            // Lanza un error con el mensaje del backend o un mensaje genérico
            throw new Error(data.message || `Error ${response.status}: ${response.statusText}`);
        }

        return data; // Devuelve los datos JSON para operaciones exitosas

    } catch (error) {
        console.error(`Error en la petición a ${url}:`, error);
        // Re-lanzar el error para que el componente que llama pueda manejarlo
        throw error;
    }
};

// Hook para usar dentro de componentes y tener acceso fácil al token
export const useDocumentService = () => {
    const { getToken } = useAuth();

    // --- Envuelve las funciones devueltas con useCallback ---
    const getDocuments = useCallback((contextType, contextId) => {
        if (!contextId) return Promise.resolve({ success: true, documentos: [] });
        const param = contextType === 'proyecto' ? 'id_proyecto' : 'id_tarea';
        // Pasa getToken como tercer argumento
        return request(`${API_URL}?${param}=${contextId}`, { method: 'GET' }, getToken);
    }, [getToken]); // Dependencia: getToken

    const uploadDocument = useCallback((file, contextType, contextId) => {
        const formData = new FormData();
        formData.append('documento', file);
        const contextParam = contextType === 'proyecto' ? 'id_proyecto' : 'id_tarea';
        formData.append(contextParam, contextId);
        // Pasa getToken como tercer argumento
        return request(API_URL, {
            method: 'POST',
            body: formData,
        }, getToken);
    }, [getToken]); // Dependencia: getToken

    const deleteDocument = useCallback((documentId) => {
        // Pasa getToken como tercer argumento
        return request(`${API_URL}?id=${documentId}`, {
            method: 'DELETE',
        }, getToken);
    }, [getToken]); // Dependencia: getToken

    const downloadDocument = useCallback(async (documentId, filename) => {
        try {
            // Pasa getToken como tercer argumento
            const response = await request(`${API_URL}?id=${documentId}`, { method: 'GET' }, getToken);

            if (!(response instanceof Response) || !response.body) {
                 throw new Error('La respuesta del servidor no fue un archivo válido.');
            }

            const blob = await response.blob();
            const downloadUrl = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = downloadUrl;
            const contentDisposition = response.headers.get('content-disposition');
            let finalFilename = filename;
            if (contentDisposition) {
                const filenameMatch = contentDisposition.match(/filename="?(.+)"?/i);
                if (filenameMatch && filenameMatch.length > 1) {
                    finalFilename = filenameMatch[1];
                }
            }
            link.setAttribute('download', finalFilename);
            document.body.appendChild(link);
            link.click();
            link.parentNode.removeChild(link);
            window.URL.revokeObjectURL(downloadUrl);

        } catch (error) {
            console.error('Error al descargar el documento:', error);
            throw error;
        }
    }, [getToken]); // Dependencia: getToken
    // --- Fin de los wrappers useCallback ---

    // Devuelve las funciones memoizadas
    return { getDocuments, uploadDocument, deleteDocument, downloadDocument };
};