// src/features/schedule/components/ProjectDetailsPanel.js
import React, { useState, useEffect, useCallback } from 'react';
import {
    Box, Typography, Stack, useTheme, Divider,
    CircularProgress, Alert, Dialog, DialogTitle,
    DialogContent, DialogContentText, DialogActions, Button, alpha
} from '@mui/material';
import {
    CalendarMonth, Description, Label, Person,
    Timer, EventAvailable, Update, History, FolderOpenOutlined
} from '@mui/icons-material';
import { parseISO, isValid, differenceInDays, startOfDay } from 'date-fns';
import ActivityLogDisplay from './ActivityLogDisplay.js';
import { useDocumentService } from '../../../services/documentService.js';
import DocumentList from './DocumentList.js';
import DocumentUpload from './DocumentUpload.js';

// Componente DetailItem (sin cambios)
const DetailItem = ({ icon, label, value, valueComponent = null }) => (
    <Stack direction="row" spacing={1.5} alignItems="center">
        {React.cloneElement(icon, { sx: { color: 'text.secondary', fontSize: '1.1rem', flexShrink: 0 } })}
        <Stack sx={{ overflow: 'hidden' }}>
            <Typography variant="caption" color="text.secondary" noWrap>{label}</Typography>
            {valueComponent ? valueComponent : (
                <Typography variant="body2" sx={{ fontWeight: 500 }} noWrap>
                    {(value !== null && value !== undefined && value !== '') ? value :
                     <Typography component="span" variant="body2" sx={{ fontStyle: 'italic', color: 'text.disabled' }}>N/A</Typography>}
                </Typography>
            )}
        </Stack>
    </Stack>
);

const ProjectDetailsPanel = ({ project, activityLog, onLogItemClick }) => {
    const theme = useTheme();
    const { getDocuments, deleteDocument, downloadDocument, uploadDocument } = useDocumentService();
    const [documents, setDocuments] = useState([]);
    const [loadingDocs, setLoadingDocs] = useState(false);
    const [errorDocs, setErrorDocs] = useState(null);
    const [docToDelete, setDocToDelete] = useState(null);
    const [isDeletingDoc, setIsDeletingDoc] = useState(false);
    const [downloadError, setDownloadError] = useState(null);
    const projectId = project?.id_proyecto;

    // --- useEffect y Handlers (sin cambios en lógica) ---
    useEffect(() => {
        const loadDocuments = async () => {
            if (!projectId) { setDocuments([]); return; }
            setLoadingDocs(true); setErrorDocs(null); setDownloadError(null);
            try {
                const data = await getDocuments('proyecto', projectId);
                setDocuments(data.documentos || []);
            } catch (err) {
                console.error("Error fetching documents:", err);
                setErrorDocs(err.message || 'Error al cargar documentos.'); setDocuments([]);
            } finally { setLoadingDocs(false); }
        };
        loadDocuments();
    }, [projectId, getDocuments]);

    const refreshDocuments = useCallback(async () => {
        if (!projectId) { setDocuments([]); return; }
        setErrorDocs(null); setDownloadError(null);
        try {
            const data = await getDocuments('proyecto', projectId);
            setDocuments(data.documentos || []);
        } catch (err) {
            console.error("Error refreshing documents:", err);
            setErrorDocs(err.message || 'Error al refrescar documentos.');
        }
    }, [projectId, getDocuments]);

    const handleUploadSuccess = useCallback(() => { refreshDocuments(); }, [refreshDocuments]);
    const handleUploadError = useCallback((err) => { console.error("Upload failed in parent:", err); setErrorDocs(`Error en subida: ${err.message}`); }, []);
    const openDeleteConfirm = useCallback((documentId) => { setDocToDelete(documentId); }, []);
    const closeDeleteConfirm = useCallback(() => { setDocToDelete(null); setIsDeletingDoc(false); }, []);
    const handleDeleteDocument = useCallback(async () => {
        if (!docToDelete) return;
        setIsDeletingDoc(true); setErrorDocs(null);
        try {
            await deleteDocument(docToDelete);
            refreshDocuments(); closeDeleteConfirm();
        } catch (err) {
            console.error("Error deleting document:", err);
            setErrorDocs(`Error al eliminar: ${err.message}`); setIsDeletingDoc(false);
        }
    }, [docToDelete, deleteDocument, refreshDocuments, closeDeleteConfirm]);
    const handleDownloadDocument = useCallback(async (documentId, filename) => {
        setDownloadError(null);
        try { await downloadDocument(documentId, filename); }
        catch (error) { console.error("Download failed in parent:", error); setDownloadError(`Error al descargar: ${error.message}`); }
    }, [downloadDocument]);
    // --- Fin useEffect y Handlers ---

    if (!project) {
        return ( <Box sx={{ p: 3, textAlign: 'center', color: 'text.disabled', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Typography>Selecciona un proyecto para ver sus detalles y actividad.</Typography></Box> );
    }

    // --- Cálculo de Días y Datos (sin cambios) ---
    let totalDays = null, elapsedDays = null, remainingDays = null;
    const today = startOfDay(new Date());
    const startDate = project.fecha_inicio_orig ? parseISO(project.fecha_inicio_orig.includes(' ') ? project.fecha_inicio_orig.replace(' ', 'T') : project.fecha_inicio_orig) : null;
    const endDate = project.fecha_fin_orig ? parseISO(project.fecha_fin_orig.includes(' ') ? project.fecha_fin_orig.replace(' ', 'T') : project.fecha_fin_orig) : null;
    if (isValid(startDate) && isValid(endDate) && startDate <= endDate) {
        totalDays = differenceInDays(endDate, startDate) + 1;
        elapsedDays = today >= startDate ? Math.min(differenceInDays(today, startDate) + 1, totalDays) : 0;
        remainingDays = today <= endDate ? differenceInDays(endDate, today) : 0;
        if (remainingDays < 0) remainingDays = 0;
    }
    const projectName = project.nombre || 'Proyecto sin nombre';
    const projectDescription = project.descripcion || '';
    const projectStartDateDisplay = project.fecha_inicio_display || 'N/A';
    const projectEndDateDisplay = project.fecha_fin_display || 'N/A';
    const projectCreator = project.nombre_usuario_creador || 'Desconocido';
    const logEntries = activityLog?.entries;
    const loadingLog = activityLog?.loading;
    const errorLog = activityLog?.error;
    // --- Fin Cálculo de Días y Datos ---

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden', bgcolor: 'background.paper' }}> {/* Asegurar fondo */}
            {/* --- Sección Detalles Proyecto --- */}
            <Box sx={{ flexShrink: 0, borderBottom: `1px solid ${theme.palette.divider}` }}>
                <Stack spacing={2} sx={{ p: 2.5 }}> {/* Más padding */}
                    <Typography variant="h6" sx={{ fontWeight: 600, mb: 1 }}>Detalles del Proyecto</Typography>
                    <DetailItem icon={<Label />} label="Nombre" value={projectName} />
                    <DetailItem
                        icon={<Description />}
                        label="Descripción"
                        valueComponent={
                            <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                                {projectDescription || <Typography component="span" sx={{ fontStyle: 'italic', color: 'text.disabled' }}>Sin descripción</Typography>}
                            </Typography>
                        }
                    />
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={{ xs: 2, sm: 3 }}>
                        <DetailItem icon={<CalendarMonth />} label="Inicio" value={projectStartDateDisplay} />
                        <DetailItem icon={<CalendarMonth />} label="Fin" value={projectEndDateDisplay} />
                    </Stack>
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={{ xs: 2, sm: 3 }} justifyContent="space-between">
                        <DetailItem icon={<Timer />} label="Días Totales" value={totalDays !== null ? `${totalDays} día(s)` : 'N/A'} />
                        <DetailItem icon={<Update />} label="Días Transcurridos" value={elapsedDays !== null ? `${elapsedDays} día(s)` : 'N/A'} />
                        <DetailItem icon={<EventAvailable />} label="Días Faltantes" value={remainingDays !== null ? `${remainingDays} día(s)` : 'N/A'} />
                    </Stack>
                    <DetailItem icon={<Person />} label="Creado por" value={projectCreator} />
                </Stack>
            </Box>

              {/* --- Contenedor Scroll --- */}
              {/* *** Fondo ligeramente diferente para el área de scroll *** */}
              <Box sx={{
                  flexGrow: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column',
                  bgcolor: alpha(theme.palette.grey[500], 0.03), // Fondo muy sutil
                  '&::-webkit-scrollbar': { width: '6px' },
                  '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.25),  }
              }}>

                {/* --- Sección Documentos --- */}
                <Box sx={{ p: 2.5, pb: 1, flexShrink: 0 }}> {/* Más padding */}
                    <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1.5 }}> {/* Más espacio */}
                        <FolderOpenOutlined sx={{ color: 'text.secondary' }} />
                        <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>Documentos</Typography>
                    </Stack>
                    {/* Componente Upload (sin cambios) */}
                    <DocumentUpload
                        contextType="proyecto"
                        contextId={projectId}
                        onUploadSuccess={handleUploadSuccess}
                        onUploadError={handleUploadError}
                    />
                    {/* Estados y Lista (sin cambios) */}
                    {loadingDocs && <Box sx={{ display: 'flex', justifyContent: 'center', my: 2 }}><CircularProgress size={24} /></Box>}
                    {errorDocs && !loadingDocs && <Alert severity="error" sx={{ my: 1, fontSize: '0.8rem' }}>{errorDocs}</Alert>}
                    {downloadError && <Alert severity="error" sx={{ my: 1, fontSize: '0.8rem' }}>{downloadError}</Alert>}
                    {!loadingDocs && (
                        <DocumentList
                            documents={documents}
                            onDelete={openDeleteConfirm}
                            onDownload={handleDownloadDocument}
                        />
                    )}
                </Box>
                {/* --- Fin Sección Documentos --- */}

                <Divider sx={{ mx: 2.5, my: 1.5 }} /> {/* Más padding y margen */}

                {/* --- Sección Historial --- */}
                <Box sx={{ p: 2.5, pt: 1, flexShrink: 0 }}> {/* Más padding */}
                    <Stack direction="row" spacing={1.5} alignItems="center"> {/* Más espacio */}
                        <History sx={{ color: 'text.secondary' }} />
                        <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>Historial de Actividad</Typography>
                    </Stack>
                </Box>
                <Box sx={{ px: 2.5, pb: 2.5, flexGrow: 1 }}> {/* Más padding */}
                    <ActivityLogDisplay
                        entries={logEntries}
                        loading={loadingLog}
                        error={errorLog}
                        onLogItemClick={onLogItemClick}
                    />
                </Box>
                 {/* --- Fin Sección Historial --- */}

            </Box> {/* Fin Contenedor Scroll */}

            {/* --- Diálogo Confirmación Eliminación (sin cambios) --- */}
            <Dialog open={Boolean(docToDelete)} onClose={closeDeleteConfirm}>
                <DialogTitle>Confirmar Eliminación</DialogTitle>
                <DialogContent>
                    <DialogContentText>
                        ¿Estás seguro de que quieres eliminar este documento? Esta acción no se puede deshacer.
                    </DialogContentText>
                    {errorDocs && !isDeletingDoc && docToDelete && (
                         <Alert severity="error" sx={{ mt: 2 }}>{errorDocs}</Alert>
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={closeDeleteConfirm} disabled={isDeletingDoc}>Cancelar</Button>
                    <Button onClick={handleDeleteDocument} color="error" autoFocus disabled={isDeletingDoc}>
                        {isDeletingDoc ? <CircularProgress size={20} color="inherit" /> : 'Eliminar'}
                    </Button>
                </DialogActions>
            </Dialog>
            {/* --- Fin Diálogo --- */}

        </Box>
    );
};

export default ProjectDetailsPanel;
