// src/services/activityLogService.js
import apiClient from './apiClient.js'; // Asume que apiClient maneja tokens y errores

const LOGS_ENDPOINT = '/registros.php'; // Endpoint del backend PHP

/**
 * Obtiene los registros de actividad para una entidad específica o globalmente.
 * @param {string | null} entityType - El tipo de entidad ('proyectos' o 'tareas') o null para global.
 * @param {number|string | null} entityId - El ID de la entidad o null para global.
 * @returns {Promise<Array<object>>} Una promesa que resuelve con un array de registros.
 * @throws {Error} Lanza un error si la obtención falla (manejado por apiClient).
 */
export const getActivityLogByEntity = async (entityType, entityId) => {
    // Construir parámetros solo si ambos, tipo e ID, están presentes
    const params = {};
    if (entityType && entityId) {
        if (entityType !== 'proyectos' && entityType !== 'tareas') {
            console.warn(`getActivityLogByEntity: entityType inválido: ${entityType}. Debe ser 'proyectos' o 'tareas'. Fetching globalmente.`);
            // No añadir parámetros inválidos
        } else {
            params.tabla_afectada = entityType;
            params.id_registro_afectado = entityId;
            console.log(`Fetching activity log for ${entityType} ID: ${entityId}`);
        }
    } else {
        console.log(`Fetching global activity log`);
        // No se añaden parámetros, buscará todos los registros
    }


    try {
        // Llama al endpoint pasando los parámetros (vacío si es global)
        const data = await apiClient.get(LOGS_ENDPOINT, { params }); // params puede ser {}

        // Asume que la respuesta es { success: true, registros: [...] }
        if (data && data.success && Array.isArray(data.registros)) {
            return data.registros.map(log => ({
                ...log,
                fecha_cambio_dt: log.fecha_cambio ? new Date(log.fecha_cambio.replace(' ', 'T') + 'Z') : null
            }));
        } else {
            console.warn("Respuesta de API inválida o sin registros:", data?.message || data);
            return [];
        }
    } catch (error) {
        const entityInfo = entityType && entityId ? `for ${entityType} ${entityId}` : 'globally';
        console.error(`Error en activityLogService.getActivityLogByEntity ${entityInfo}:`, error.message);
        throw new Error(error.message || 'No se pudo cargar el historial de actividad.');
    }
};
