// src/pages/LoginPage.js
import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import Login from '../features/auth/components/Login.js'; // Asegúrate que la ruta sea correcta
import {
    Container,
    Box,
    Typography,
    Link as MuiLink,
    Avatar,
    Toolbar,
    AppBar,
    useTheme,
    Stack,
    CssBaseline, // Asegura estilos base consistentes
    alpha // Necesitamos alpha aquí para el fondo degradado de la página
} from '@mui/material';
import ScienceIcon from '@mui/icons-material/Science'; // Un icono más temático para "InvestigaApp"

const LoginPage = () => {
    const theme = useTheme();

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                minHeight: '100vh',
                // bgcolor: 'background.default', // El CssBaseline ya lo aplica
                // Fondo degradado muy sutil para la página completa
                background: `linear-gradient(180deg, ${alpha(theme.palette.primary.main, 0.03)} 0%, ${theme.palette.background.default} 30%)`,
            }}
        >
            <CssBaseline /> {/* Normaliza estilos y aplica fondo default */}

            {/* AppBar Minimalista y Profesional */}
            <AppBar
                position="static" // O 'sticky' si quieres que se quede fija al hacer scroll
                color="inherit" // Hereda color, permite fondo de papel
                elevation={0} // Sin sombra por defecto (definido en tema)
                sx={{
                    // backgroundColor: theme.palette.background.paper, // Aplicado por override del tema
                    // borderBottom: `1px solid ${theme.palette.divider}`, // Aplicado por override del tema
                    py: 1, // Padding vertical reducido para un look más compacto
                }}
            >
                {/* Usar Container para controlar el ancho máximo del contenido del AppBar */}
                <Container maxWidth="lg">
                    <Toolbar disableGutters sx={{ justifyContent: 'space-between' }}> {/* Quitamos padding interno y justificamos */}
                        {/* Logo y Nombre de la App */}
                        <Stack
                            direction="row"
                            alignItems="center"
                            spacing={1.5} // Espacio entre icono y texto
                            component={RouterLink} // Enlace a la página principal (si aplica)
                            to="/" // Puedes cambiar esto si la raíz no es el dashboard o si prefieres no enlazar
                            sx={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            <Box
                                component="img"
                                src="/logo ito.png" // Ruta relativa a la carpeta 'public'
                                alt="Logo Control de Proyectos"
                                sx={{
                                    height: 36, // Ajusta la altura según necesites
                                    width: 'auto',
                                    // Transición suave para el margen
                                    transition: theme.transitions.create('margin', {
                                        easing: theme.transitions.easing.sharp,
                                        duration: theme.transitions.duration.enteringScreen,
                                    }),
                                }}
                            />
                            <Typography
                                variant="h6" // Tamaño adecuado para AppBar
                                noWrap // Evita que el texto se parta en múltiples líneas
                                sx={{
                                    fontWeight: 600, // Semibold (definido en tu tema)
                                    color: 'text.primary', // Usar color de texto primario del tema
                                    letterSpacing: '0.5px', // Ligero espaciado para legibilidad
                                }}
                            >
                                InvestigApp
                            </Typography>
                        </Stack>

                        {/* Espacio reservado por si quieres añadir botones (ej: Registro) aquí en el futuro */}
                        {/* <Button component={RouterLink} to="/register" variant="outlined" size="small">Registrarse</Button> */}
                    </Toolbar>
                </Container>
            </AppBar>

            {/* Contenedor Principal del Login */}
            <Container
                component="main"
                maxWidth="xs" // Mantenemos 'xs' que es ideal para formularios de login
                sx={{
                    flexGrow: 1, // Ocupa el espacio vertical disponible
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center', // Centra verticalmente el contenido
                    alignItems: 'center', // Centra horizontalmente el contenido
                    py: { xs: 4, sm: 6, md: 8 }, // Padding vertical responsivo y aumentado
                }}
            >
                {/* *** Renderiza el componente Login *** */}
                {/* Asume que Login.js también se beneficia de los estilos del tema */}
                <Login />

                {/* Enlace a Registro */}
                <Box sx={{ mt: 4, textAlign: 'center' }}> {/* Aumentamos un poco el margen superior */}
                    <Typography variant="body2" color="text.secondary">
                        ¿Aún no tienes una cuenta?{' '}
                        <MuiLink
                            component={RouterLink}
                            to="/registro" // Asegúrate que esta ruta exista en AppRoutes.js
                            variant="body2"
                            // Estilos aplicados por override del tema (si tienes)
                            // Si no, puedes añadir sx={{ fontWeight: 500 }} o similar
                        >
                            Regístrate ahora
                        </MuiLink>
                    </Typography>
                </Box>
            </Container>

            {/* Footer Minimalista */}
            <Box
                component="footer"
                sx={{
                    py: 2.5, // Padding vertical ajustado
                    px: 2,
                    mt: 'auto', // Empuja al fondo de la página
                    bgcolor: 'transparent', // Se integra con el fondo degradado
                    textAlign: 'center'
                }}
            >
                <Typography variant="caption" color="text.secondary">
                    © {new Date().getFullYear()} Investigacion 2.
                    {' '}
                    {/* Enlaces con separador visual */}
                    {/* Asegúrate de tener rutas para /privacy y /terms si mantienes estos enlaces */}
                    <MuiLink component={RouterLink} to="/privacy" color="inherit" sx={{ textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>
                        Privacidad
                    </MuiLink>
                    {' • '} {/* Usar un punto como separador */}
                    <MuiLink component={RouterLink} to="/terms" color="inherit" sx={{ textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>
                        Términos
                    </MuiLink>
                </Typography>
            </Box>
        </Box>
    );
};

export default LoginPage;
