// src/features/auth/services/authService.js
import apiClient from '../../../services/apiClient.js'; // Asegúrate que la ruta sea correcta

/**
 * Llama al endpoint de login de la API usando el apiClient.
 * @param {string} username - El nombre de usuario o email.
 * @param {string} password - La contraseña del usuario.
 * @returns {Promise<{token: string, userInfo: object}>} Una promesa que resuelve con el token y la info del usuario.
 * @throws {Error} Lanza un error si el login falla (manejado por apiClient).
 */
export const loginUser = async (username, password) => {
    const endpoint = '/login.php'; // Ruta relativa al API_BASE_URL
    const payload = {
        username: username, // El backend espera 'username'
        password: password,
    };

    try {
        // apiClient.post maneja la solicitud y parsea la respuesta JSON
        const data = await apiClient.post(endpoint, payload);

        // Validar que la respuesta contenga los datos esperados
        // Asumiendo que tu backend devuelve un objeto con 'token' y 'user_info' en caso de éxito.
        // Ajusta los nombres ('user_info', 'id', etc.) según la respuesta real de tu API.
        if (!data || typeof data !== 'object') {
             throw new Error("Respuesta inesperada del servidor durante el login.");
        }
        if (!data.token) {
             console.error("Respuesta de login exitosa pero falta el 'token':", data);
             throw new Error("Respuesta inválida del servidor (falta token).");
        }
        if (!data.user_info || typeof data.user_info !== 'object' || !data.user_info.id) {
             // Verificamos que user_info exista, sea un objeto y contenga un 'id'
             console.error("Respuesta de login exitosa pero faltan datos del usuario ('user_info' o 'user_info.id'):", data);
             throw new Error("Respuesta inválida del servidor (faltan datos de usuario).");
        }

        // Devuelve el token y la información del usuario (que incluye el ID)
        return {
            token: data.token,
            userInfo: data.user_info, // Este objeto debe contener el ID: { id: 123, name: '...', email: '...' }
        };

    } catch (error) {
        // apiClient ya debería haber formateado el error.
        // Puedes añadir logs o relanzar.
        console.error("Error en authService.loginUser:", error.message || error);
        // Relanzar para que el componente Login pueda mostrar el mensaje.
        throw error;
    }
};

