// src/features/projects/components/Proyectos.js
import React from 'react';
import {
    List, ListItemButton, ListItemText, ListItemIcon, Typography, Box, IconButton, Menu, MenuItem, CircularProgress, Alert
} from '@mui/material';
import FolderIcon from '@mui/icons-material/Folder';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
// Quitar useProyectos si ya no se usa aquí directamente
// import { useProyectos } from '../hooks/useProjects.js';

// *** Recibe proyectos, loading y error como props ***
const Proyectos = ({
    proyectos = [], // Valor por defecto
    loading,
    error,
    selectedProjectId,
    onProjectSelect,
    onEditProject,
    onDeleteProject
}) => {
    // Estado local para el menú de acciones
    const [anchorEl, setAnchorEl] = React.useState(null);
    const [currentProject, setCurrentProject] = React.useState(null);
    const open = Boolean(anchorEl);

    // Manejadores del menú
    const handleClick = (event, proyecto) => {
        event.stopPropagation(); // Evita que el clic se propague al ListItemButton
        setAnchorEl(event.currentTarget);
        setCurrentProject(proyecto);
    };
    const handleClose = () => {
        setAnchorEl(null);
        setCurrentProject(null);
    };

    const handleEdit = () => {
        if (currentProject && onEditProject) {
            onEditProject(currentProject);
        }
        handleClose();
    };

    const handleDelete = () => {
        if (currentProject && onDeleteProject) {
            onDeleteProject(currentProject);
        }
        handleClose();
    };

    // Renderizado condicional
    if (loading) {
        return <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}><CircularProgress size={30} /></Box>;
    }
    if (error) {
        return <Alert severity="error" sx={{ m: 1 }}>{error}</Alert>;
    }
    if (!proyectos || proyectos.length === 0) {
        return <Typography sx={{ p: 2, textAlign: 'center', color: 'text.secondary' }}>No hay proyectos.</Typography>;
    }

    return (
        <>
            <List component="nav" dense sx={{ p: 0 }}>
                {proyectos.map((proyecto) => (
                    <ListItemButton
                        key={proyecto.id_proyecto}
                        selected={selectedProjectId === proyecto.id_proyecto}
                        onClick={() => onProjectSelect(proyecto.id_proyecto)}
                        sx={{
                            borderRadius: 1, // Bordes redondeados
                            mb: 0.5, // Espacio ligero entre items
                            '&.Mui-selected': {
                                // Estilos cuando está seleccionado
                                // bgcolor: 'action.selected', // Color de fondo por defecto
                                // '&:hover': { bgcolor: 'action.hover' } // Hover cuando seleccionado
                            },
                        }}
                    >
                        <ListItemIcon sx={{ minWidth: 32 }}> {/* Icono más pequeño */}
                            <FolderIcon fontSize="small" color={selectedProjectId === proyecto.id_proyecto ? "primary" : "action"} />
                        </ListItemIcon>
                        <ListItemText
                            primary={proyecto.nombre || "Proyecto sin nombre"}
                            primaryTypographyProps={{
                                noWrap: true, // Evita que el texto se desborde
                                variant: 'body2', // Tamaño de texto
                                fontWeight: selectedProjectId === proyecto.id_proyecto ? 500 : 400 // Más peso si seleccionado
                            }}
                        />
                        {/* Botón de acciones */}
                        <IconButton
                            edge="end"
                            aria-label="actions"
                            size="small"
                            onClick={(e) => handleClick(e, proyecto)}
                            sx={{ mr: -1 }} // Ajustar margen si es necesario
                        >
                            <MoreVertIcon fontSize="small" />
                        </IconButton>
                    </ListItemButton>
                ))}
            </List>

            {/* Menú de Acciones */}
            <Menu
                anchorEl={anchorEl}
                open={open}
                onClose={handleClose}
                MenuListProps={{ 'aria-labelledby': 'basic-button' }}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                transformOrigin={{ vertical: 'top', horizontal: 'right' }}
            >
                <MenuItem onClick={handleEdit} dense>
                    <ListItemIcon>
                        <EditIcon fontSize="small" />
                    </ListItemIcon>
                    <ListItemText>Editar</ListItemText>
                </MenuItem>
                <MenuItem onClick={handleDelete} dense sx={{ color: 'error.main' }}>
                    <ListItemIcon>
                        <DeleteIcon fontSize="small" color="error" />
                    </ListItemIcon>
                    <ListItemText>Eliminar</ListItemText>
                </MenuItem>
            </Menu>
        </>
    );
};

export default Proyectos;
