// src/features/projects/hooks/useProjects.js
import { useState, useEffect, useCallback } from 'react';
import * as projectService from '../services/projectService.js'; // Importa el servicio actualizado

const useProyectos = () => {
    const [proyectos, setProyectos] = useState([]);
    const [loading, setLoading] = useState(true); // Loading para la lista inicial
    const [error, setError] = useState(null); // Error al cargar la lista inicial

    // Estado para operaciones CUD (Create, Update, Delete)
    const [operationLoading, setOperationLoading] = useState(false);
    const [operationError, setOperationError] = useState(null);

    // Estado para el formulario
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [formData, setFormData] = useState(null); // null o { id_proyecto?, nombre, descripcion, fecha_inicio, fecha_fin, estado }

    // Estado para el diálogo de eliminación
    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
    const [selectedProyecto, setSelectedProyecto] = useState(null); // Proyecto a eliminar

    // Función para cargar/recargar proyectos
    const cargarProyectos = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const data = await projectService.fetchProyectos();
            setProyectos(data || []); // Asegura que sea un array
        } catch (err) {
            console.error("Error en useProyectos - cargarProyectos:", err);
            setError(err.message || 'Error al cargar los proyectos.');
            setProyectos([]); // Limpia en caso de error
        } finally {
            setLoading(false);
        }
    }, []);

    // Carga inicial
    useEffect(() => {
        cargarProyectos();
    }, [cargarProyectos]);

    // --- Handlers para Formulario ---
    const handleOpenForm = useCallback((proyecto = null) => {
        // Si es para editar, formatea las fechas para el input type="date"
        const initialData = proyecto
            ? {
                ...proyecto,
                fecha_inicio: proyecto.fecha_inicio ? proyecto.fecha_inicio.split('T')[0] : '',
                fecha_fin: proyecto.fecha_fin ? proyecto.fecha_fin.split('T')[0] : '',
              }
            : { nombre: '', descripcion: '', fecha_inicio: '', fecha_fin: '', estado: 'activo' }; // Valores por defecto para crear
        setFormData(initialData);
        setOperationError(null); // Limpia errores previos
        setIsFormOpen(true);
    }, []);

    const handleCloseForm = useCallback(() => {
        setIsFormOpen(false);
        setFormData(null);
        setOperationError(null);
    }, []);

    const handleInputChange = useCallback((event) => {
        const { name, value } = event.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    }, []);

    const handleSubmit = useCallback(async (event) => {
        event.preventDefault();
        if (!formData) return;

        setOperationLoading(true);
        setOperationError(null);

        try {
            let result;
            if (formData.id_proyecto) {
                // Actualizar
                result = await projectService.updateProyecto(formData.id_proyecto, formData);
            } else {
                // Crear
                result = await projectService.createProyecto(formData);
            }
            console.log("Resultado operación proyecto:", result);
            handleCloseForm();
            await cargarProyectos(); // Recarga la lista después de éxito
            // Devolver una promesa resuelta para encadenar .then() si es necesario
            return Promise.resolve(result);
        } catch (err) {
            console.error("Error en useProyectos - handleSubmit:", err);
            setOperationError(err.message || 'Error al guardar el proyecto.');
            // Devolver una promesa rechazada para encadenar .catch() si es necesario
            return Promise.reject(err);
        } finally {
            setOperationLoading(false);
        }
    }, [formData, handleCloseForm, cargarProyectos]);

    // --- Handlers para Diálogo de Eliminación ---
    const handleOpenDeleteDialog = useCallback((proyecto) => {
        setSelectedProyecto(proyecto);
        setOperationError(null); // Limpia errores previos
        setIsDeleteDialogOpen(true);
    }, []);

    const handleCloseDeleteDialog = useCallback(() => {
        setIsDeleteDialogOpen(false);
        setSelectedProyecto(null);
        setOperationError(null);
    }, []);

    const handleDeleteConfirm = useCallback(async () => {
        if (!selectedProyecto?.id_proyecto) return Promise.reject(new Error("No hay proyecto seleccionado para eliminar."));

        setOperationLoading(true);
        setOperationError(null);

        try {
            const result = await projectService.deleteProyecto(selectedProyecto.id_proyecto);
            console.log("Resultado eliminación proyecto:", result);
            handleCloseDeleteDialog();
            await cargarProyectos(); // Recarga la lista
            // Devolver promesa resuelta
            return Promise.resolve(result);
        } catch (err) {
            console.error("Error en useProyectos - handleDeleteConfirm:", err);
            setOperationError(err.message || 'Error al eliminar el proyecto.');
             // Devolver promesa rechazada
            return Promise.reject(err);
        } finally {
            setOperationLoading(false);
        }
    }, [selectedProyecto, handleCloseDeleteDialog, cargarProyectos]);

    // --- Handler para actualizar estado (ej. desde diálogo de finalización) ---
     const updateProjectStatus = useCallback(async (projectId, newStatus) => {
        setOperationLoading(true);
        setOperationError(null);
        try {
            const result = await projectService.updateProyecto(projectId, { estado: newStatus });
            console.log(`Estado del proyecto ${projectId} actualizado a ${newStatus}:`, result);
            await cargarProyectos(); // Recarga para reflejar el cambio
            return Promise.resolve(result);
        } catch (err) {
            console.error(`Error actualizando estado del proyecto ${projectId}:`, err);
            setOperationError(err.message || 'Error al actualizar el estado del proyecto.');
            return Promise.reject(err);
        } finally {
            setOperationLoading(false);
        }
    }, [cargarProyectos]);


    return {
        proyectos,
        loading, // Loading inicial
        error,   // Error inicial
        selectedProyecto, // Para el diálogo de eliminación
        formData,
        isFormOpen,
        isDeleteDialogOpen,
        operationLoading, // Loading para CUD
        operationError,   // Error para CUD
        handleInputChange,
        handleOpenForm,
        handleCloseForm,
        handleOpenDeleteDialog,
        handleCloseDeleteDialog,
        handleSubmit,
        handleDeleteConfirm,
        updateProjectStatus, // Exporta la función para actualizar estado
        refreshProyectos: cargarProyectos // Exporta para refrescar manualmente si es necesario
    };
};

export default useProyectos;
