// src/features/schedule/components/DocumentList.js
import React from 'react';
import {
    List, ListItem, ListItemAvatar, Avatar, ListItemText, Typography, IconButton, Tooltip, Box, Stack, alpha, useTheme
} from '@mui/material';
import {
    DescriptionOutlined, PictureAsPdfOutlined, ImageOutlined, InsertDriveFileOutlined,
    FolderZipOutlined, TableChartOutlined, SlideshowOutlined, CodeOutlined,
    DownloadForOfflineOutlined, DeleteOutline
} from '@mui/icons-material';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';

// Helper getFileIcon (sin cambios)
const getFileIcon = (mimeType) => {
    if (!mimeType) return InsertDriveFileOutlined;
    const type = mimeType.toLowerCase();
    if (type.includes('pdf')) return PictureAsPdfOutlined;
    if (type.startsWith('image/')) return ImageOutlined;
    if (type.includes('word')) return DescriptionOutlined;
    if (type.includes('spreadsheet') || type.includes('excel')) return TableChartOutlined;
    if (type.includes('presentation') || type.includes('powerpoint')) return SlideshowOutlined;
    if (type.includes('zip') || type.includes('rar')) return FolderZipOutlined;
    if (type.startsWith('text/')) return CodeOutlined;
    return InsertDriveFileOutlined;
};

// Helper formatBytes (sin cambios)
const formatBytes = (bytes, decimals = 2) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
};

const DocumentList = ({ documents = [], onDelete, onDownload }) => {
    const theme = useTheme();

    if (!documents || documents.length === 0) {
        return ( <Typography variant="body2" color="text.secondary" sx={{ mt: 2, textAlign: 'center', fontStyle: 'italic' }}> No hay documentos asociados a este proyecto. </Typography> );
    }

    return (
        <List dense sx={{ width: '100%', p: 0 }}>
            {documents.map((doc) => {
                const FileIcon = getFileIcon(doc.tipo_archivo);
                const formattedSize = formatBytes(doc.tamanio);
                let formattedDate = 'Fecha inválida';
                try {
                    const date = new Date(doc.fecha_subida);
                    if (!isNaN(date)) { formattedDate = format(date, 'dd MMM yyyy, HH:mm', { locale: es }); }
                } catch (e) { console.error("Error formatting doc date", e); }

                return (
                    <ListItem
                        key={doc.id_documento}
                        secondaryAction={
                            <Stack direction="row" spacing={0.5}>
                                <Tooltip title="Descargar">
                                    <IconButton edge="end" aria-label="descargar" onClick={() => onDownload(doc.id_documento, doc.nombre_archivo)} size="small" sx={{ '&:hover': { color: 'primary.main' } }}>
                                        <DownloadForOfflineOutlined fontSize="small" />
                                    </IconButton>
                                </Tooltip>
                                <Tooltip title="Eliminar">
                                    <IconButton edge="end" aria-label="eliminar" onClick={() => onDelete(doc.id_documento)} size="small" sx={{ '&:hover': { color: 'error.main' } }}>
                                        <DeleteOutline fontSize="small" />
                                    </IconButton>
                                </Tooltip>
                            </Stack>
                        }
                        sx={{
                            // *** Fondo ligeramente más claro que el contenedor de scroll ***
                            bgcolor: theme.palette.background.paper, // Usar fondo paper
                            mb: 1,
                            border: `1px solid ${theme.palette.divider}`, // Borde sutil
                            boxShadow: theme.shadows[1], // Sombra ligera
                            transition: theme.transitions.create(['background-color', 'box-shadow']),
                            '&:hover': {
                                bgcolor: alpha(theme.palette.action.hover, 0.04), // Hover muy sutil
                                boxShadow: theme.shadows[2], // Sombra más pronunciada en hover
                            },
                            pr: 12 // Espacio para botones
                        }}
                        disablePadding
                    >
                        <ListItemAvatar sx={{ minWidth: 40, mr: 1.5 }}> {/* Más margen */}
                            <Avatar sx={{ bgcolor: alpha(theme.palette.primary.light, 0.15), width: 36, height: 36 }}> {/* Ligeramente más grande */}
                                <FileIcon sx={{ color: 'primary.main', fontSize: '1.3rem' }} />
                            </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                            primary={ <Typography variant="body2" sx={{ fontWeight: 500, color: 'text.primary' }} noWrap> {doc.nombre_archivo} </Typography> }
                            secondary={ <Typography variant="caption" color="text.secondary"> {formattedSize} - Subido por {doc.nombre_usuario_subio || 'Sistema'} el {formattedDate} </Typography> }
                            sx={{ my: 0.5 }}
                        />
                    </ListItem>
                );
            })}
        </List>
    );
};

export default DocumentList;
