import React from 'react'; // Necesario para usar iconos MUI como componentes JSX
import { parseISO, isValid, format } from 'date-fns';
import { es } from 'date-fns/locale';
import {
    PriorityHigh as PriorityHighIcon, // Para Urgente y Alta
    Flag as FlagIcon,                 // Para Media y Baja (y default)
    CheckCircleOutline as CheckCircleOutlineIcon, // Para Completada
    Autorenew as AutorenewIcon,       // Para En Progreso (alternativa)
    RadioButtonUnchecked as RadioButtonUncheckedIcon, // Para Pendiente
    HelpOutline as HelpIcon,          // Icono por defecto para estado
    ErrorOutline
} from '@mui/icons-material';

