// --- Funciones de Formato de Fecha ---

/**
 * Formatea una cadena de fecha (ej. 'YYYY-MM-DD') para mostrarla al usuario.
 * @param {string | null | undefined} dateString - La cadena de fecha.
 * @returns {string} - La fecha formateada (ej. '15 Abr 24') o 'N/A' o 'Inválida'.
 */
export const formatDateForDisplay = (dateString) => {
    if (!dateString) return 'N/A';
    try {
        const date = parseISO(dateString); // date-fns parsea YYYY-MM-DD correctamente
        return isValid(date) ? format(date, 'd MMM yy', { locale: es }) : 'Inválida';
    } catch (error) {
        console.error("Error formateando fecha para display:", dateString, error);
        return 'Inválida';
    }
};

/**
 * Formatea una cadena de fecha para usarla en un input[type="date"].
 * @param {string | null | undefined} dateString - La cadena de fecha.
 * @returns {string} - La fecha en formato 'YYYY-MM-DD' o ''.
 */
export const formatDateForInput = (dateString) => {
    if (!dateString) return '';
    try {
        const date = parseISO(dateString);
        return isValid(date) ? format(date, 'yyyy-MM-dd') : '';
    } catch (error) {
        console.error("Error formateando fecha para input:", dateString, error);
        return '';
    }
};

/**
 * Formatea una cadena de fecha simple (ej. '15 Abr 2024').
 * @param {string | null | undefined} dateString - La cadena de fecha.
 * @returns {string} - La fecha formateada o 'N/A'.
 */
export const formatSimpleDate = (dateString) => {
  if (!dateString) return 'N/A';
  try {
    const date = parseISO(dateString);
    return isValid(date) ? format(date, 'dd MMM yyyy', { locale: es }) : 'N/A';
  } catch (error) {
    console.error("Error formateando fecha simple:", dateString, error);
    return 'N/A';
  }
};


// --- Funciones para Obtener Iconos ---

/**
 * Devuelve el componente de icono MUI correspondiente a la prioridad.
 * @param {string} prioridad - La clave de prioridad ('baja', 'media', 'alta', 'urgente').
 * @returns {JSX.Element} - El componente de icono.
 */
export const getPrioridadIcon = (prioridad) => {
    // Usar fontSize="inherit" permite que el tamaño se controle donde se usa el icono.
    switch (prioridad?.toLowerCase()) {
        case 'urgente':
            return <PriorityHighIcon fontSize="inherit" color="error" />;
        case 'alta':
            return <PriorityHighIcon fontSize="inherit" color="warning" />; // Mismo icono, diferente color
        case 'media':
            return <FlagIcon fontSize="inherit" color="info" />;
        case 'baja':
            return <FlagIcon fontSize="inherit" color="success" />;
        default:
            return <FlagIcon fontSize="inherit" color="disabled" />; // Icono por defecto más neutral
    }
};

/**
 * Devuelve el componente de icono MUI correspondiente al estado.
 * @param {string} estado - La clave de estado ('pendiente', 'en_progreso', 'completada').
 * @returns {JSX.Element} - El componente de icono.
 */
export const getEstadoIcon = (estado) => {
    switch (estado?.toLowerCase()) {
        case 'completada':
            return <CheckCircleOutlineIcon fontSize="inherit" color="success" />;
        case 'en_progreso':
            return <AutorenewIcon fontSize="inherit" color="info" />; // Usar Autorenew para progreso
        case 'pendiente':
            return <RadioButtonUncheckedIcon fontSize="inherit" color="action" />; // Gris acción
        case 'bloqueada': // Si se usa
             return <ErrorOutline fontSize="inherit" color="error" />;
        default:
            return <HelpIcon fontSize="inherit" color="disabled" />; // Icono por defecto
    }
};


// --- Función de Ordenamiento ---

/**
 * Ordena un array de tareas según prioridad (descendente) y luego fecha de vencimiento (ascendente).
 * @param {Array<object>} tasks - El array de objetos de tarea. Cada tarea debe tener 'prioridad' y 'fecha_vencimiento_orig'.
 * @returns {Array<object>} - El array de tareas ordenado.
 */
export const sortTasks = (tasks) => {
    // Clonar el array para no mutar el original
    return [...tasks].sort((a, b) => {
        // 1. Prioridad (Urgente > Alta > Media > Baja > Default)
        const prioridadOrder = { urgente: 4, alta: 3, media: 2, baja: 1, default: 0 };
        // Asegurarse de manejar casos donde la prioridad no esté definida o sea inválida
        const prioA = prioridadOrder[a.prioridad?.toLowerCase()] ?? prioridadOrder.default;
        const prioB = prioridadOrder[b.prioridad?.toLowerCase()] ?? prioridadOrder.default;

        if (prioA !== prioB) {
            return prioB - prioA; // Mayor prioridad numérica (más importante) primero
        }

        // 2. Fecha de Vencimiento (Ascendente - más próximas primero)
        // Usar la fecha original guardada en el hook useTareas
        const dateA = a.fecha_vencimiento_orig ? parseISO(a.fecha_vencimiento_orig) : null;
        const dateB = b.fecha_vencimiento_orig ? parseISO(b.fecha_vencimiento_orig) : null;
        const isValidA = dateA && isValid(dateA);
        const isValidB = dateB && isValid(dateB);

        // Lógica de comparación de fechas:
        // - Fechas válidas se comparan entre sí.
        // - Tareas con fecha válida van antes que las sin fecha o con fecha inválida.
        // - Tareas sin fecha o con fecha inválida mantienen su orden relativo entre ellas.
        if (isValidA && isValidB) {
             if (dateA.getTime() !== dateB.getTime()) {
                return dateA.getTime() - dateB.getTime(); // Más temprana primero
             }
        } else if (isValidA) {
            return -1; // a (con fecha) va antes que b (sin fecha)
        } else if (isValidB) {
            return 1;  // b (con fecha) va antes que a (sin fecha)
        }

        // 3. Si tienen misma prioridad y misma fecha (o ninguna), mantener orden original relativo
        return 0;
    });
};
