// src/pages/Registro.js
import React, { useState, useCallback } from 'react';
import { useNavigate, Link as RouterLink } from 'react-router-dom';
import {
    Container,
    Box,
    Typography,
    TextField,
    Button,
    CircularProgress,
    Alert,
    Link as MuiLink,
    AppBar,
    Toolbar,
    Stack,
    CssBaseline,
    alpha,
    useTheme,
    Avatar // Importa Avatar
} from '@mui/material';
import PersonAddIcon from '@mui/icons-material/PersonAdd'; // Icono relevante para registro

// Importa la función del servicio
import { registerUser } from '../features/auth/services/userService.js'; // Ajusta la ruta si es necesario

// *** Renombrado a RegistroPage ***
function RegistroPage() {
    const [nombre, setNombre] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);
    const navigate = useNavigate();
    const theme = useTheme();

    const handleSubmit = useCallback(async (event) => {
        event.preventDefault();
        setError(null);
        setSuccess(null);

        if (!nombre || !email || !password || !confirmPassword) {
            setError('Todos los campos son obligatorios.');
            return;
        }
        if (password !== confirmPassword) {
            setError('Las contraseñas no coinciden.');
            return;
        }
        if (password.length < 6) {
            setError('La contraseña debe tener al menos 6 caracteres.');
            return;
        }

        setLoading(true);

        try {
            // Usa la función del servicio
            const userData = { nombre, email, password };
            // registerUser usa apiClient internamente y maneja errores
            const result = await registerUser(userData);

            setSuccess(result.message || '¡Usuario registrado exitosamente!');
            setNombre('');
            setEmail('');
            setPassword('');
            setConfirmPassword('');

            setTimeout(() => {
                navigate('/login');
            }, 2000);

        } catch (err) {
            console.error("Error en el registro:", err);
            // El error ya viene formateado desde apiClient/registerUser
            setError(err.message || 'No se pudo completar el registro. Inténtalo de nuevo.');
        } finally {
            setLoading(false);
        }
    }, [nombre, email, password, confirmPassword, navigate]);

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                minHeight: '100vh',
                background: `linear-gradient(180deg, ${alpha(theme.palette.primary.main, 0.03)} 0%, ${theme.palette.background.default} 30%)`,
            }}
        >
            <CssBaseline />

            <AppBar
                position="static"
                color="inherit"
                elevation={0}
                sx={{ py: 1 }}
            >
                <Container maxWidth="lg">
                    <Toolbar disableGutters sx={{ justifyContent: 'space-between' }}>
                        <Stack
                            direction="row"
                            alignItems="center"
                            spacing={1.5}
                            component={RouterLink}
                            to="/"
                            sx={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            <Box
                                component="img"
                                src="/logo ito.png"
                                alt="Logo InvestigApp"
                                sx={{ height: 36, width: 'auto' }}
                            />
                            <Typography
                                variant="h6"
                                noWrap
                                sx={{ fontWeight: 600, color: 'text.primary', letterSpacing: '0.5px' }}
                            >
                                InvestigApp
                            </Typography>
                        </Stack>
                         <Button component={RouterLink} to="/login" variant="outlined" size="small">
                            Iniciar Sesión
                         </Button>
                    </Toolbar>
                </Container>
            </AppBar>

            <Container
                component="main"
                maxWidth="xs"
                sx={{
                    flexGrow: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    alignItems: 'center',
                    py: { xs: 4, sm: 6 },
                }}
            >
                <Stack alignItems="center" spacing={2} sx={{ mb: 4 }}>
                    <Avatar sx={{ bgcolor: 'primary.main' }}>
                        <PersonAddIcon />
                    </Avatar>
                    <Typography component="h1" variant="h5" sx={{ fontWeight: 500 }}>
                        Crear Nueva Cuenta
                    </Typography>
                </Stack>

                <Box component="form" onSubmit={handleSubmit} noValidate sx={{ width: '100%' }}>
                    {error && (
                        <Alert severity="error" sx={{ width: '100%', mb: 2 }}>
                            {error}
                        </Alert>
                    )}
                    {success && (
                        <Alert severity="success" sx={{ width: '100%', mb: 2 }}>
                            {success}
                        </Alert>
                    )}

                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        id="nombre"
                        label="Nombre Completo"
                        name="nombre"
                        autoComplete="name"
                        autoFocus
                        value={nombre}
                        onChange={(e) => setNombre(e.target.value)}
                        disabled={loading || !!success}
                    />
                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        id="email"
                        label="Correo Electrónico"
                        name="email"
                        autoComplete="email"
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        disabled={loading || !!success}
                    />
                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        name="password"
                        label="Contraseña"
                        type="password"
                        id="password"
                        autoComplete="new-password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        disabled={loading || !!success}
                        helperText="Mínimo 6 caracteres"
                    />
                    <TextField
                        margin="normal"
                        required
                        fullWidth
                        name="confirmPassword"
                        label="Confirmar Contraseña"
                        type="password"
                        id="confirmPassword"
                        autoComplete="new-password"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        disabled={loading || !!success}
                        error={!!confirmPassword && password !== confirmPassword}
                        helperText={!!confirmPassword && password !== confirmPassword ? "Las contraseñas no coinciden" : ""}
                    />
                    <Button
                        type="submit"
                        fullWidth
                        variant="contained"
                        sx={{ mt: 3, mb: 2, py: 1.2 }}
                        disabled={loading || !!success}
                    >
                        {loading ? <CircularProgress size={24} color="inherit" /> : 'Registrarme'}
                    </Button>

                    <Box sx={{ mt: 2, textAlign: 'center' }}>
                        <Typography variant="body2" color="text.secondary">
                            ¿Ya tienes una cuenta?{' '}
                            <MuiLink component={RouterLink} to="/login" variant="body2">
                                Inicia Sesión aquí
                            </MuiLink>
                        </Typography>
                    </Box>
                </Box>
            </Container>

            <Box
                component="footer"
                sx={{
                    py: 2.5,
                    px: 2,
                    mt: 'auto',
                    bgcolor: 'transparent',
                    textAlign: 'center'
                }}
            >
                <Typography variant="caption" color="text.secondary">
                    © {new Date().getFullYear()} Investigacion 2.
                    {' '}
                    <MuiLink component={RouterLink} to="/privacy" color="inherit" sx={{ textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>
                        Privacidad
                    </MuiLink>
                    {' • '}
                    <MuiLink component={RouterLink} to="/terms" color="inherit" sx={{ textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>
                        Términos
                    </MuiLink>
                </Typography>
            </Box>
        </Box>
    );
}

// *** Renombrado a RegistroPage ***
export default RegistroPage;
