// src/features/auth/services/userService.js
import apiClient from '../../../services/apiClient.js'; // Asegúrate que la ruta sea correcta

/**
 * Llama al endpoint de registro de usuarios (POST a usuarios.php).
 * @param {object} userData - Datos del usuario { nombre, email, password }.
 * @returns {Promise<object>} Una promesa que resuelve con la respuesta del backend (ej: { success: true, message: '...', id_usuario: ... }).
 * @throws {Error} Lanza un error si el registro falla (manejado por apiClient).
 */
export const registerUser = async (userData) => {
    const endpoint = '/usuarios.php'; // Endpoint para crear usuarios
    const payload = {
        nombre: userData.nombre,
        email: userData.email,
        password: userData.password,
    };

    try {
        // apiClient.post maneja la solicitud POST y parsea la respuesta JSON
        // No se necesita token para el registro
        const data = await apiClient.post(endpoint, payload);

        // Validar la respuesta del backend (asumiendo { success: true, message: ..., id_usuario: ... })
        if (!data || typeof data !== 'object') {
            throw new Error("Respuesta inesperada del servidor durante el registro.");
        }
        // El backend devuelve 201 Created en éxito, apiClient lo maneja como OK.
        // Verificamos 'success' por si acaso.
        if (data.success === false) {
             console.error("Registro fallido según el backend:", data);
             throw new Error(data.message || "Error desconocido durante el registro.");
        }
        if (!data.id_usuario) {
             console.error("Respuesta de registro exitosa pero falta 'id_usuario':", data);
             // Podría ser un éxito parcial, pero es mejor tratarlo como error si esperas el ID
             throw new Error("Respuesta inválida del servidor (falta ID de usuario).");
        }

        // Devuelve la respuesta completa del backend
        return data;

    } catch (error) {
        // apiClient ya debería haber formateado el error (incluyendo status y message)
        console.error("Error en userService.registerUser:", error.message || error);
        // Relanzar para que el componente RegistroPage pueda mostrar el mensaje.
        throw error;
    }
};

