import { getToken } from '../../../utils/auth.js'; // <--- IMPORTA DESDE UTILS

// Asegúrate que esta URL apunte correctamente a tu script PHP
const API_URL = 'http://localhost/xampp/back/proyectos.php'; // ¡AJUSTA ESTA URL!

/**
 * Helper para manejar respuestas Fetch y errores comunes.
 * @param {Response} response - La respuesta de fetch.
 * @returns {Promise<any>} - Promesa que resuelve con los datos JSON si es exitoso.
 * @throws {Error} - Lanza un error con el mensaje del backend o un mensaje genérico.
 */
const handleResponse = async (response) => {
    const contentType = response.headers.get("content-type");
    let result;
    // Intenta parsear JSON incluso si no es 'ok', ya que el backend envía errores en JSON
    if (contentType && contentType.indexOf("application/json") !== -1) {
        try {
            result = await response.json();
        } catch (jsonError) {
             // Si falla el parseo de JSON, intenta obtener texto
             console.error("Error parseando JSON, intentando obtener texto:", jsonError);
             const text = await response.text();
             result = { success: false, message: text || `Error ${response.status}: ${response.statusText} (Respuesta no JSON)` };
             // Lanzar un error aquí es opcional, pero ayuda a detener el flujo si la respuesta es inesperada
             const error = new Error(result.message);
             error.status = response.status;
             error.result = result;
             throw error;
        }
    } else {
        // Si no es JSON, intenta obtener texto
        const text = await response.text();
        result = { success: false, message: text || `Error ${response.status}: ${response.statusText} (Content-Type no JSON)` };
        // Considera lanzar un error aquí también si esperas siempre JSON
        const error = new Error(result.message);
        error.status = response.status;
        error.result = result;
        throw error;
    }

    if (!response.ok) {
        // Usa el mensaje del backend si está disponible, si no, usa el statusText
        const errorMessage = result?.message || `Error ${response.status}: ${response.statusText}`;
        console.error(`Error ${response.status}: ${errorMessage}`, result); // Loguea el error completo
        const error = new Error(errorMessage);
        error.status = response.status; // Añade el status al objeto Error
        error.result = result; // Añade el resultado completo por si se necesita más info
        throw error;
    }

    // Si la respuesta es OK pero el backend indica fallo (ej. success: false)
    if (result && result.success === false) {
        console.error("Error lógico del backend:", result);
        const error = new Error(result.message || 'El servidor indicó un error inesperado.');
        error.status = response.status; // Puede ser 200 OK pero con success: false
        error.result = result;
        throw error;
    }

    return result; // Devuelve el objeto JSON completo (ej: { success: true, proyectos: [...] })
};

/**
 * Obtiene todos los proyectos asociados al usuario autenticado.
 * @returns {Promise<Array>} - Promesa que resuelve con la lista de proyectos.
 */
export const fetchProyectos = async () => {
    const token = getToken(); // Usa la función importada del AuthContext
    if (!token) {
        console.error("fetchProyectos: No autorizado. Token no encontrado.");
        // Considera si deberías lanzar un error específico para redirección o manejo global
        throw new Error('No autorizado. Token no encontrado.');
    }

    const response = await fetch(API_URL, {
        method: 'GET',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json', // Indica que esperamos JSON
        },
    });
    const data = await handleResponse(response);
    return data.proyectos || []; // Devuelve la lista de proyectos del resultado
};

/**
 * Obtiene los detalles de un proyecto específico por ID.
 * @param {number | string} idProyecto - El ID del proyecto.
 * @returns {Promise<Object|null>} - Promesa que resuelve con los datos del proyecto o null si no se encuentra.
 */
export const fetchProyectoById = async (idProyecto) => {
    const token = getToken();
    if (!token) {
        console.error("fetchProyectoById: No autorizado. Token no encontrado.");
        throw new Error('No autorizado. Token no encontrado.');
    }
    // Validación más robusta del ID
    const parsedId = parseInt(idProyecto, 10);
    if (isNaN(parsedId) || parsedId <= 0) {
        console.error("fetchProyectoById: ID de proyecto inválido:", idProyecto);
        throw new Error('ID de proyecto inválido.');
    }


    const response = await fetch(`${API_URL}?id_proyecto=${parsedId}`, { // Usa el ID parseado
        method: 'GET',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json',
        },
    });
    const data = await handleResponse(response);
    // Asegurarse de que devuelve un objeto o null si no se encuentra
    return data.proyecto || null;
};

/**
 * Crea un nuevo proyecto.
 * @param {Object} proyectoData - Datos del proyecto ({ nombre, descripcion, fecha_inicio, fecha_fin, estado? }).
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend (incluyendo el nuevo ID).
 */
export const createProyecto = async (proyectoData) => {
    const token = getToken();
    if (!token) {
        console.error("createProyecto: No autorizado. Token no encontrado.");
        throw new Error('No autorizado. Token no encontrado.');
    }

    // Validación básica de datos requeridos
    if (!proyectoData || !proyectoData.nombre || !proyectoData.fecha_inicio || !proyectoData.fecha_fin) {
        console.error("createProyecto: Datos incompletos.", proyectoData);
        throw new Error("Faltan datos requeridos para crear el proyecto (nombre, fecha inicio, fecha fin).");
    }

    // Función auxiliar para formatear fecha
    const formatDate = (date) => {
        if (date instanceof Date) {
            return date.toISOString().split('T')[0];
        }
        // Intenta parsear si es string, asumiendo formato YYYY-MM-DD o similar
        if (typeof date === 'string') {
            try {
                const parsed = new Date(date);
                // Verifica si es una fecha válida antes de formatear
                if (!isNaN(parsed.getTime())) {
                    return parsed.toISOString().split('T')[0];
                }
            } catch (e) {
                 console.warn(`createProyecto: No se pudo parsear la fecha '${date}'. Usando valor original.`);
            }
        }
        return date; // Devuelve original si no es Date o string parseable
    };


    // Asegúrate de que las fechas estén en formato YYYY-MM-DD
    const dataToSend = {
        ...proyectoData,
        fecha_inicio: formatDate(proyectoData.fecha_inicio),
        fecha_fin: formatDate(proyectoData.fecha_fin),
        // Asegura un estado por defecto si no se proporciona
        estado: proyectoData.estado || 'activo'
    };

    const response = await fetch(API_URL, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json',
        },
        body: JSON.stringify(dataToSend),
    });
    return handleResponse(response); // Devuelve la respuesta completa del backend
};

/**
 * Actualiza un proyecto existente.
 * @param {number | string} idProyecto - El ID del proyecto a actualizar.
 * @param {Object} proyectoData - Datos a actualizar.
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend.
 */
export const updateProyecto = async (idProyecto, proyectoData) => {
    const token = getToken();
    if (!token) {
        console.error("updateProyecto: No autorizado. Token no encontrado.");
        throw new Error('No autorizado. Token no encontrado.');
    }
    const parsedId = parseInt(idProyecto, 10);
    if (isNaN(parsedId) || parsedId <= 0) {
        console.error("updateProyecto: ID de proyecto inválido:", idProyecto);
        throw new Error('ID de proyecto inválido para actualizar.');
    }
    if (!proyectoData || Object.keys(proyectoData).length === 0) {
        console.warn("updateProyecto: No se proporcionaron datos para actualizar.");
        // Devolver un éxito simulado para no romper flujos que esperan una promesa resuelta
        return Promise.resolve({ success: true, message: 'No se proporcionaron datos para actualizar.' });
    }

    // Función auxiliar para formatear fecha (igual que en create)
    const formatDate = (date) => {
        if (date instanceof Date) {
            return date.toISOString().split('T')[0];
        }
        if (typeof date === 'string') {
             try {
                const parsed = new Date(date);
                if (!isNaN(parsed.getTime())) {
                    return parsed.toISOString().split('T')[0];
                }
            } catch (e) {
                 console.warn(`updateProyecto: No se pudo parsear la fecha '${date}'. Usando valor original.`);
            }
        }
        return date;
    };

    // Asegúrate de que las fechas estén en formato YYYY-MM-DD si se incluyen
    const dataToSend = { ...proyectoData };
    if (dataToSend.hasOwnProperty('fecha_inicio')) { // Solo formatea si la propiedad existe
        dataToSend.fecha_inicio = formatDate(dataToSend.fecha_inicio);
    }
    if (dataToSend.hasOwnProperty('fecha_fin')) { // Solo formatea si la propiedad existe
        dataToSend.fecha_fin = formatDate(dataToSend.fecha_fin);
    }

    const response = await fetch(`${API_URL}?id_proyecto=${parsedId}`, { // Usa el ID parseado
        method: 'PUT',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json',
        },
        body: JSON.stringify(dataToSend),
    });
    return handleResponse(response);
};

/**
 * Elimina un proyecto.
 * @param {number | string} idProyecto - El ID del proyecto a eliminar.
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend.
 */
export const deleteProyecto = async (idProyecto) => {
    const token = getToken();
    if (!token) {
        console.error("deleteProyecto: No autorizado. Token no encontrado.");
        throw new Error('No autorizado. Token no encontrado.');
    }
    const parsedId = parseInt(idProyecto, 10);
    if (isNaN(parsedId) || parsedId <= 0) {
        console.error("deleteProyecto: ID de proyecto inválido:", idProyecto);
        throw new Error('ID de proyecto inválido para eliminar.');
    }

    const response = await fetch(`${API_URL}?id_proyecto=${parsedId}`, { // Usa el ID parseado
        method: 'DELETE',
        headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json',
        },
    });
    // DELETE puede devolver 204 No Content sin cuerpo, pero tu PHP devuelve JSON
    // handleResponse debería funcionar bien aquí.
    return handleResponse(response);
};
