// src/features/equipos/services/equiposService.js
import apiClient from '../../../services/apiClient.js'; // Ajusta la ruta si es necesario

const EQUIPOS_ENDPOINT = '/equipos.php'; // Endpoint relativo a API_BASE_URL

/**
 * Obtiene los miembros de un proyecto específico.
 * @param {number} idProyecto - El ID del proyecto.
 * @returns {Promise<Array<object>>} Una promesa que resuelve con la lista de miembros.
 */
export const fetchMiembrosProyecto = async (idProyecto) => {
    if (!idProyecto) throw new Error('ID de proyecto es requerido');
    try {
        // apiClient.get maneja la construcción de la URL con query params
        const data = await apiClient.get(EQUIPOS_ENDPOINT, {
            params: { id_proyecto: idProyecto }
        });
        // Asume respuesta { success: true, miembros: [...] }
        if (data?.success && Array.isArray(data.miembros)) {
            return data.miembros;
        } else {
            console.warn("fetchMiembrosProyecto: Respuesta inválida o sin miembros:", data?.message || data);
            return []; // Devuelve array vacío si no hay éxito o datos
        }
    } catch (error) {
        console.error(`Error fetching members for project ${idProyecto}:`, error.message || error);
        // Relanza el error formateado por apiClient
        throw error;
    }
};

/**
 * Añade un nuevo miembro a un equipo.
 * @param {number} idProyecto - ID del proyecto.
 * @param {number} idUsuario - ID del usuario a añadir.
 * @param {string} rol - Rol del nuevo miembro ('lider', 'colaborador', 'observador').
 * @returns {Promise<object>} Una promesa que resuelve con los datos del miembro añadido.
 */
export const addMiembroEquipo = async (idProyecto, idUsuario, rol) => {
    if (!idProyecto || !idUsuario || !rol) {
        throw new Error('ID de proyecto, ID de usuario y rol son requeridos');
    }
    const payload = {
        id_proyecto: idProyecto,
        id_usuario: idUsuario,
        rol: rol,
    };
    try {
        const data = await apiClient.post(EQUIPOS_ENDPOINT, payload);
        // Asume respuesta { success: true, id_equipo: ..., ... }
        if (data?.success) {
            return data; // Devuelve toda la respuesta exitosa
        } else {
            // apiClient ya debería lanzar error si success es false o hay error HTTP
            // Este else es una salvaguarda por si acaso
            throw new Error(data?.message || 'Error desconocido al añadir miembro.');
        }
    } catch (error) {
        console.error(`Error adding member ${idUsuario} to project ${idProyecto}:`, error.message || error);
        throw error;
    }
};

/**
 * Actualiza el rol de un miembro del equipo.
 * @param {number} idProyecto - ID del proyecto.
 * @param {number} idUsuario - ID del usuario cuyo rol se actualiza.
 * @param {string} nuevoRol - El nuevo rol.
 * @returns {Promise<object>} Una promesa que resuelve con la respuesta de éxito.
 */
export const updateRolMiembro = async (idProyecto, idUsuario, nuevoRol) => {
    if (!idProyecto || !idUsuario || !nuevoRol) {
        throw new Error('ID de proyecto, ID de usuario y nuevo rol son requeridos');
    }
    const payload = { rol: nuevoRol };
    try {
        // El PUT necesita identificar el recurso en la URL (query params) y el cambio en el body
        const data = await apiClient.put(EQUIPOS_ENDPOINT, payload, {
            params: { id_proyecto: idProyecto, id_usuario: idUsuario }
        });
        // Asume respuesta { success: true, message: '...' }
        if (data?.success) {
            return data;
        } else {
            throw new Error(data?.message || 'Error desconocido al actualizar rol.');
        }
    } catch (error) {
        console.error(`Error updating role for member ${idUsuario} in project ${idProyecto}:`, error.message || error);
        throw error;
    }
};

/**
 * Elimina un miembro de un equipo.
 * @param {number} idProyecto - ID del proyecto.
 * @param {number} idUsuario - ID del usuario a eliminar.
 * @returns {Promise<object>} Una promesa que resuelve con la respuesta de éxito.
 */
export const removeMiembroEquipo = async (idProyecto, idUsuario) => {
    if (!idProyecto || !idUsuario) {
        throw new Error('ID de proyecto y ID de usuario son requeridos');
    }
    try {
        // DELETE necesita identificar el recurso en la URL (query params)
        const data = await apiClient.delete(EQUIPOS_ENDPOINT, {
            params: { id_proyecto: idProyecto, id_usuario: idUsuario }
        });
        // Asume respuesta { success: true, message: '...' } o 204 No Content (apiClient devuelve { success: true })
        if (data?.success) {
            return data;
        } else {
            throw new Error(data?.message || 'Error desconocido al eliminar miembro.');
        }
    } catch (error) {
        console.error(`Error removing member ${idUsuario} from project ${idProyecto}:`, error.message || error);
        throw error;
    }
};


