// src/routes/AppRoutes.js
import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';

// Importa Layouts y Componentes de Ruta
import DashboardLayout from '../layouts/DashboardLayout.js';
import ProtectedRoute from './ProtectedRoute.js';
import PublicRoute from './PublicRoute.js';

// Importa Páginas
import LoginPage from '../pages/LoginPage.js';
import RegistroPage from '../pages/Registro.js'; // <-- Ya está importando RegistroPage
import DashboardPage from '../pages/DashboardPage.js';
import GestionEquiposPage from '../pages/GestionEquiposPage.js';
// import ProjectDetailsPage from '../pages/ProjectDetailsPage';
// NO importes NotFoundPage si no existe

const AppRoutes = () => {
  return (
    <Routes>

      {/* --- Rutas Públicas (Solo para usuarios NO autenticados) --- */}
      <Route element={<PublicRoute />}>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/registro" element={<RegistroPage />} /> {/* <-- Ya usa RegistroPage */}
      </Route>

      {/* --- Rutas Protegidas (Solo para usuarios autenticados) --- */}
      <Route element={<ProtectedRoute />}>
        {/* Rutas que usan el DashboardLayout */}
        <Route element={<DashboardLayout />}>
          <Route path="/dashboard" element={<DashboardPage />} />
          <Route path="/gestion-equipos/:idProyecto" element={<GestionEquiposPage />} /> {/* Asegúrate que la ruta incluya el ID */}
          {/* Agrega aquí otras rutas que necesiten el DashboardLayout */}

          {/* Redirección por defecto dentro de las rutas protegidas */}
          <Route path="/" element={<Navigate to="/dashboard" replace />} />

        </Route> {/* Fin de rutas que usan DashboardLayout */}

      </Route> {/* Fin de Rutas Protegidas */}

      {/* --- Fallback Route --- */}
      <Route path="*" element={<Navigate to="/login" replace />} />

    </Routes>
  );
};

export default AppRoutes;
