// src/features/tasks/services/taskService.js
import { parseISO, isValid, format } from 'date-fns';
import { es } from 'date-fns/locale';
// Importa las funciones de validación desde el archivo de utilidades
import { isValidProjectId, isValidTaskId } from '../../../utils/validation.js';
// Importa getToken para la autorización
import { getToken } from '../../../utils/auth.js';

// Define la URL base de tu API PHP (ajusta si es necesario)
const API_BASE_URL = 'http://localhost/xampp/back'; // Ajusta si es necesario
const TASKS_ENDPOINT = `${API_BASE_URL}/tareas.php`;

/**
 * Función helper para manejar las respuestas de fetch (sin cambios respecto a la versión anterior)
 */
const handleApiResponse = async (response) => {
    const contentType = response.headers.get("content-type");
    let data;

    if (contentType && contentType.indexOf("application/json") !== -1) {
        try {
            data = await response.json();
        } catch (jsonError) {
            // Si falla el parseo pero la respuesta es OK (ej. 204 No Content), es éxito sin datos.
            if (response.ok && response.status === 204) {
                return { success: true, message: 'Operación exitosa (No Content).', status: 204 };
            }
            // Si falla el parseo y NO es OK, lanzar error.
            if (!response.ok) {
                 const errorText = await response.text().catch(() => 'No se pudo leer el cuerpo del error.');
                 throw new Error(`Error HTTP ${response.status}: ${response.statusText}. Respuesta no JSON: ${errorText}`);
            }
            // Si falla el parseo pero SÍ es OK (y no 204), es raro, pero podría pasar.
            // Devolver un error o un mensaje genérico.
             throw new Error(`Respuesta OK pero JSON inválido: ${jsonError.message} (Status: ${response.status})`);
        }
    } else if (response.ok && response.status === 204) {
         // Éxito sin contenido JSON
         return { success: true, message: 'Operación exitosa (No Content).', status: 204 };
    } else if (!response.ok) {
        // Error HTTP y no es JSON
        const errorText = await response.text().catch(() => 'No se pudo leer el cuerpo del error.');
        throw new Error(`Error HTTP ${response.status}: ${response.statusText}. ${errorText}`);
    } else {
        // Respuesta OK pero no es JSON (y no 204) - considerar si esto es un error o no.
        // Por ahora, lo tratamos como éxito con advertencia.
        data = { success: true, message: 'Respuesta recibida pero no es JSON.', status: response.status };
    }

    // Si la respuesta fue OK pero el backend indica fallo explícito
    if (response.ok && data && data.success === false) {
        const error = new Error(data.message || `Error ${response.status}: Operación fallida según el backend.`);
        error.status = response.status;
        error.data = data; // Adjunta los datos completos del error
        throw error;
    }

    // Si la respuesta NO fue OK (ya manejado parcialmente arriba, pero doble check)
    if (!response.ok) {
        // Usa el mensaje del JSON si existe, si no, el statusText
        const error = new Error(data?.message || `Error HTTP ${response.status}: ${response.statusText}`);
        error.status = response.status;
        error.data = data; // Adjunta los datos completos del error
        throw error;
    }

    // Añade el status a la data exitosa para posible referencia
    if (data) {
        data.status = response.status;
    }

    return data; // Devuelve la data parseada y validada
};


/**
 * Obtiene tareas. Requiere token.
 * Solo puede obtener una tarea específica (si se provee taskId)
 * O todas las tareas de un proyecto específico (si se provee projectId).
 * NO puede obtener todas las tareas de todos los proyectos.
 * @param {string | null} [projectId=null] - ID del proyecto para filtrar (opcional).
 * @param {string | null} [taskId=null] - ID de la tarea específica a obtener (opcional, tiene precedencia).
 * @returns {Promise<Array>} - Promesa que resuelve con un array de tareas procesadas.
 */
export const getTareas = async (projectId = null, taskId = null) => {
    const token = getToken(); // Obtiene el token
    if (!token) {
        console.error('getTareas: No autorizado: Token no encontrado.');
        throw new Error('No autorizado: Token no encontrado.');
    }

    let url = TASKS_ENDPOINT;
    const headers = {
        'Authorization': `Bearer ${token}`, // <--- Añade cabecera de autorización
        'Accept': 'application/json'
    };
    const params = new URLSearchParams();
    let logContext = 'todas del usuario'; // Contexto inicial

    // Determina qué parámetro añadir a la URL
    if (isValidTaskId(taskId)) {
        params.append('id_tarea', taskId);
        logContext = `tarea ID ${taskId}`;
    } else if (isValidProjectId(projectId)) {
        params.append('id_proyecto', projectId);
        logContext = `proyecto ID ${projectId}`;
    }

    const queryString = params.toString();
    // Siempre habrá queryString si pasamos la validación anterior
    
    if(queryString) {
        url += `?${queryString}`;
    }
    console.log(`taskService (getTareas): Fetching tareas (${logContext}) from ${url}`);

    try {
        const response = await fetch(url, { method: 'GET', headers: headers });
        const data = await handleApiResponse(response);

        let tareasData = [];
        // El backend devuelve 'tarea' para una sola, 'tareas' para una lista
        if (isValidTaskId(taskId)) {
            // Espera un objeto 'tarea'
            tareasData = (data && data.success && data.tarea) ? [data.tarea] : [];
            if (tareasData.length === 0 && data?.success) { // Verifica data.success por si la respuesta fue 200 OK pero sin 'tarea'
                console.warn(`taskService (fetch): Tarea con ID ${taskId} no encontrada.`);
            }
        } else {
            // Espera un array 'tareas'
            tareasData = (data && data.success && Array.isArray(data.tareas)) ? data.tareas : [];
        }
        // Si no es ni por taskId ni por projectId, tareasData permanecerá vacío

        // Mapeo y procesamiento de datos (sin cambios)
        return tareasData.map(tarea => ({
            ...tarea,
            id_tarea: parseInt(tarea.id_tarea, 10),
            id_proyecto: tarea.id_proyecto ? parseInt(tarea.id_proyecto, 10) : null,
            fecha_inicio_orig: tarea.fecha_inicio,
            fecha_vencimiento_orig: tarea.fecha_vencimiento,
            fecha_inicio_display: tarea.fecha_inicio && isValid(parseISO(tarea.fecha_inicio))
                ? format(parseISO(tarea.fecha_inicio), 'd MMM yy', { locale: es }) : 'N/A',
            fecha_vencimiento_display: tarea.fecha_vencimiento && isValid(parseISO(tarea.fecha_vencimiento))
                ? format(parseISO(tarea.fecha_vencimiento), 'd MMM yy', { locale: es }) : 'N/A',
            prioridad: tarea.prioridad?.toLowerCase() || 'media',
            estado: tarea.estado?.trim().toLowerCase().replace(/\s+/g, '_') || 'pendiente',
            nombre_proyecto: tarea.nombre_proyecto || 'N/A', // Nombre del proyecto viene del JOIN en PHP
        }));

    }   catch (error) {
        console.error(`taskService (getTareas): Error fetching tareas (${logContext}):`, error.message, error.status ? `(Status: ${error.status})` : '', error.data ? error.data : '');
        throw error; // Relanza el error para que el hook lo maneje
    }
};

/**
 * Crea una nueva tarea. Requiere token.
 * @param {Object} tareaData - Datos de la tarea a crear.
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend.
 */
export const createTarea = async (tareaData) => {
    const token = getToken();
    if (!token) {
        throw new Error('No autorizado: Token no encontrado.');
    }

    // Validación crucial: id_proyecto es requerido por el backend
    if (!isValidProjectId(tareaData?.id_proyecto)) {
        throw new Error("ID de proyecto inválido o faltante al crear tarea.");
    }

    const url = TASKS_ENDPOINT;
    const headers = {
        'Authorization': `Bearer ${token}`, // <--- Añade cabecera de autorización
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    };

    // Asegura que las fechas estén en formato YYYY-MM-DD si son Date objects
    const formatDate = (date) => {
        if (date instanceof Date) return date.toISOString().split('T')[0];
        return date; // Asume que ya es string YYYY-MM-DD o null/undefined
    };

    const payload = {
        titulo: tareaData.titulo,
        descripcion: tareaData.descripcion,
        fecha_inicio: formatDate(tareaData.fecha_inicio) || null, // Asegura null si está vacío
        fecha_vencimiento: formatDate(tareaData.fecha_vencimiento), // Requerido por backend
        prioridad: tareaData.prioridad || 'media', // Default si no viene
        estado: tareaData.estado || 'pendiente', // Default si no viene
        id_proyecto: tareaData.id_proyecto, // Requerido
    };

    console.log("taskService (createTarea): Creating task with payload:", payload);

    try {
        const response = await fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(payload) });
        const data = await handleApiResponse(response);
        // El backend devuelve id_tarea en éxito
        if (!data.id_tarea) {
            // Si success es true pero falta id_tarea, es un error inesperado
            throw new Error(data.message || "Respuesta inválida al crear tarea (falta ID).");
        }
        return data; // Devuelve la respuesta completa del backend { success: true, message: ..., id_tarea: ... }
    } catch (error) {
        console.error("taskService (fetch): Error creating tarea:", error.message, error.status ? `(Status: ${error.status})` : '', error.data ? error.data : '');
        throw error;
    }
};

/**
 * Actualiza una tarea existente. Requiere token.
 * @param {string | number} idTarea - ID de la tarea a actualizar.
 * @param {Object} tareaData - Datos de la tarea a actualizar.
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend.
 */
export const updateTarea = async (idTarea, tareaData) => {
    const token = getToken();
    if (!token) {
        throw new Error('No autorizado: Token no encontrado.');
    }

    if (!isValidTaskId(idTarea)) {
        throw new Error("ID de tarea inválido para actualizar.");
    }

    const url = `${TASKS_ENDPOINT}?id_tarea=${idTarea}`; // ID en la URL para PUT
    const headers = {
        'Authorization': `Bearer ${token}`, // <--- Añade cabecera de autorización
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    };

    // Asegura que las fechas estén en formato YYYY-MM-DD si son Date objects
    const formatDate = (date) => {
        if (date instanceof Date) return date.toISOString().split('T')[0];
        return date;
    };

    // Payload solo con los campos permitidos por el backend para PUT
    const payload = {
        titulo: tareaData.titulo,
        descripcion: tareaData.descripcion,
        fecha_inicio: formatDate(tareaData.fecha_inicio) || null,
        fecha_vencimiento: formatDate(tareaData.fecha_vencimiento),
        prioridad: tareaData.prioridad,
        estado: tareaData.estado,
        // id_proyecto NO se puede cambiar según el backend
    };

    console.log(`taskService (updateTarea): Updating task ID ${idTarea} with payload:`, payload);

    try {
        const response = await fetch(url, { method: 'PUT', headers: headers, body: JSON.stringify(payload) });
        const data = await handleApiResponse(response);
        // PUT exitoso devuelve { success: true, message: ... }
        return data;
    } catch (error) {
        console.error(`taskService (fetch): Error updating tarea ID ${idTarea}:`, error.message, error.status ? `(Status: ${error.status})` : '', error.data ? error.data : '');
        throw error;
    }
};

/**
 * Elimina una tarea existente. Requiere token.
 * @param {string | number} idTarea - ID de la tarea a eliminar.
 * @returns {Promise<Object>} - Promesa que resuelve con la respuesta del backend.
 */
export const deleteTarea = async (idTarea) => {
    const token = getToken();
    if (!token) {
        throw new Error('No autorizado: Token no encontrado.');
    }

    if (!isValidTaskId(idTarea)) {
        throw new Error("ID de tarea inválido para eliminar.");
    }

    const url = `${TASKS_ENDPOINT}?id_tarea=${idTarea}`; // ID en la URL para DELETE
    const headers = {
        'Authorization': `Bearer ${token}`, // <--- Añade cabecera de autorización
        'Accept': 'application/json' // Aunque DELETE puede no devolver cuerpo, aceptar JSON por si hay error
    };

    console.log(`taskService (deleteTarea): Deleting task ID ${idTarea}`);

    try {
        const response = await fetch(url, { method: 'DELETE', headers: headers });
        // DELETE exitoso puede devolver 204 No Content o un JSON { success: true, ... }
        const data = await handleApiResponse(response);
        return data;
    } catch (error) {
        console.error(`taskService (fetch): Error deleting tarea ID ${idTarea}:`, error.message, error.status ? `(Status: ${error.status})` : '', error.data ? error.data : '');
        throw error;
    }
};
