// src/features/schedule/components/ScheduleProjectHeader.js
import React from 'react';
import { Stack, Typography, Chip, LinearProgress, Tooltip, Box, alpha, useTheme } from '@mui/material';
import EventIcon from '@mui/icons-material/Event'; // Icono por defecto si falta en urgencyInfo

const ScheduleProjectHeader = ({ projectDetails, urgencyInfo, progress }) => {
    const theme = useTheme();

    // Validar datos esenciales
    if (!projectDetails) {
        console.warn("ScheduleProjectHeader: Falta projectDetails.");
        return null;
    }
    // Si falta urgencyInfo, usar valores por defecto
    const safeUrgencyInfo = urgencyInfo || { colorName: 'grey', label: 'Desconocido', icon: EventIcon };

    const { colorName, label: urgencyLabel, icon: UrgencyIcon } = safeUrgencyInfo;

    // Obtener colores del tema de forma segura
    let mainColor = theme.palette.primary.main;
    let darkColor = theme.palette.primary.dark;
    let contrastTextColor = theme.palette.primary.contrastText; // Para el icono dentro del chip

    if (colorName === 'default' || colorName === 'grey') {
        mainColor = theme.palette.grey[500];
        darkColor = theme.palette.grey[700];
        contrastTextColor = theme.palette.getContrastText(mainColor);
    } else if (theme.palette[colorName]) {
        mainColor = theme.palette[colorName].main;
        darkColor = theme.palette[colorName].dark || mainColor; // Fallback a main si dark no existe
        contrastTextColor = theme.palette[colorName].contrastText || theme.palette.getContrastText(mainColor);
    }

    // Formatear progreso para mostrar
    const displayProgress = Math.round(progress || 0);

    return (
        // Usar Box con estilos similares a un Paper pero con color basado en urgencia
        <Box
            sx={{
                p: 1.5,
                 // Usar radio del tema
                bgcolor: alpha(mainColor, 0.08), // Fondo basado en color de urgencia
                border: `1px solid ${alpha(mainColor, 0.3)}` // Borde basado en color de urgencia
            }}
        >
            <Stack spacing={1.5}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1} flexWrap="wrap">
                    <Tooltip title={projectDetails.descripcion || projectDetails.nombre || "Detalles del proyecto"} arrow>
                        <Typography variant="h6" sx={{ fontWeight: 600, color: darkColor, flexGrow: 1, minWidth: 150, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {projectDetails.nombre || "Proyecto sin nombre"}
                        </Typography>
                    </Tooltip>
                    <Chip
                        // Asegurarse que UrgencyIcon es un componente válido
                        icon={UrgencyIcon ? <UrgencyIcon sx={{ fontSize: '1rem !important', color: `${darkColor} !important` }} /> : undefined}
                        label={urgencyLabel}
                        size="small"
                        sx={{
                            bgcolor: alpha(mainColor, 0.15), // Fondo más intenso
                            color: darkColor, // Texto oscuro
                            fontWeight: 500,
                            height: 24, // Ligeramente más alto
                            fontSize: '0.75rem', // Un poco más grande
                            borderRadius: theme.shape.borderRadius * 0.75, // Radio consistente
                            flexShrink: 0,
                            // Estilos para el icono dentro del chip
                            '& .MuiChip-icon': {
                                color: `${darkColor} !important`, // Asegurar color del icono
                                marginLeft: '6px', // Ajustar margen
                                marginRight: '-4px',
                            }
                        }}
                    />
                </Stack>
                <Tooltip title={`Progreso estimado: ${projectDetails.fecha_inicio_display || 'N/A'} - ${projectDetails.fecha_fin_display || 'N/A'} (${displayProgress}%)`} arrow>
                    <Stack direction="row" spacing={1.5} alignItems="center">
                        <LinearProgress
                            variant="determinate" value={displayProgress}
                            sx={{
                                flexGrow: 1, height: 8, borderRadius: 4, // Más gruesa y redondeada
                                backgroundColor: alpha(mainColor, 0.2),
                                '& .MuiLinearProgress-bar': {
                                    backgroundColor: mainColor,
                                    borderRadius: 4,
                                }
                            }}
                        />
                        <Typography variant="body2" sx={{ fontWeight: 600, color: darkColor, flexShrink: 0 }}>
                            {displayProgress}%
                        </Typography>
                    </Stack>
                </Tooltip>
            </Stack>
        </Box>
    );
};

export default ScheduleProjectHeader;
