// src/contexts/AuthContext.js
import React, { createContext, useState, useContext, useEffect, useCallback, useMemo } from 'react';
import apiClient from '../services/apiClient.js'; // Asegúrate que la ruta sea correcta
import { setToken as saveToken, removeToken as deleteToken, getToken as retrieveToken } from '../utils/auth.js'; // Asegúrate que la ruta sea correcta

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
    // Inicializa el token desde localStorage al cargar
    const [token, setToken] = useState(() => retrieveToken());
    const [user, setUser] = useState(null);
    // isLoading ahora refleja la verificación inicial del token
    const [isLoading, setIsLoading] = useState(true);
    const [authError, setAuthError] = useState(null); // Para errores específicos de autenticación

    const login = useCallback(async (newToken, userInfo) => {
        // *** CORRECCIÓN AQUÍ: Cambiar id_usuario por id ***
        // Verifica que userInfo exista y tenga la propiedad 'id'
        if (!newToken || !userInfo || !userInfo.id) {
            console.error("AuthContext: Intento de login con datos inválidos.", { newToken, userInfo });
            setAuthError("Datos de inicio de sesión inválidos.");
            return false; // El login falla si los datos no son válidos
        }
        console.log("AuthContext: Logueando usuario:", userInfo);
        saveToken(newToken); // Guarda en localStorage
        setToken(newToken); // Actualiza estado
        setUser(userInfo); // Actualiza estado
        setAuthError(null); // Limpia errores previos
        setIsLoading(false); // El usuario está autenticado
        return true; // Indica que el login fue exitoso en el contexto
    }, []); // No necesita dependencias si solo usa argumentos

    const logout = useCallback(() => {
        console.log("AuthContext: Deslogueando usuario.");
        deleteToken(); // Elimina de localStorage
        setToken(null); // Limpia estado
        setUser(null); // Limpia estado
        setAuthError(null); // Limpia errores
        setIsLoading(false); // Termina cualquier posible estado de carga pendiente
    }, []);

    // Función para obtener el token actual
    const getCurrentToken = useCallback(() => {
        return token;
    }, [token]);

    // Efecto para verificar el token al cargar la aplicación
    useEffect(() => {
        let isMounted = true;
        const verifyAuth = async () => {
            const currentTokenInStorage = retrieveToken();

            if (!currentTokenInStorage) {
                console.log("AuthContext: No hay token en storage, terminando carga inicial de auth.");
                if (isMounted) {
                    setIsLoading(false);
                    setUser(null);
                    setToken(null);
                }
                return;
            }

            console.log("AuthContext: Verificando token existente con /me.php...");
            setAuthError(null);

            try {
                // Llamar a /me.php
                const response = await apiClient.get('/me.php');

                // Esperar la estructura { success: true, user_info: {...} }
                const userInfo = response?.user_info;

                // Verificar 'id' dentro de user_info (según /me.php)
                if (!userInfo || typeof userInfo !== 'object' || !userInfo.id) {
                    console.error("AuthContext: Respuesta inválida o incompleta desde /me.php. Datos recibidos:", response);
                    throw new Error("Información de usuario inválida recibida del servidor.");
                }

                console.log("AuthContext: Verificación con /me.php exitosa. Usuario:", userInfo);

                if (isMounted && retrieveToken() === currentTokenInStorage) {
                    setUser(userInfo); // Establece el usuario desde user_info
                    setToken(currentTokenInStorage);
                } else if (isMounted) {
                    console.warn("AuthContext: El token cambió durante la verificación o componente desmontado. Ignorando resultado.");
                }
            } catch (error) {
                console.error("AuthContext: Error durante la verificación del token con /me.php.", error.message || error);
                if (isMounted) {
                    logout();
                    setAuthError(`Error de autenticación: ${error.message || 'No se pudo verificar la sesión.'}`);
                }
            } finally {
                if (isMounted) {
                    setIsLoading(false);
                }
            }
        };

        verifyAuth();

        return () => {
            isMounted = false;
        };
    }, [logout]); // Dependencia de logout

    // Memoizar el valor del contexto
    const value = useMemo(() => ({
        user,
        // *** CORRECCIÓN AQUÍ: Usar 'id' del objeto user (que viene de user_info) ***
        userId: user?.id,
        token,
        isAuthenticated: !!user && !!token,
        isLoading,
        authError,
        login,
        logout,
        getToken: getCurrentToken
    }), [user, token, isLoading, authError, login, logout, getCurrentToken]);

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};

// Hook para consumir el contexto
export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined || context === null) {
        throw new Error('useAuth debe ser usado dentro de un AuthProvider');
    }
    return context;
};
