// src/features/projects/components/ProyectoFormulario.js
import React from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Grid,
    CircularProgress,
    Typography,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Alert,
    Box,
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';
import { useTheme } from '@mui/material/styles';

// Nota: selectedProyecto viene del hook y ya tiene las fechas en formato yyyy-MM-dd
const ProyectoFormulario = ({
    open,
    onClose,
    onSubmit,
    proyectoData,
    onInputChange,
    isCreating,
    loading, // operationLoading del hook
    error,   // operationError del hook
}) => {
    const theme = useTheme();

    // Si no hay datos de proyecto (p.ej. al cerrar), no renderizar contenido del form
    if (!proyectoData) return null;

    const handleDialogClose = (event, reason) => {
        if (loading && reason === 'backdropClick') {
            // Prevent closing on backdrop click while loading
            return;
        }
        if (!loading) {
            onClose();
        }
    };

    return (
        <Dialog
            open={open}
            onClose={handleDialogClose} // Use custom handler
            fullWidth
            maxWidth="sm"
            PaperProps={{
                component: 'form',
                onSubmit: onSubmit,
            }}
            aria-labelledby="project-form-dialog-title"
        >
            <DialogTitle sx={{
                borderBottom: `1px solid ${theme.palette.divider}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                py: 1.5, // Keep specific padding if needed for title height
                px: 2.5
            }} id="project-form-dialog-title">
                <Typography variant="h6" fontWeight="600">
                    {isCreating ? 'Crear Nuevo Proyecto' : 'Editar Proyecto'}
                </Typography>
                <IconButton onClick={onClose} size="small" disabled={loading} aria-label="Cerrar diálogo">
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent dividers sx={{ px: theme.spacing(3), py: theme.spacing(2) }}> {/* Consistent padding */}
                 {/* Mostrar error de operación si existe */}
                 {error && (
                    <Alert severity="error" sx={{ mb: 2 }}>
                        {error}
                    </Alert>
                 )}
                {/* pt: 1 removed as dividers prop adds padding */}
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            required
                            label="Nombre del proyecto"
                            name="nombre"
                            value={proyectoData.nombre || ''}
                            onChange={onInputChange}
                            margin="dense" // Keep dense if preferred for forms
                            variant="outlined"
                            disabled={loading}
                            autoFocus // Enfocar el primer campo al abrir
                        />
                    </Grid>
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            multiline
                            rows={3}
                            label="Descripción"
                            name="descripcion"
                            value={proyectoData.descripcion || ''}
                            onChange={onInputChange}
                            margin="dense"
                            variant="outlined"
                            disabled={loading}
                        />
                    </Grid>
                    <Grid item xs={12} sm={6}>
                        <TextField
                            fullWidth
                            required
                            label="Fecha Inicio"
                            type="date"
                            name="fecha_inicio"
                            value={proyectoData.fecha_inicio || ''} // Directamente del estado
                            onChange={onInputChange}
                            InputLabelProps={{ shrink: true }}
                            margin="dense"
                            variant="outlined"
                            disabled={loading}
                        />
                    </Grid>
                    <Grid item xs={12} sm={6}>
                        <TextField
                            fullWidth
                            required
                            label="Fecha Fin"
                            type="date"
                            name="fecha_fin"
                            value={proyectoData.fecha_fin || ''} // Directamente del estado
                            onChange={onInputChange}
                            InputLabelProps={{ shrink: true }}
                            margin="dense"
                            variant="outlined"
                            disabled={loading}
                        />
                    </Grid>
                    <Grid item xs={12}>
                        <FormControl fullWidth margin="dense" variant="outlined" disabled={loading}>
                            <InputLabel id="estado-select-label">Estado</InputLabel>
                            <Select
                                labelId="estado-select-label"
                                label="Estado"
                                name="estado"
                                value={proyectoData.estado || 'activo'} // Valor por defecto 'activo'
                                onChange={onInputChange}
                            >
                                <MenuItem value="activo">Activo</MenuItem>
                                <MenuItem value="pausado">Pausado</MenuItem>
                                <MenuItem value="completado">Completado</MenuItem>
                                {/* Añadir más estados si es necesario */}
                            </Select>
                        </FormControl>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ p: theme.spacing(2), borderTop: `1px solid ${theme.palette.divider}` }}> {/* Consistent padding */}
                <Button onClick={onClose} disabled={loading} color="inherit"> {/* Use inherit for cancel */}
                    Cancelar
                </Button>
                <Button
                    type="submit"
                    variant="contained"
                    disabled={loading}
                    startIcon={loading ? <CircularProgress size={20} color="inherit" /> : null}
                >
                    {loading ? 'Guardando...' : (isCreating ? 'Crear Proyecto' : 'Guardar Cambios')}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default ProyectoFormulario;
