// src/layouts/DashboardLayout.js
import React, { useState, useCallback } from 'react';
import { Outlet } from 'react-router-dom';
import {
    Box,
    CssBaseline,
    useMediaQuery,
    styled,
    useTheme,
    alpha // Necesario para el scrollbar
} from '@mui/material';
import Sidebar from './Sidebar.js';
import Navbar from './Navbar.js';

// --- Constantes de Layout ---
const DRAWER_WIDTH = 260;
const COLLAPSED_DRAWER_WIDTH = 88;
const APP_BAR_HEIGHT = 64;

// --- Styled Components ---

// Contenedor principal del contenido (Main)
const MainContent = styled('main', {
    shouldForwardProp: (prop) => prop !== 'sidebarOpen' && prop !== 'isDesktop',
})(({ theme, sidebarOpen, isDesktop }) => {
    const currentSidebarWidth = !isDesktop ? 0 : (sidebarOpen ? DRAWER_WIDTH : COLLAPSED_DRAWER_WIDTH);

    return {
        flexGrow: 1,
        // *** FONDO GRISÁCEO PARA CONTRASTE ***
        backgroundColor: theme.palette.mode === 'dark'
            ? theme.palette.grey[900] // Gris oscuro para modo oscuro
            : theme.palette.grey[100], // Gris muy claro para modo claro
        marginTop: `${APP_BAR_HEIGHT}px`,
        height: `calc(100vh - ${APP_BAR_HEIGHT}px)`,
        marginLeft: !isDesktop ? 0 : `${currentSidebarWidth}px`,
        width: !isDesktop ? '100%' : `calc(100% - ${currentSidebarWidth}px)`,
        transition: theme.transitions.create(['margin-left', 'width'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.enteringScreen,
        }),
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        padding: theme.spacing(3),
        [theme.breakpoints.down('md')]: {
             padding: theme.spacing(2),
             marginLeft: 0,
             width: '100%',
        },
    };
});

// --- Layout Component (Lógica sin cambios) ---
const DashboardLayout = () => {
    const theme = useTheme();
    const isDesktop = useMediaQuery(theme.breakpoints.up('md'));
    const [mobileOpen, setMobileOpen] = useState(false);
    const [sidebarOpen, setSidebarOpen] = useState(true);

    const isSidebarCollapsed = isDesktop && !sidebarOpen;

    const handleDrawerToggle = useCallback(() => {
        if (isDesktop) {
            setSidebarOpen(prev => !prev);
        } else {
            setMobileOpen(prev => !prev);
        }
    }, [isDesktop]);

    const handleMobileDrawerClose = useCallback(() => {
        setMobileOpen(false);
    }, []);

    return (
        <Box sx={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>
            <CssBaseline />

            {/* Navbar Fijo */}
            <Navbar
                sx={{
                    position: 'fixed',
                    width: isDesktop ? `calc(100% - ${(sidebarOpen ? DRAWER_WIDTH : COLLAPSED_DRAWER_WIDTH)}px)` : '100%',
                    ml: isDesktop ? `${(sidebarOpen ? DRAWER_WIDTH : COLLAPSED_DRAWER_WIDTH)}px` : 0,
                    transition: theme.transitions.create(['margin-left', 'width'], {
                        easing: theme.transitions.easing.sharp,
                        duration: theme.transitions.duration.enteringScreen,
                    }),
                    zIndex: theme.zIndex.drawer + 1,
                }}
                handleDrawerToggle={handleDrawerToggle}
                isSidebarCollapsed={isSidebarCollapsed}
            />

            {/* Sidebar (Usará la versión que hayas elegido: clara u oscura) */}
            <Sidebar
                drawerWidth={DRAWER_WIDTH}
                collapsedWidth={COLLAPSED_DRAWER_WIDTH}
                variant={isDesktop ? "permanent" : "temporary"}
                open={isDesktop ? sidebarOpen : mobileOpen}
                collapsed={isSidebarCollapsed}
                onClose={handleMobileDrawerClose}
                ModalProps={{ keepMounted: true }}
            />

            {/* Área Principal del Contenido */}
            <MainContent component="main" sidebarOpen={sidebarOpen} isDesktop={isDesktop}>
                {/* Contenedor interno para scroll */}
                 <Box sx={{
                     flex: 1,
                     display: 'flex',
                     flexDirection: 'column',
                     overflowY: 'auto',
                     overflowX: 'hidden',
                     minHeight: 0,
                     // Estilos scrollbar (pueden estar en el tema global o aquí)
                     '&::-webkit-scrollbar': { width: '8px' },
                     '&::-webkit-scrollbar-track': { bgcolor: 'transparent', },
                     '&::-webkit-scrollbar-thumb': {
                         backgroundColor: alpha(theme.palette.text.primary, 0.25), // Más visible
                         borderRadius: '4px',
                         '&:hover': {
                              backgroundColor: alpha(theme.palette.text.primary, 0.4),
                         }
                     }
                 }}>
                     <Outlet /> {/* Renderiza la página actual */}
                 </Box>
            </MainContent>
        </Box>
    );
};

export default DashboardLayout;
