// src/features/schedule/components/ActivityLogDisplay.js
import React from 'react';
import {
    List, ListItem, ListItemText, Typography, Box, CircularProgress, Alert,
    Stack, Tooltip, alpha, useTheme, Avatar
} from '@mui/material';
import { formatDistanceToNow, isValid } from 'date-fns';
import { es } from 'date-fns/locale';
import {
    AddCircleOutline, EditOutlined, DeleteForeverOutlined,
    History, PersonOutline, CalendarTodayOutlined, TaskAlt,
} from '@mui/icons-material';

// Mapeo (sin cambios)
const changeTypeMap = {
    creacion: { icon: AddCircleOutline, color: 'success', critical: false },
    actualizacion: { icon: EditOutlined, color: 'info', critical: false },
    eliminacion: { icon: DeleteForeverOutlined, color: 'error', critical: true },
    cambio_estado: { icon: TaskAlt, color: 'secondary', critical: false },
    default: { icon: History, color: 'action', critical: false },
};

const ActivityLogDisplay = ({ entries = [], loading, error, onLogItemClick }) => {
    const theme = useTheme();

    // Estados de carga/error/vacío (sin cambios)
    if (loading) { return ( <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}><CircularProgress size={24} /></Box> ); }
    if (error) { return <Alert severity="error" sx={{ mt: 1, fontSize: '0.8rem' }}>{error}</Alert>; }
    if (!entries || entries.length === 0) { return <Typography variant="body2" color="text.secondary" sx={{ mt: 1, textAlign: 'center', fontStyle: 'italic' }}>No hay actividad registrada.</Typography>; }

    // Formateo de fecha (sin cambios)
    const formatRelativeTime = (date) => {
        if (!date || !isValid(date)) return 'Fecha inválida';
        try { return formatDistanceToNow(date, { addSuffix: true, locale: es }); }
        catch (e) { console.error("Error formatting date:", e); return 'Fecha inválida'; }
    };

    const handleClick = (entry) => { if (onLogItemClick) { onLogItemClick(entry); } };

    return (
        <List sx={{ width: '100%', bgcolor: 'transparent', p: 0 }}>
            {entries.map((entry) => {
                const { icon: ChangeIcon = History, color: changeColorName = 'action', critical = false } = changeTypeMap[entry.tipo_cambio] || changeTypeMap.default;

                // Derivación de color (sin cambios)
                let changeColorValue = theme.palette.text.secondary;
                const paletteColor = theme.palette[changeColorName];
                if (paletteColor) {
                    if (typeof paletteColor === 'object' && paletteColor.main) { changeColorValue = paletteColor.main; }
                    else if (changeColorName === 'action' && paletteColor.active) { changeColorValue = paletteColor.active; }
                    else if (typeof paletteColor === 'string') { changeColorValue = paletteColor; }
                }
                if (typeof changeColorValue !== 'string') { changeColorValue = theme.palette.text.secondary; }

                // Estilo del item
                const isClickable = !!onLogItemClick;
                const itemStyle = {
                    mb: 0.5, // Mantenemos margen inferior
                    cursor: isClickable ? 'pointer' : 'default',
                    transition: theme.transitions.create('background-color'),
                    '&:hover': {
                        bgcolor: isClickable ? alpha(theme.palette.action.hover, 0.04) : 'transparent',
                    },
                    // No necesitamos el spread de critical aquí si no hay estilos específicos
                };

                return (
                    <ListItem
                        key={entry.id_cambio || `log-${Math.random()}`}
                        disableGutters
                        divider
                        onClick={() => handleClick(entry)}
                        sx={{
                            alignItems: 'flex-start',
                            py: 1, // Padding vertical reducido
                            px: 0.5, // Padding horizontal mantenido
                            ...itemStyle
                        }}
                    >
                        {/* Avatar más pequeño */}
                        <Box sx={{ mr: 1.25, mt: 0.25 }}> {/* Margen derecho reducido */}
                            <Avatar sx={{ bgcolor: alpha(changeColorValue, 0.15), width: 28, height: 28 }}> {/* Tamaño reducido */}
                                <ChangeIcon sx={{ fontSize: '1rem', color: changeColorValue }} /> {/* Icono más pequeño */}
                            </Avatar>
                        </Box>

                        {/* Contenido Principal */}
                        <ListItemText
                            primary={
                                <Typography
                                    variant="caption" // Usar caption para el texto principal
                                    component="span"
                                    sx={{
                                        fontWeight: 500,
                                        color: 'text.primary',
                                        lineHeight: 1.3, // Ajustar interlineado
                                        ...(critical && { color: 'error.dark', fontWeight: 600 })
                                    }}
                                >
                                    {entry.descripcion || `Cambio de tipo '${entry.tipo_cambio || 'desconocido'}'`}
                                </Typography>
                            }
                            secondary={
                                // Stack secundario con menos espacio y margen
                                <Stack direction="row" spacing={0.75} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mt: 0.25 }}>
                                    <Tooltip title={entry.nombre_usuario_responsable || 'Sistema'}>
                                        <Stack direction="row" alignItems="center" spacing={0.3}> {/* Menos espacio icono-texto */}
                                            <PersonOutline sx={{ fontSize: '0.8rem', color: 'text.secondary' }} /> {/* Icono más pequeño */}
                                            <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.7rem' }}> {/* Texto más pequeño */}
                                                {entry.nombre_usuario_responsable || 'Sistema'}
                                            </Typography>
                                        </Stack>
                                    </Tooltip>
                                    <Tooltip title={entry.fecha_cambio || 'Fecha desconocida'}>
                                        <Stack direction="row" alignItems="center" spacing={0.3}> {/* Menos espacio icono-texto */}
                                            <CalendarTodayOutlined sx={{ fontSize: '0.8rem', color: 'text.secondary' }} /> {/* Icono más pequeño */}
                                            <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.7rem' }}> {/* Texto más pequeño */}
                                                {formatRelativeTime(entry.fecha_cambio_dt)}
                                            </Typography>
                                        </Stack>
                                    </Tooltip>
                                </Stack>
                            }
                            secondaryTypographyProps={{ component: 'div' }}
                            sx={{ my: 0 }} // Quitar margen vertical del ListItemText
                        />
                    </ListItem>
                );
            })}
        </List>
    );
};

export default ActivityLogDisplay;
