import React from 'react';
import { motion } from 'framer-motion';
import {
    ListItem, Paper, Typography, Chip, styled, useTheme,
    alpha, Stack, Tooltip, IconButton, Box
} from '@mui/material';
import {
    Edit as EditIcon, Delete as DeleteIcon,
    FolderOpen as FolderOpenIcon, // Para chip de proyecto
    CalendarToday as CalendarTodayIcon,
} from '@mui/icons-material';
import {
    prioridadColors, estadoColors, estadoMapping, prioridadMapping,
    getPrioridadIcon, getEstadoIcon, formatSimpleDate // Importar formatSimpleDate
} from '../utils/taskUtils.js'; // Importar utils

// --- Styled Components (Ajustados para tamaño compacto) ---

const TaskItemContainer = styled(motion.div)(({ theme }) => ({
    padding: 0,
    marginBottom: theme.spacing(0.5), // Espacio reducido entre items
    '&:last-child': { marginBottom: 0 },
}));

const TaskPaperStyled = styled(Paper, {
    shouldForwardProp: (prop) => prop !== 'prioridad' && prop !== 'isOverdue' && prop !== 'ultraCompact',
})(({ theme, prioridad, isOverdue, ultraCompact }) => {
    const colorName = prioridadColors[prioridad] || 'default';
    const colorValue = theme.palette[colorName] || theme.palette.grey;
    const mainColor = typeof colorValue === 'object' ? colorValue.main : theme.palette.grey[400];
    const hoverBgColor = typeof colorValue === 'object' ? alpha(mainColor, 0.04) : alpha(theme.palette.grey[400], 0.04);
    const hoverBorderColor = typeof colorValue === 'object' ? alpha(mainColor, 0.4) : alpha(theme.palette.grey[400], 0.4);

    return {
        padding: theme.spacing(ultraCompact ? 0.5 : 0.75, ultraCompact ? 1.25 : 1.5), // Padding reducido
        borderRadius: theme.shape.borderRadius * (ultraCompact ? 0.7 : 0.85), // Radio más pequeño
        transition: theme.transitions.create(['background-color', 'border-color', 'border-left-color'], {
            duration: theme.transitions.duration.shortest,
        }),
        border: `1px solid ${theme.palette.divider}`,
        borderLeft: `${ultraCompact ? 2 : 3}px solid ${isOverdue ? theme.palette.error.main : mainColor}`, // Borde más fino
        backgroundColor: theme.palette.background.paper,
        minHeight: 'auto', // Altura automática
        width: '100%',
        display: 'flex', flexDirection: 'column',
        overflow: 'hidden', cursor: 'pointer', position: 'relative',
        paddingRight: theme.spacing(ultraCompact ? 5 : 6), // Espacio reducido para botones
        '&:hover': {
            backgroundColor: hoverBgColor,
            borderColor: hoverBorderColor,
        },
    };
});

const InfoChipStyled = styled(Chip, {
    shouldForwardProp: (prop) => prop !== 'ultraCompact',
})(({ theme, ultraCompact }) => ({
   height: ultraCompact ? 16 : 18, // Altura aún más pequeña
   fontSize: ultraCompact ? '0.6rem' : '0.65rem', // Fuente aún más pequeña
   fontWeight: 500,
   borderRadius: theme.shape.borderRadius * 0.6, // Más redondeado
   padding: theme.spacing(0, ultraCompact ? 0.4 : 0.5), // Padding reducido
   '& .MuiChip-icon': {
       fontSize: ultraCompact ? '0.7rem' : '0.75rem', // Icono más pequeño
       marginLeft: theme.spacing(ultraCompact ? 0.15 : 0.25),
       marginRight: theme.spacing(ultraCompact ? -0.7 : -0.6),
   },
   // Específico para iconos SVG de Material Icons si es necesario
   '& .MuiChip-icon.MuiSvgIcon-root': {
       fontSize: ultraCompact ? '0.75rem' : '0.8rem',
       marginLeft: theme.spacing(ultraCompact ? 0.25 : 0.35),
       marginRight: theme.spacing(ultraCompact ? -0.8 : -0.7),
   }
}));


// --- Componente TaskItem ---
const TaskItem = ({
    tarea,
    showProjectChip, // Mostrar chip de proyecto (si no estamos filtrando)
    onClick,         // Handler para click general en el item
    onEdit,          // Handler para editar (recibido de TaskList)
    onDelete,        // Handler para borrar (recibido de TaskList)
    ultraCompact = false, // Prop para modo ultra compacto
}) => {
    const theme = useTheme();

    // Handler para el botón de editar
    const handleEditClick = (e) => {
        e.stopPropagation(); // Evita que el click se propague al ListItemButton
        if (onEdit) { // Verifica que la prop exista
            console.log("TaskItem: Edit clicked, calling onEdit with:", tarea); // Log para depurar
            onEdit(tarea); // Llama a la función pasada por props
        } else {
            console.warn("TaskItem: onEdit handler is missing!");
        }
    };

    // Handler para el botón de borrar
    const handleDeleteClick = (e) => {
        e.stopPropagation();
        if (onDelete) { // Verifica que la prop exista
            console.log("TaskItem: Delete clicked, calling onDelete with:", tarea); // Log para depurar
            onDelete(tarea); // Llama a la función pasada por props
        } else {
            console.warn("TaskItem: onDelete handler is missing!");
        }
    };

    // Handler para el click general en el item
    const handleItemClick = () => {
        if (onClick) {
            onClick(tarea);
        }
    };

    // --- Cálculos de estado y formato ---
    const isOverdue = tarea.fecha_vencimiento_orig && new Date(tarea.fecha_vencimiento_orig) < new Date() && tarea.estado !== 'completada';
    const estadoLabel = estadoMapping[tarea.estado] || estadoMapping.default;
    const prioridadLabel = prioridadMapping[tarea.prioridad] || prioridadMapping.default;
    const fechaVencimientoFormatted = formatSimpleDate(tarea.fecha_vencimiento_orig); // Usa la función de utils
    const estadoColorName = estadoColors[tarea.estado] || 'default';
    const estadoBgColor = alpha(theme.palette[estadoColorName]?.main || theme.palette.grey[300], 0.15);
    const estadoTextColor = theme.palette[estadoColorName]?.dark || theme.palette.text.secondary;
    const prioridadColorName = prioridadColors[tarea.prioridad] || 'default';
    const prioridadIconColor = theme.palette[prioridadColorName]?.main || theme.palette.action.active;

    // Tamaños de iconos consistentes y más pequeños
    const actionIconSize = ultraCompact ? '0.8rem' : '0.9rem';
    const priorityIconSize = ultraCompact ? '1rem' : 'small'; // 'small' es ~1.25rem

    return (
        <TaskItemContainer
           key={tarea.id_tarea} layout // key aquí es importante para framer-motion
           initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
           transition={{ type: 'spring', stiffness: 400, damping: 40 }} // Animación más rápida
        >
           <ListItem disablePadding sx={{ width: '100%', alignItems: 'stretch' }}>
               <TaskPaperStyled
                   prioridad={tarea.prioridad} isOverdue={isOverdue} elevation={0}
                   onClick={handleItemClick} ultraCompact={ultraCompact}
               >
                   {/* Stack principal horizontal */}
                   <Stack direction="row" spacing={ultraCompact ? 0.75 : 1} alignItems="flex-start" sx={{ width: '100%' }}>
                        {/* Icono de Prioridad */}
                        <Box sx={{ mt: ultraCompact ? 0.1 : 0.2, color: prioridadIconColor }}>
                           <Tooltip title={`Prioridad: ${prioridadLabel}`}>
                               {/* Renderiza el icono con tamaño dinámico */}
                               {React.isValidElement(getPrioridadIcon(tarea.prioridad))
                                   ? React.cloneElement(getPrioridadIcon(tarea.prioridad), { sx: { fontSize: priorityIconSize } })
                                   : <Box sx={{ width: 16, height: 16 }} /> /* Placeholder pequeño */
                               }
                           </Tooltip>
                        </Box>

                       {/* Contenido Principal (Título y Chips) */}
                       <Stack spacing={ultraCompact ? 0.15 : 0.25} sx={{ flexGrow: 1, overflow: 'hidden', pt: 0 }}>
                           {/* Título */}
                           <Tooltip title={tarea.titulo} placement="top-start">
                               <Typography
                                   variant="body2"
                                   sx={{
                                       fontWeight: 500,
                                       lineHeight: ultraCompact ? 1.3 : 1.4, // Altura de línea reducida
                                       textDecoration: tarea.estado === 'completada' ? 'line-through' : 'none',
                                       color: tarea.estado === 'completada' ? 'text.disabled' : 'text.primary',
                                       overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                                       display: 'block', // Asegura que whiteSpace funcione
                                       fontSize: ultraCompact ? '0.75rem' : '0.8rem', // Tamaño de fuente reducido
                                   }}
                               >
                                   {tarea.titulo || 'Tarea sin título'}
                               </Typography>
                           </Tooltip>
                           {/* Chips de Información */}
                           <Stack direction="row" spacing={ultraCompact ? 0.35 : 0.5} flexWrap="wrap" useFlexGap sx={{ pt: ultraCompact ? 0.1 : 0.25 }}>
                               {/* Chip de Proyecto (Opcional) */}
                               {showProjectChip && !ultraCompact && tarea.nombre_proyecto && (
                                   <InfoChipStyled
                                       icon={<FolderOpenIcon />} // Tamaño manejado por styled
                                       label={tarea.nombre_proyecto}
                                       variant="outlined" ultraCompact={ultraCompact}
                                       // Puedes añadir sx aquí si necesitas estilos específicos
                                   />
                               )}
                               {/* Chip de Estado */}
                               <InfoChipStyled
                                   icon={getEstadoIcon(tarea.estado)} // Tamaño manejado por styled
                                   label={estadoLabel} ultraCompact={ultraCompact}
                                   sx={{ color: estadoTextColor, bgcolor: estadoBgColor, '& .MuiChip-icon': { color: estadoTextColor } }}
                               />
                               {/* Chip de Fecha Vencimiento */}
                               {fechaVencimientoFormatted !== 'N/A' && (
                                   <InfoChipStyled
                                       icon={<CalendarTodayIcon />} // Tamaño manejado por styled
                                       label={fechaVencimientoFormatted} variant="outlined" ultraCompact={ultraCompact}
                                       // Añadir estilo si está vencida
                                       sx={isOverdue ? { borderColor: 'error.light', color: 'error.dark' } : {}}
                                   />
                               )}
                           </Stack>
                       </Stack>

                       {/* Botones de Acción (Posición Absoluta) */}
                       <Stack
                           direction="row" spacing={0} // Sin espacio entre botones
                           justifyContent="flex-end" alignItems="center"
                           sx={{
                               position: 'absolute',
                               top: theme.spacing(ultraCompact ? 0.25 : 0.5), // Posición ajustada
                               right: theme.spacing(ultraCompact ? 0.5 : 0.75), // Posición ajustada
                           }}
                       >
                           <Tooltip title="Editar Tarea">
                               {/* Envolver en span para Tooltip en botón deshabilitado (si aplicara) */}
                               <span>
                                   <IconButton size="small" onClick={handleEditClick} aria-label="Editar tarea"
                                       sx={{ p: ultraCompact ? 0.4 : 0.5, '&:hover': { bgcolor: alpha(theme.palette.action.active, 0.06) } }} >
                                       <EditIcon sx={{ fontSize: actionIconSize }} /> {/* Tamaño dinámico */}
                                   </IconButton>
                               </span>
                           </Tooltip>
                           <Tooltip title="Eliminar Tarea">
                               <span>
                                   <IconButton size="small" onClick={handleDeleteClick} aria-label="Eliminar tarea"
                                       sx={{ p: ultraCompact ? 0.4 : 0.5, color: 'error.main', '&:hover': { bgcolor: alpha(theme.palette.error.main, 0.06) } }} >
                                       <DeleteIcon sx={{ fontSize: actionIconSize }} /> {/* Tamaño dinámico */}
                                   </IconButton>
                               </span>
                           </Tooltip>
                       </Stack>
                   </Stack>
               </TaskPaperStyled>
           </ListItem>
       </TaskItemContainer>
   );
};

export default TaskItem;
