// src/pages/DashboardPage.js
import React, { useCallback, useMemo, useState } from 'react';
import {
    Box, Grid, Typography, Paper, Button, alpha, Fab, Divider, CircularProgress, Alert
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { useAuth } from '../contexts/AuthContext.js';
import { useTheme } from '@mui/material';
import { useProject } from '../contexts/ProjectContext.js'; // <--- Importa el hook del contexto

// Componentes
import Proyectos from '../features/projects/components/Proyectos.js';
import ProyectoFormulario from '../features/projects/components/ProyectoFormulario.js';
import ProyectoEliminarDialog from '../features/projects/components/ProyectoEliminarDialog.js';
import TaskList from '../features/tasks/components/TaskList.js';
import TaskDialog from '../features/tasks/components/TaskDialog.js';
import TaskDeleteDialog from '../features/tasks/components/TaskDeleteDialog.js';
import Cronograma from '../features/schedule/components/Cronograma.js';
import ProjectCompletionDialog from '../features/projects/components/ProjectCompletionDialog.js';
import EquipoManagementPanel from '../features/equipos/components/EquipoManagementPanel.js'; // <--- Importa el panel

// Hooks
import useProyectos from '../features/projects/hooks/useProjects.js';
import { useTareas } from '../features/tasks/hooks/useTareas.js';
import { useActivityLog } from '../hooks/useActivityLog.js';

const DashboardPage = () => {
    const { user } = useAuth();
    const theme = useTheme();
    // Obtiene estado y funciones del contexto, incluyendo control del panel
    const {
        currentProjectId,
        setActiveProject,
        isTeamPanelOpen, // <--- Estado de visibilidad del panel
        closeTeamPanel   // <--- Función para cerrar el panel
    } = useProject();

    // --- Hooks Proyectos ---
    // Quitamos setSelectedProjectId y selectedProjectId de aquí
    const {
        proyectos,
        selectedProyecto, // Este puede seguir siendo útil para el diálogo de eliminación
        formData: projectFormData, isFormOpen: isProjectFormOpen,
        isDeleteDialogOpen: isProjectDeleteDialogOpen, operationLoading: projectOperationLoading,
        operationError: projectOperationError, handleInputChange: handleProjectInputChange,
        handleOpenForm: openProjectForm, handleCloseForm: closeProjectForm,
        handleOpenDeleteDialog: openProjectDeleteDialog, handleCloseDeleteDialog: closeProjectDeleteDialog,
        handleSubmit: handleProjectSubmit, handleDeleteConfirm,
        updateProjectStatus
    } = useProyectos();

    // Estado para el diálogo de finalización de proyecto
    const [isCompletionDialogOpen, setIsCompletionDialogOpen] = useState(false);
    const [projectToCompleteId, setProjectToCompleteId] = useState(null);

    // Handler llamado por useTareas
    const handleAllTasksCompleted = useCallback((projectId) => {
        console.log(`DashboardPage: Recibida señal de que todas las tareas del proyecto ${projectId} están completas.`);
        setProjectToCompleteId(projectId);
        setIsCompletionDialogOpen(true);
    }, []);

    // Hook useTareas (usa currentProjectId del contexto)
    const {
        tareas, loading: loadingTasks, error: errorTasks,
        dialogOpen: isTaskDialogOpen, formData: taskFormData, isEditing: isTaskEditing,
        tareaToDelete, isDeleteDialogOpen: isTaskDeleteDialogOpen,
        operationLoading: taskOperationLoading, operationError: taskOperationError,
        openEditDialog: openTaskEditDialog, openCreateDialog: openTaskCreateDialog,
        handleCloseDialog: closeTaskDialog, openDeleteConfirm: openTaskDeleteConfirm,
        handleCloseDeleteDialog: closeTaskDeleteDialog, handleSubmit: handleTaskSubmit,
        handleDeleteConfirm: handleTaskDeleteConfirm, handleInputChange: handleTaskInputChange,
        handleDateChange: handleTaskDateChange,
    } = useTareas(currentProjectId, handleAllTasksCompleted); // <--- Pasa currentProjectId

    // Hook Activity Log - Obtiene el log GLOBAL si no hay proyecto activo
    const {
        logEntries: globalLogEntries,
        loading: loadingGlobalLog,
        error: errorGlobalLog,
        refreshLog
    } = useActivityLog(currentProjectId ? null : 'proyectos', null); // Solo fetch global si no hay proyecto activo

    // --- Handlers ---
    // Modificado para usar setActiveProject del contexto
    const handleProjectSelection = useCallback((projectId) => {
        console.log("DashboardPage: Project selected:", projectId);
        setActiveProject(projectId); // <--- Llama a la función del contexto
        // Opcional: Refrescar el log global cuando se deselecciona un proyecto
        if (!projectId) {
            refreshLog();
        }
    }, [setActiveProject, refreshLog]); // <--- Depende de setActiveProject

    const handleOperationSuccess = useCallback(() => {
        console.log("Operation successful, refreshing log...");
        if (typeof refreshLog === 'function') {
            refreshLog();
        } else {
            console.error("refreshLog is not available or not a function!");
        }
        // Considera si necesitas refrescar miembros aquí también, aunque el contexto ya lo hace al seleccionar
        // if (currentProjectId && typeof refreshMembers === 'function') { // Si implementas refreshMembers en el contexto
        //    refreshMembers();
        // }
    }, [refreshLog]); // Podría necesitar refreshMembers si se implementa

    const handleTaskClick = useCallback((task) => { console.log("Tarea clickeada:", task); }, []);
    const handleEditProject = useCallback((proyecto) => { openProjectForm(proyecto); }, [openProjectForm]);
    const handleDeleteProject = useCallback((proyecto) => { openProjectDeleteDialog(proyecto); }, [openProjectDeleteDialog]);
    const handleAddNewProject = useCallback(() => { openProjectForm(null); }, [openProjectForm]);
    const handleEditTask = useCallback((task) => { openTaskEditDialog(task); }, [openTaskEditDialog]);
    const handleDeleteTask = useCallback((task) => { openTaskDeleteConfirm(task); }, [openTaskDeleteConfirm]);
    const handleAddNewTask = useCallback(() => {
        if (currentProjectId) { openTaskCreateDialog(); } // Usa currentProjectId del contexto
        else { console.warn("Selecciona un proyecto para añadir una tarea."); }
    }, [currentProjectId, openTaskCreateDialog]); // Usa currentProjectId del contexto

    // --- Handlers para el Diálogo de Finalización ---
    const handleCloseCompletionDialog = useCallback(() => {
        setIsCompletionDialogOpen(false);
        setProjectToCompleteId(null);
    }, []);

    const handleConfirmProjectCompletion = useCallback(async () => {
        if (!projectToCompleteId) return;
        console.log(`DashboardPage: Confirmado finalizar proyecto ${projectToCompleteId}`);
        try {
            await updateProjectStatus(projectToCompleteId, 'finalizado');
            handleOperationSuccess();
        } catch (error) {
            console.error("Error al intentar marcar el proyecto como finalizado:", error);
        } finally {
            handleCloseCompletionDialog();
        }
    }, [projectToCompleteId, updateProjectStatus, handleCloseCompletionDialog, handleOperationSuccess]);

    const handleKeepProjectActive = useCallback(() => {
        console.log(`DashboardPage: Decidido mantener activo el proyecto ${projectToCompleteId}`);
        handleCloseCompletionDialog();
    }, [projectToCompleteId, handleCloseCompletionDialog]);

    // Obtener nombre del proyecto para el diálogo (useMemo)
    const projectToCompleteName = useMemo(() => {
        if (!projectToCompleteId) return '';
        const proj = proyectos.find(p => p.id_proyecto === projectToCompleteId);
        return proj?.nombre || `Proyecto ID ${projectToCompleteId}`;
    }, [projectToCompleteId, proyectos]);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}>
            {/* Header */}
            <Box sx={{ p: { xs: 1, sm: 2 }, flexShrink: 0 }}>
                <Typography variant="h5" component="h1" sx={{ mb: 1, fontWeight: 600 }}>
                    Dashboard {user ? `- ${user.nombre_usuario || user.email}` : ''}
                </Typography>
            </Box>

            {/* Grid Container */}
            <Grid container spacing={2} sx={{ flexGrow: 1, overflow: 'hidden', px: { xs: 1, sm: 2 }, pb: { xs: 1, sm: 2 }, height: `calc(100% - ${theme.spacing(8)})` }}>

                {/* Columna Izquierda */}
                <Grid item xs={12} sm={5} md={4} lg={3} sx={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden', width: 1/4}}>
                    <Paper sx={{ p: 1.5, display: 'flex', flexDirection: 'column', flexGrow: 1, overflow: 'hidden', height: '100%' }}>
                        {/* Sección Proyectos (Usa currentProjectId para el seleccionado) */}
                        <Box sx={{ mb: 1.5, flexShrink: 0 }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                <Typography variant="subtitle1" component="h2" fontWeight="500">Proyectos</Typography>
                                <Button variant="contained" size="small" startIcon={<AddIcon />} onClick={handleAddNewProject} disabled={projectOperationLoading} sx={{ py: 0.5, fontSize: '0.75rem' }}>Nuevo</Button>
                            </Box>
                            <Box sx={{ maxHeight: 'calc(40vh - 60px)', overflowY: 'auto', pr: 0.5, mr: -0.5, '&::-webkit-scrollbar': { width: '4px' }, '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.2), borderRadius: '2px' } }}>
                                <Proyectos
                                    proyectos={proyectos}
                                    selectedProjectId={currentProjectId} // <--- Usa el ID del contexto
                                    onProjectSelect={handleProjectSelection}
                                    onEditProject={handleEditProject}
                                    onDeleteProject={handleDeleteProject}
                                />
                            </Box>
                        </Box>
                        <Divider sx={{ my: 1 }} />
                        {/* Sección Tareas (Usa currentProjectId) */}
                        <Box sx={{ display: 'flex', flexDirection: 'column', flexGrow: 1, overflow: 'hidden' }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1, flexShrink: 0 }}>
                                {/* Ajustar título de tareas */}
                                <Typography variant="subtitle1" component="h2" fontWeight="500">{currentProjectId ? `Tareas del Proyecto` : 'Selecciona un Proyecto'}</Typography>
                                {/* Deshabilitar botón "Nueva Tarea" si no hay proyecto seleccionado */}
                                <Button variant="contained" size="small" startIcon={<AddIcon />} onClick={handleAddNewTask} disabled={!currentProjectId || taskOperationLoading} sx={{ py: 0.5, fontSize: '0.75rem' }}>Nueva Tarea</Button>
                            </Box>
                            <Box sx={{ flexGrow: 1, overflowY: 'auto', pr: 0.5, mr: -0.5, '&::-webkit-scrollbar': { width: '4px' }, '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.2), borderRadius: '2px' } }}>
                                <TaskList
                                    tareas={tareas}
                                    loading={loadingTasks}
                                    error={errorTasks}
                                    idProyectoContext={currentProjectId} // <--- Usa el ID del contexto
                                    onTaskClick={handleTaskClick}
                                    onEditTask={handleEditTask}
                                    onDeleteTask={handleDeleteTask}
                                />
                            </Box>
                        </Box>
                    </Paper>
                </Grid>

                {/* Columna Derecha (Usa currentProjectId) */}
                <Grid item xs={12} sm={7} md={8} lg={9} sx={{ display: { xs: 'none', sm: 'flex' }, height: '100%', flexDirection: 'column', overflow: 'hidden', width: 5.9/8 }}>
                    <Cronograma
                        selectedProjectId={currentProjectId} // <--- Usa el ID del contexto
                        // Pasar el log GLOBAL solo si no hay proyecto activo
                        activityLog={!currentProjectId ? { entries: globalLogEntries, loading: loadingGlobalLog, error: errorGlobalLog } : undefined}
                    />
                </Grid>
            </Grid>

            {/* FAB (Usa currentProjectId) */}
            <Fab color="primary" size="medium" aria-label="add task" onClick={handleAddNewTask} disabled={!currentProjectId || taskOperationLoading} sx={{ position: 'fixed', bottom: theme.spacing(2), right: theme.spacing(2), zIndex: 1050, display: { xs: 'flex', sm: 'none' } }}>
                <AddIcon />
            </Fab>

            {/* --- Diálogos Modales --- */}
            {/* Formulario Proyecto */}
            {isProjectFormOpen && (
                <ProyectoFormulario
                    open={isProjectFormOpen}
                    onClose={closeProjectForm}
                    onSubmit={(e) => handleProjectSubmit(e).then(handleOperationSuccess)}
                    proyectoData={projectFormData}
                    onInputChange={handleProjectInputChange}
                    isCreating={!projectFormData?.id_proyecto}
                    loading={projectOperationLoading}
                    error={projectOperationError}
                />
            )}
            {/* Eliminar Proyecto */}
            {isProjectDeleteDialogOpen && (
                <ProyectoEliminarDialog
                    open={isProjectDeleteDialogOpen}
                    onClose={closeProjectDeleteDialog}
                    onConfirm={() => {
                        console.log("Attempting to delete project...");
                        handleDeleteConfirm()
                            .then(() => {
                                console.log("Project deleted successfully, calling handleOperationSuccess...");
                                if (typeof handleOperationSuccess === 'function') {
                                    handleOperationSuccess();
                                } else {
                                    console.error("handleOperationSuccess is not defined or not a function!");
                                }
                            })
                            .catch(error => {
                                console.error("Error caught during project deletion flow in DashboardPage:", error);
                            });
                    }}
                    // Usa selectedProyecto del hook useProyectos para el nombre
                    proyectoNombre={selectedProyecto?.nombre}
                    loading={projectOperationLoading}
                    error={projectOperationError}
                />
            )}
            {/* Formulario Tarea */}
            {isTaskDialogOpen && (
                 <TaskDialog
                    open={isTaskDialogOpen}
                    onClose={closeTaskDialog}
                    onSubmit={(e) => handleTaskSubmit(e).then(handleOperationSuccess)}
                    formData={taskFormData}
                    onInputChange={handleTaskInputChange}
                    onDateChange={handleTaskDateChange}
                    isEditing={isTaskEditing}
                    loading={taskOperationLoading}
                    error={taskOperationError}
                 />
            )}
            {/* Eliminar Tarea */}
            {isTaskDeleteDialogOpen && (
                <TaskDeleteDialog
                    open={isTaskDeleteDialogOpen}
                    onClose={closeTaskDeleteDialog}
                    onConfirm={() => handleTaskDeleteConfirm().then(handleOperationSuccess)}
                    taskTitle={tareaToDelete?.titulo}
                    loading={taskOperationLoading}
                    error={taskOperationError}
                />
            )}
            {/* Diálogo de Confirmación de Finalización */}
            {isCompletionDialogOpen && (
                <ProjectCompletionDialog
                    open={isCompletionDialogOpen}
                    onClose={handleCloseCompletionDialog}
                    onConfirmCompletion={handleConfirmProjectCompletion}
                    onKeepActive={handleKeepProjectActive}
                    projectName={projectToCompleteName}
                    loading={projectOperationLoading} // Pasa el loading de operación de proyecto
                />
            )}

            {/* --- Renderizado Condicional del Panel de Equipo --- */}
            <EquipoManagementPanel
                open={isTeamPanelOpen}
                onClose={closeTeamPanel}
                projectId={currentProjectId}
            />
            {/* --- Fin Panel de Equipo --- */}
        </Box>
    );
};

export default DashboardPage;
