// src/utils/validation.js (o el nombre que elijas)

/**
 * Valida si un ID de proyecto es un número válido y positivo.
 * @param {any} id - El ID a validar.
 * @returns {boolean} - True si es válido, false en caso contrario.
 */
export const isValidProjectId = (id) => {
    const numId = Number(id);
    // Verifica que no sea null/undefined, no sea string vacío,
    // sea un número finito y sea mayor que 0.
    return id !== null &&
           id !== undefined &&
           String(id).trim() !== '' &&
           !isNaN(numId) &&
           isFinite(numId) && // Asegura que no sea Infinity
           numId > 0;
};

/**
 * Valida si un ID de tarea es un número válido y positivo.
 * @param {any} id - El ID a validar.
 * @returns {boolean} - True si es válido, false en caso contrario.
 */
export const isValidTaskId = (id) => {
    const numId = Number(id);
    return id !== null &&
           id !== undefined &&
           String(id).trim() !== '' &&
           !isNaN(numId) &&
           isFinite(numId) &&
           numId > 0;
};

