// src/features/schedule/hooks/useScheduleData.js
import { useState, useEffect, useCallback, useMemo } from 'react';
import { useAuth } from '../../../contexts/AuthContext.js';
import * as projectService from '../../projects/services/projectService.js';
import * as taskService from '../../tasks/services/taskService.js';
// *** Importa useActivityLog ***
import { useActivityLog } from '../../../hooks/useActivityLog.js';
import {
    transformTaskToTimelineItem,
    calculateProgress,
    getUrgencyInfo,
    formatDisplayDate,
} from '../utils/scheduleUtils.js';
import { isValid, parseISO } from 'date-fns';

import { isValidProjectId } from '../../../utils/validation.js';

// Helper para asegurar que una fecha sea válida o null
const safeParseDate = (dateInput) => {
    if (!dateInput) return null;
    // Intenta crear un objeto Date directamente. Si es válido, usa el string original.
    // Si no, intenta parsear como ISO.
    try {
        const directDate = new Date(dateInput);
        if (isValid(directDate)) {
            // Si es válido, devuelve el string original o formatea a YYYY-MM-DD si es necesario
            // Esto depende de qué formato espera el resto de tu código.
            // Asumiremos que el string original está bien si es parseable.
            return dateInput;
        } else {
            // Intenta parsear como ISO, manejando el espacio
            const isoDate = parseISO(dateInput.includes(' ') ? dateInput.replace(' ', 'T') : dateInput);
            // Si el parseo ISO es válido, devuelve el string original (o formatea si prefieres)
            return isValid(isoDate) ? dateInput : null;
        }
    } catch (e) {
        console.warn(`safeParseDate: Error parsing date string "${dateInput}"`, e);
        return null;
    }
};


// Helper para asegurar que un string no sea null/undefined/vacío
const ensureString = (value, defaultValue = '') => {
    return (value !== null && value !== undefined) ? String(value) : defaultValue;
};


export const useScheduleData = (selectedProjectId = null) => {
    const [rawTasks, setRawTasks] = useState([]);
    const [selectedProjectDetails, setSelectedProjectDetails] = useState(null);
    const [generalProjectsData, setGeneralProjectsData] = useState([]);
    const [loadingData, setLoadingData] = useState(true); // Loading para proyectos/tareas
    const [errorData, setErrorData] = useState(null); // Error para proyectos/tareas
    const [filters, setFilters] = useState({ priority: 'all' });
    const { token } = useAuth(); // Asume que useAuth provee el token

    // *** Hook para el LOG ESPECÍFICO del proyecto ***
    // Se activa solo si selectedProjectId es válido
    const {
        logEntries: specificLogEntries,
        loading: loadingSpecificLog,
        error: errorSpecificLog,
        refreshLog: refreshSpecificLog // Se puede usar para refrescar el log específico si es necesario
    } = useActivityLog(
        selectedProjectId && isValidProjectId(selectedProjectId) ? 'proyectos' : null, // Tipo de tabla
        selectedProjectId && isValidProjectId(selectedProjectId) ? selectedProjectId : null // ID del registro
    );

    // --- Fetch Data (Proyectos y Tareas) ---
    const fetchData = useCallback(async () => {
        // Verifica si hay token ANTES de cualquier llamada
        if (!token) {
            console.error("useScheduleData: Token no disponible.");
            setErrorData("Autenticación requerida."); setLoadingData(false);
            setRawTasks([]); setSelectedProjectDetails(null); setGeneralProjectsData([]);
            return;
        }

        setLoadingData(true); setErrorData(null);
        console.log(`useScheduleData: Starting fetch for ${selectedProjectId ? `Project ID ${selectedProjectId}` : 'Global View'}`);

        let projectDetailsResult = null; // Para vista específica
        let projectsForSummary = []; // Para vista general
        let tasksDataArray = [];

        try {
            const isProjectView = selectedProjectId !== null && isValidProjectId(selectedProjectId);

            if (isProjectView) {
                // --- Vista de Proyecto Seleccionado ---
                console.log(`useScheduleData: Fetching project/task data for project ID: ${selectedProjectId}`);
                setGeneralProjectsData([]); // Limpiar datos generales

                // Llama a fetchProyectoById para obtener UN proyecto y fetchTareas para las tareas de ESE proyecto
                const [projectResult, tasksResult] = await Promise.all([
                    projectService.fetchProyectoById(selectedProjectId), // <--- CORREGIDO: Usa fetchProyectoById
                    taskService.getTareas(selectedProjectId) // Asume que fetchTareas solo necesita projectId
                ]);

                projectDetailsResult = projectResult; // Puede ser null si no se encuentra
                tasksDataArray = tasksResult || [];

                if (!projectDetailsResult) {
                    // Si el proyecto no se encontró (fetchProyectoById devolvió null)
                    throw new Error(`Proyecto con ID ${selectedProjectId} no encontrado o acceso denegado.`);
                }

                // Procesar detalles del proyecto (ya es un solo objeto)
                const validStartDateOrig = safeParseDate(projectDetailsResult.fecha_inicio); // Usa los nombres de campo correctos
                const validEndDateOrig = safeParseDate(projectDetailsResult.fecha_fin);   // Usa los nombres de campo correctos
                const processedProjectDetails = {
                    ...projectDetailsResult,
                    nombre: ensureString(projectDetailsResult.nombre, 'Proyecto sin nombre'),
                    descripcion: ensureString(projectDetailsResult.descripcion),
                    estado: ensureString(projectDetailsResult.estado?.toLowerCase().replace(/\s+/g, '_'), 'desconocido'),
                    nombre_usuario_creador: ensureString(projectDetailsResult.nombre_usuario_creador, 'Desconocido'),
                    // Guarda las fechas originales parseadas si necesitas lógica con ellas
                    fecha_inicio_orig: validStartDateOrig,
                    fecha_fin_orig: validEndDateOrig,
                    // Crea las fechas para mostrar
                    fecha_inicio_display: formatDisplayDate(validStartDateOrig),
                    fecha_fin_display: formatDisplayDate(validEndDateOrig),
                };
                setSelectedProjectDetails(processedProjectDetails);
                console.log("Processed Project Details:", processedProjectDetails);

                // Procesar tareas
                const processedTasks = tasksDataArray.map(task => {
                    const validTaskStartOrig = safeParseDate(task.fecha_inicio); // Usa los nombres de campo correctos
                    const validTaskDueOrig = safeParseDate(task.fecha_vencimiento); // Usa los nombres de campo correctos
                    return {
                        ...task,
                        titulo: ensureString(task.titulo, 'Tarea sin título'),
                        descripcion: ensureString(task.descripcion),
                        estado: ensureString(task.estado?.toLowerCase().replace(/\s+/g, '_'), 'pendiente'),
                        prioridad: ensureString(task.prioridad?.toLowerCase(), 'media'),
                        nombre_proyecto: ensureString(processedProjectDetails.nombre, 'Proyecto sin nombre'), // Usar nombre procesado
                        // Guarda fechas originales parseadas
                        fecha_inicio_orig: validTaskStartOrig,
                        fecha_vencimiento_orig: validTaskDueOrig,
                        // Crea fechas para mostrar
                        fecha_inicio_display: formatDisplayDate(validTaskStartOrig),
                        fecha_vencimiento_display: formatDisplayDate(validTaskDueOrig),
                        status: ensureString(task.estado?.toLowerCase().replace(/\s+/g, '_'), 'pendiente'), // Mantener 'status' si se usa en otro lugar
                    };
                });
                setRawTasks(processedTasks);
                console.log("Processed Tasks (Specific):", processedTasks);

            } else {
                // --- Vista General ---
                console.log("useScheduleData: Fetching data for Global View.");
                setSelectedProjectDetails(null); // Limpiar detalles del proyecto

                // Llama a fetchProyectos para obtener TODOS los proyectos y fetchTareas sin ID para TODAS las tareas
                const [projectsResult, tasksResult] = await Promise.all([
                    projectService.fetchProyectos(), // <--- CORREGIDO: Usa fetchProyectos
                    taskService.getTareas() // Asume que fetchTareas sin ID trae todas
                ]);

                projectsForSummary = projectsResult || [];
                tasksDataArray = tasksResult || [];

                // Procesar proyectos para resumen
                const processedProjects = projectsForSummary.map(proj => {
                     const validProjStartOrig = safeParseDate(proj.fecha_inicio); // Usa los nombres de campo correctos
                     const validProjEndOrig = safeParseDate(proj.fecha_fin);   // Usa los nombres de campo correctos
                     return {
                        ...proj,
                        nombre: ensureString(proj.nombre, 'Proyecto sin nombre'),
                        descripcion: ensureString(proj.descripcion),
                        estado: ensureString(proj.estado?.toLowerCase().replace(/\s+/g, '_'), 'activo'),
                        nombre_usuario_creador: ensureString(proj.nombre_usuario_creador, 'Desconocido'),
                        // Guarda fechas originales parseadas
                        fecha_inicio_orig: validProjStartOrig,
                        fecha_fin_orig: validProjEndOrig,
                        // Crea fechas para mostrar
                        fecha_inicio_display: formatDisplayDate(validProjStartOrig),
                        fecha_fin_display: formatDisplayDate(validProjEndOrig),
                    };
                });
                setGeneralProjectsData(processedProjects);
                console.log("Processed Projects for Summary (Global):", processedProjects);

                // Procesar TODAS las tareas
                const projectNamesMap = processedProjects.reduce((map, proj) => {
                    if (proj.id_proyecto) map[proj.id_proyecto] = proj.nombre;
                    return map;
                }, {});
                const processedTasks = tasksDataArray.map(task => {
                    const validTaskStartOrig = safeParseDate(task.fecha_inicio); // Usa los nombres de campo correctos
                    const validTaskDueOrig = safeParseDate(task.fecha_vencimiento); // Usa los nombres de campo correctos
                    return {
                        ...task,
                        titulo: ensureString(task.titulo, 'Tarea sin título'),
                        descripcion: ensureString(task.descripcion),
                        estado: ensureString(task.estado?.toLowerCase().replace(/\s+/g, '_'), 'pendiente'),
                        prioridad: ensureString(task.prioridad?.toLowerCase(), 'media'),
                        nombre_proyecto: ensureString(projectNamesMap[task.id_proyecto], 'Proyecto Desconocido'), // Añadir nombre del proyecto
                        // Guarda fechas originales parseadas
                        fecha_inicio_orig: validTaskStartOrig,
                        fecha_vencimiento_orig: validTaskDueOrig,
                        // Crea fechas para mostrar
                        fecha_inicio_display: formatDisplayDate(validTaskStartOrig),
                        fecha_vencimiento_display: formatDisplayDate(validTaskDueOrig),
                        status: ensureString(task.estado?.toLowerCase().replace(/\s+/g, '_'), 'pendiente'),
                    };
                });
                setRawTasks(processedTasks);
                console.log("Processed Tasks (Global):", processedTasks);
            }

        } catch (err) {
            console.error("useScheduleData: Error during fetchData:", err);
            // Intenta obtener el mensaje de error de forma más segura
            const message = err?.result?.message || err?.message || 'Error al cargar datos del cronograma.';
            setErrorData(message);
            // Limpiar estados en caso de error
            setRawTasks([]);
            setSelectedProjectDetails(null);
            setGeneralProjectsData([]);
        } finally {
            setLoadingData(false);
            console.log("useScheduleData: Fetch finished.");
        }

    }, [selectedProjectId, token]); // Dependencias correctas

    useEffect(() => {
        fetchData();
    }, [fetchData]); // fetchData ya incluye selectedProjectId y token como dependencias

    // --- Filtrado y Transformación ---
    const filteredAndTransformedItems = useMemo(() => {
        // console.log("useScheduleData useMemo: Transforming rawTasks:", rawTasks);
        // console.log("useScheduleData useMemo: Applying filters:", filters);

        const items = rawTasks
            .filter(task => {
                const passesPriority = filters.priority === 'all' || task.prioridad === filters.priority;
                // Añadir más filtros aquí si es necesario
                return passesPriority;
            })
            .map(task => {
                // console.log("useScheduleData useMemo: Task before transform:", task);
                const timelineItem = transformTaskToTimelineItem(task);
                // console.log(`useScheduleData useMemo: Task ${task.id_tarea} transformed to:`, timelineItem);

                // Validación más robusta del item transformado
                if (!timelineItem) {
                     console.warn(`Task ${task.id_tarea || 'ID missing'} resulted in null timeline item.`);
                     return null;
                }
                if (!timelineItem.date || !isValid(timelineItem.date)) {
                    console.warn(`Task ${task.id_tarea || 'ID missing'} resulted in invalid date in timeline item:`, timelineItem.date);
                    return null;
                }
                 if (!timelineItem.title) {
                    console.warn(`Task ${task.id_tarea || 'ID missing'} resulted in timeline item with missing title.`);
                    // Considera asignar un título por defecto si es preferible a filtrar
                    // timelineItem.title = '(Tarea sin título)';
                    return null;
                }
                return timelineItem;
            })
            .filter(item => item !== null); // Filtrar nulos resultantes de la transformación o validación

        // console.log("useScheduleData useMemo: Transformed items (before sort):", items);

        // Ordenación por fecha, manejando fechas potencialmente nulas
        return items.sort((a, b) => (a.date?.getTime() ?? 0) - (b.date?.getTime() ?? 0));

    }, [rawTasks, filters]);

    // --- Manejador para cambiar filtros ---
    const handleFilterChange = useCallback((filterName, value) => {
        // Asegurarse de que el valor no sea null/undefined antes de actualizar
        if (value !== null && value !== undefined) {
            setFilters(prevFilters => ({ ...prevFilters, [filterName]: value }));
        } else {
            console.warn(`handleFilterChange received null/undefined value for filter '${filterName}'`);
        }
    }, []);

    // --- Calcular detalles para la cabecera ---
    const projectHeaderData = useMemo(() => {
        if (selectedProjectDetails) {
            // Usa las fechas originales parseadas para cálculos
            const progress = calculateProgress(selectedProjectDetails.fecha_inicio_orig, selectedProjectDetails.fecha_fin_orig);
            const urgency = getUrgencyInfo(selectedProjectDetails.fecha_inicio_orig, selectedProjectDetails.fecha_fin_orig, selectedProjectDetails.estado, true);
            return { progress, urgency };
        }
        return { progress: 0, urgency: null };
    }, [selectedProjectDetails]);

    // --- Combinar estados de carga y error ---
    // El loading general es la carga de datos + la carga del log específico (si aplica)
    const combinedLoading = loadingData || (!!selectedProjectId && loadingSpecificLog);
    // El error general es el error de datos O el error del log específico (si aplica)
    const combinedError = errorData || (!!selectedProjectId && errorSpecificLog ? `Error en log: ${errorSpecificLog}` : null);


    // *** Devolver el estado y funciones, INCLUYENDO el log específico ***
    return {
        timelineItems: filteredAndTransformedItems,
        selectedProjectDetails,
        generalProjectsData,
        projectProgress: projectHeaderData.progress,
        projectUrgencyInfo: projectHeaderData.urgency,
        loading: combinedLoading, // Usar loading combinado
        error: combinedError,     // Usar error combinado
        filters,
        handleFilterChange,
        // *** Devolver el log específico del proyecto ***
        projectActivityLog: {
            entries: specificLogEntries,
            loading: loadingSpecificLog,
            error: errorSpecificLog,
            refreshLog: refreshSpecificLog // Devolver refresh por si se necesita
        },
        // Opcional: Devolver la función para recargar datos manualmente si es necesario
        refreshScheduleData: fetchData
    };
};
