// src/features/equipos/components/EquipoManagementPanel.js
import React, { useState, useCallback } from 'react';
import {
    Drawer, Box, Typography, IconButton, Divider, CircularProgress, Alert, Button, Snackbar
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import { useProject } from '../../../contexts/ProjectContext.js'; // Ajusta ruta si es necesario
import * as equiposService from '../services/equiposService.js'; // Ajusta ruta si es necesario
import EquipoList from './EquipoList.js'; // Reutiliza la lista
import AddMiembroDialog from './AddMiembroDialog.js'; // Reutiliza el diálogo de añadir
import EditRolDialog from './EditRolDialog.js'; // Reutiliza el diálogo de editar

const PANEL_WIDTH = 360; // Ancho del panel lateral

const EquipoManagementPanel = ({ open, onClose, projectId }) => {
    // Obtiene datos y funciones del contexto
    const {
        currentProjectMembers,
        loadingMembers,
        errorMembers,
        refreshMembers // Función para refrescar la lista en el contexto (y sidebar)
    } = useProject();

    // Estados locales para los diálogos dentro del panel
    const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
    const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
    const [miembroParaEditar, setMiembroParaEditar] = useState(null);
    const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
    const [operationLoading, setOperationLoading] = useState(false);
    const [operationError, setOperationError] = useState(null);


    // --- Handlers para CRUD (adaptados para el panel) ---
    const handleAddMiembro = async (proyectoId, usuarioId, rol) => {
        setOperationLoading(true);
        setOperationError(null);
        try {
            await equiposService.addMiembroEquipo(proyectoId, usuarioId, rol);
            setSnackbar({ open: true, message: 'Miembro añadido.', severity: 'success' });
            refreshMembers(); // Refresca la lista en el contexto/sidebar
        } catch (err) {
            console.error("Error en handleAddMiembro (Panel):", err);
            setOperationError(err.message || 'Error al añadir miembro.'); // Muestra error en el diálogo
            setSnackbar({ open: true, message: err.message || 'Error al añadir.', severity: 'error' });
            throw err; // Relanza para que el diálogo sepa que falló
        } finally {
            setOperationLoading(false);
        }
    };

    const handleUpdateRol = async (proyectoId, usuarioId, nuevoRol) => {
        setOperationLoading(true);
        setOperationError(null);
        try {
            await equiposService.updateRolMiembro(proyectoId, usuarioId, nuevoRol);
            setSnackbar({ open: true, message: 'Rol actualizado.', severity: 'success' });
            refreshMembers();
        } catch (err) {
            console.error("Error en handleUpdateRol (Panel):", err);
             setOperationError(err.message || 'Error al actualizar rol.');
            setSnackbar({ open: true, message: err.message || 'Error al actualizar.', severity: 'error' });
            throw err;
        } finally {
            setOperationLoading(false);
        }
    };

    const handleRemoveMiembro = async (proyectoId, usuarioId) => {
        // No usamos operationLoading/Error aquí porque la confirmación está en EquipoListItem
        // y el error principal se mostraría en el Snackbar
        try {
            await equiposService.removeMiembroEquipo(proyectoId, usuarioId);
            setSnackbar({ open: true, message: 'Miembro eliminado.', severity: 'success' });
            refreshMembers();
        } catch (err) {
            console.error("Error en handleRemoveMiembro (Panel):", err);
            setSnackbar({ open: true, message: err.message || 'Error al eliminar.', severity: 'error' });
        }
    };

    // --- Handlers para Diálogos ---
    const openEditDialog = (miembro) => {
        setMiembroParaEditar(miembro);
        setOperationError(null); // Limpia error al abrir diálogo
        setIsEditDialogOpen(true);
    };
    const handleCloseAddDialog = () => {
        setOperationError(null);
        setIsAddDialogOpen(false);
    };
    const handleCloseEditDialog = () => {
        setOperationError(null);
        setIsEditDialogOpen(false);
        setMiembroParaEditar(null); // Limpia el miembro a editar
    };

    const handleCloseSnackbar = (event, reason) => {
        if (reason === 'clickaway') return;
        setSnackbar({ ...snackbar, open: false });
    };

    return (
        <>
            <Drawer
                anchor="right"
                open={open}
                onClose={onClose}
                PaperProps={{
                    sx: {
                        width: PANEL_WIDTH,
                        boxSizing: 'border-box',
                        display: 'flex',
                        flexDirection: 'column',
                    }
                }}
            >
                {/* Header del Panel */}
                <Box
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        p: 2,
                        borderBottom: (theme) => `1px solid ${theme.palette.divider}`,
                        flexShrink: 0,
                    }}
                >
                    <Typography variant="h6" component="div">
                        Gestionar Equipo
                    </Typography>
                    <IconButton onClick={onClose} size="small">
                        <CloseIcon />
                    </IconButton>
                </Box>

                {/* Contenido Principal del Panel */}
                <Box sx={{ p: 2, flexGrow: 1, overflowY: 'auto' }}>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Proyecto ID: {projectId || 'N/A'}
                    </Typography>

                    <Button
                        variant="contained"
                        startIcon={<AddIcon />}
                        onClick={() => { setOperationError(null); setIsAddDialogOpen(true); }}
                        disabled={loadingMembers || !projectId} // Deshabilita si carga o no hay ID
                        fullWidth
                        sx={{ mb: 2 }}
                    >
                        Añadir Miembro
                    </Button>

                    {loadingMembers && (
                        <Box sx={{ display: 'flex', justifyContent: 'center', my: 4 }}>
                            <CircularProgress />
                        </Box>
                    )}

                    {errorMembers && !loadingMembers && (
                        <Alert severity="error" sx={{ mb: 2 }}>
                            {errorMembers}
                            {/* Podríamos añadir un botón de reintentar aquí si refreshMembers está disponible */}
                            {/* <Button onClick={refreshMembers} size="small">Reintentar</Button> */}
                        </Alert>
                    )}

                    {!loadingMembers && !errorMembers && projectId && (
                        <EquipoList
                            miembros={currentProjectMembers}
                            onEditMiembro={openEditDialog}
                            onRemoveMiembro={handleRemoveMiembro}
                        />
                    )}
                     {!projectId && !loadingMembers && (
                         <Typography variant="body2" color="text.secondary" align="center" sx={{mt: 3}}>
                             Selecciona un proyecto para ver su equipo.
                         </Typography>
                     )}
                </Box>

            </Drawer>

            {/* Diálogos Modales (se renderizan fuera del Drawer pero controlados desde aquí) */}
            {projectId && (
                <>
                    <AddMiembroDialog
                        open={isAddDialogOpen}
                        onClose={handleCloseAddDialog}
                        onAdd={handleAddMiembro}
                        idProyecto={projectId}
                        miembrosActuales={currentProjectMembers}
                        // Pasamos el error de operación al diálogo
                        // errorProp={operationError} // Asumiendo que AddMiembroDialog acepta 'errorProp'
                    />
                    {miembroParaEditar && (
                        <EditRolDialog
                            open={isEditDialogOpen}
                            onClose={handleCloseEditDialog}
                            onUpdate={handleUpdateRol}
                            miembro={miembroParaEditar}
                             // Pasamos el error de operación al diálogo
                            // errorProp={operationError} // Asumiendo que EditRolDialog acepta 'errorProp'
                        />
                    )}
                </>
            )}

             {/* Snackbar para notificaciones (puede estar aquí o en DashboardPage) */}
             <Snackbar
                open={snackbar.open}
                autoHideDuration={4000} // Duración más corta para panel
                onClose={handleCloseSnackbar}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
                <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </>
    );
};

export default EquipoManagementPanel;
