// src/features/schedule/components/ScheduleTimeline.js
import React from 'react';
import {
    Timeline, TimelineItem, TimelineSeparator, TimelineConnector,
    TimelineContent, TimelineOppositeContent, TimelineDot
} from '@mui/lab';
import {
    Typography, Box, CircularProgress, Alert, Tooltip,
    useTheme, alpha, Stack, LinearProgress, Paper // Añadir Paper si se usa para el fondo
} from '@mui/material';
import EventIcon from '@mui/icons-material/Event';
import {
    formatDisplayDate, formatDisplayTime, calculateProgress, getUrgencyInfo
} from '../utils/scheduleUtils.js';
import { isValid } from 'date-fns';

// --- Componente TimelineItem Personalizado (Ajustado) ---
const CustomTimelineItem = ({ item, isFirst, isLast }) => {
    const theme = useTheme();

    // --- Validación de datos (sin cambios) ---
    const itemId = item?.id ?? `unknown-${Math.random()}`;
    const itemTitle = item?.title ?? 'Sin Título';
    const itemDescription = item?.description ?? '';
    const itemStatus = item?.status ?? 'pendiente';
    const itemPriority = item?.priority ?? 'media';
    const itemFechaInicioOrig = item?.fecha_inicio_orig ?? null;
    const itemFechaVencimientoOrig = item?.fecha_vencimiento_orig ?? null;
    const itemFechaInicioDisplay = item?.fecha_inicio_display ?? 'N/A';
    const itemFechaVencimientoDisplay = item?.fecha_vencimiento_display ?? 'N/A';
    const itemDate = item?.date ?? null;
    const itemIconComponent = item?.iconComponent ?? EventIcon;
    const itemColorName = item?.colorName ?? 'grey';

    // --- Cálculos específicos de la tarea (sin cambios) ---
    const taskProgress = calculateProgress(itemFechaInicioOrig, itemFechaVencimientoOrig);
    const taskUrgency = getUrgencyInfo(itemFechaInicioOrig, itemFechaVencimientoOrig, itemStatus, false);
    const {
        colorName: taskColorName = 'grey',
        label: taskUrgencyLabel = 'N/A',
        icon: TaskUrgencyIcon = EventIcon
    } = taskUrgency || {};

    // --- Obtener color de tarea (sin cambios) ---
    let taskColorValue = theme.palette.grey[500];
    const paletteColor = theme.palette[taskColorName];
    if (paletteColor && typeof paletteColor === 'object' && paletteColor.main) {
        taskColorValue = paletteColor.main;
    } else if (typeof paletteColor === 'string') {
        taskColorValue = paletteColor;
    } else if (taskColorName !== 'grey') {
        console.warn(`Task color name "${taskColorName}" invalid for item ${itemId}. Using grey.`);
    }
    if (typeof taskColorValue !== 'string') { taskColorValue = theme.palette.grey[500]; }

    // --- Fecha opuesta (sin cambios) ---
    const isValidItemDate = itemDate && isValid(itemDate);
    const formattedDate = isValidItemDate ? formatDisplayDate(itemDate) : 'Fecha N/A';
    const formattedTime = isValidItemDate ? formatDisplayTime(itemDate) : '';

    // --- Icono y color del punto (sin cambios) ---
    const DotIconComponent = itemIconComponent;
    let dotColorValue = theme.palette.grey[500];
    if (itemColorName && itemColorName !== 'grey' && theme.palette[itemColorName]) {
        const dotPaletteColor = theme.palette[itemColorName];
        if (dotPaletteColor && typeof dotPaletteColor === 'object' && dotPaletteColor.main) {
            dotColorValue = dotPaletteColor.main;
        } else if (typeof dotPaletteColor === 'string') {
            dotColorValue = dotPaletteColor;
        } else {
             console.warn(`Dot color name "${itemColorName}" invalid for item ${itemId}. Using grey.`);
        }
    }
    if (typeof dotColorValue !== 'string') { dotColorValue = theme.palette.grey[500]; }
    const contrastDotColor = dotColorValue ? theme.palette.getContrastText(dotColorValue) : theme.palette.text.primary;

    // --- Tooltip (sin cambios) ---
    const tooltipTitle = `Tarea: ${itemTitle} (Prioridad: ${itemPriority || 'N/A'} / Estado: ${itemStatus || 'N/A'})`;

    return (
        <TimelineItem sx={{ '&::before': { display: 'none' }, minHeight: 'auto' }}> {/* Asegurar altura mínima auto */}
            {/* Contenido Opuesto (Fecha/Hora) - Ajuste de padding */}
            <TimelineOppositeContent sx={{
                m: 'auto 0',
                flex: 0.25, // Ligeramente más espacio si es necesario
                textAlign: 'right',
                pr: 1.5, // Menos padding derecho
                py: 0.5 // Padding vertical reducido
            }} align="right" variant="caption" color="text.secondary"> {/* Caption para tamaño */}
                {formattedDate}
                {formattedTime && <Typography variant="caption" display="block">{formattedTime}</Typography>}
            </TimelineOppositeContent>

            {/* Separador y Punto (sin cambios) */}
            <TimelineSeparator>
                {!isFirst && <TimelineConnector sx={{ bgcolor: alpha(theme.palette.grey[500], 0.3) }} />}
                <Tooltip title={tooltipTitle}>
                    <TimelineDot sx={{ bgcolor: dotColorValue, boxShadow: theme.shadows[1], my: 0.5 }}> {/* Margen vertical reducido */}
                        {DotIconComponent && <DotIconComponent sx={{ fontSize: '1rem', color: contrastDotColor }} />}
                    </TimelineDot>
                </Tooltip>
                {!isLast && <TimelineConnector sx={{ bgcolor: alpha(theme.palette.grey[500], 0.3) }} />}
            </TimelineSeparator>

            {/* Contenido Principal - Ajustes de padding, fondo y hover */}
            <TimelineContent sx={{
                py: 1, // Padding vertical reducido
                px: 1.5, // Padding horizontal reducido
                // Opcional: Añadir un fondo sutil y borde para separar visualmente
                // bgcolor: alpha(theme.palette.grey[500], 0.03),
                // border: `1px solid ${theme.palette.divider}`,
                borderRadius: theme.shape.borderRadius / 2,
                transition: theme.transitions.create('background-color'),
                '&:hover': {
                    bgcolor: alpha(theme.palette.action.hover, 0.04), // Hover muy sutil
                }
            }}>
                <Stack spacing={0.5}> {/* Mantenemos spacing 0.5 */}
                    {/* Título y icono de estado/urgencia */}
                    <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1}>
                        <Typography variant="body2" component="span" fontWeight="600" sx={{ flexGrow: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}> {/* Body2 para título */}
                            {itemTitle}
                        </Typography>
                        <Tooltip title={`Estado Tarea: ${taskUrgencyLabel}`}>
                             {TaskUrgencyIcon && <TaskUrgencyIcon sx={{ fontSize: '1rem', color: taskColorValue, flexShrink: 0 }} />} {/* Icono un poco más pequeño */}
                        </Tooltip>
                    </Stack>

                    {/* Barra de Progreso */}
                    <Tooltip title={`Progreso Tarea: ${taskProgress}% (${taskUrgencyLabel})`}>
                        <Stack direction="row" spacing={1} alignItems="center" sx={{ width: '100%' }}>
                            <LinearProgress
                                variant="determinate"
                                value={taskProgress}
                                sx={{
                                    flexGrow: 1, height: 4, borderRadius: 2, // Más delgada
                                    backgroundColor: alpha(taskColorValue, 0.2),
                                    '& .MuiLinearProgress-bar': { backgroundColor: taskColorValue, borderRadius: 2 }
                                }}
                            />
                            <Typography variant="caption" sx={{ fontWeight: 500, color: theme.palette[taskColorName]?.dark || taskColorValue, flexShrink: 0, minWidth: '30px', textAlign: 'right' }}>
                                {taskProgress}%
                            </Typography>
                        </Stack>
                    </Tooltip>

                    {/* Descripción (opcional) */}
                    {itemDescription && (
                        <Typography variant="caption" color="text.secondary" sx={{ mt: 0.25 }}> {/* Caption y menos margen */}
                            {itemDescription}
                        </Typography>
                    )}
                    {/* Fechas de inicio y fin de la tarea */}
                     <Typography variant="caption" display="block" color="text.disabled" sx={{ mt: 0.25 }}>
                         {itemFechaInicioDisplay} - {itemFechaVencimientoDisplay}
                     </Typography>
                </Stack>
            </TimelineContent>
        </TimelineItem>
    );
};


// --- Componente Principal ScheduleTimeline (sin cambios) ---
const ScheduleTimeline = ({ items = [], loading, error }) => {
    const theme = useTheme();

    if (loading) {
        return ( <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', p: 4, minHeight: 150 }}><CircularProgress /></Box> );
    }
    if (error) {
        return ( <Alert severity="error" sx={{ m: 2 }}>Error en Timeline: {typeof error === 'string' ? error : JSON.stringify(error)}</Alert> );
    }
    if (!items || items.length === 0) {
        return (
            <Box sx={{ textAlign: 'center', p: 3, color: 'text.secondary', mt: 4 }}>
                <EventIcon sx={{ fontSize: 40, mb: 1, color: 'text.disabled' }} />
                <Typography>No hay elementos para mostrar en el cronograma.</Typography>
            </Box>
        );
    }

    const sortedItems = items; // La ordenación ya viene del hook

    return (
        <Timeline position="right" sx={{
            p: { xs: 0.5, sm: 1 }, // Ligero padding general
            m: 0, flexGrow: 1, overflowY: 'auto',
            // Scrollbar
            '&::-webkit-scrollbar': { width: '6px' },
            '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.25), borderRadius: '3px' }, // Más visible
            '&::-webkit-scrollbar-track': { backgroundColor: 'transparent' },
        }}>
            {sortedItems.map((item, index) => (
                <CustomTimelineItem
                    key={item.id || `item-${index}`}
                    item={item}
                    isFirst={index === 0}
                    isLast={index === sortedItems.length - 1}
                />
            ))}
        </Timeline>
    );
};

export default ScheduleTimeline;
