import React, { useState } from 'react';
import { useNavigate, useLocation, Link as RouterLink } from 'react-router-dom';
import { useAuth } from '../../../contexts/AuthContext.js';
import { loginUser } from '../services/authService.js';
import {
    TextField,
    Button,
    Alert,
    Box,
    Typography,
    CircularProgress,
    Avatar,
    Link as MuiLink,
    Paper,
    Fade,
    useTheme,
    IconButton,
    InputAdornment,
    Stack,
    alpha // Importar alpha para el degradado
} from '@mui/material';
import { LockOutlined as LockIcon, Visibility, VisibilityOff } from '@mui/icons-material';

const Login = () => {
    const theme = useTheme();
    const [formData, setFormData] = useState({ username: '', password: '' });
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();

    const from = location.state?.from?.pathname || "/dashboard";

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        if (error) setError('');
    };

    const handleClickShowPassword = () => setShowPassword((show) => !show);
    const handleMouseDownPassword = (event) => event.preventDefault();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        if (!formData.username || !formData.password) {
            setError('Por favor, completa ambos campos.');
            return;
        }
        setIsLoading(true);
        try {
            const { token, userInfo } = await loginUser(formData.username, formData.password);
            // Asegúrate que login en useAuth maneje correctamente userInfo
            await login(token, userInfo);
            navigate(from, { replace: true });
        } catch (err) {
            // Intenta obtener el mensaje de error específico de la respuesta de la API si está disponible
            const apiErrorMessage = err.response?.data?.message || err.data?.message;
            setError(apiErrorMessage || err.message || 'Credenciales incorrectas o error de conexión.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        // Fade necesita un único hijo directo que sea un elemento React válido
        <Fade in={true} timeout={800}>
            <Paper
                elevation={0} // Empezamos sin elevación, añadimos sombra sutil con sx
                sx={{
                    width: '100%',
                    p: { xs: 3, sm: 5 },
                    borderRadius: '16px', // Bordes un poco más redondeados
                    boxShadow: `0px 4px 20px ${alpha(theme.palette.grey[500], 0.08)}`, // Sombra sutil
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    // Fondo con degradado sutil
                    background: `linear-gradient(145deg, ${theme.palette.background.paper} 0%, ${alpha(theme.palette.primary.main, 0.02)} 100%)`,
                    overflow: 'hidden', // Asegura que el degradado no se salga por los bordes redondeados
                }}
            >
                {/* Encabezado del Formulario */}
                <Avatar sx={{
                    bgcolor: 'primary.main',
                    color: 'primary.contrastText',
                    mb: 2, width: 56, height: 56
                }}>
                    <LockIcon fontSize='medium'/>
                </Avatar>
                <Typography component="h1" variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
                    Bienvenido de Nuevo
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 4 }}>
                    Ingresa tus credenciales para acceder.
                </Typography>

                {/* Alerta de Error */}
                {error && (
                    <Alert
                        severity="error"
                        sx={{ mb: 2.5, width: '100%' }}
                        onClose={() => setError('')}
                        aria-live="assertive"
                        variant="outlined" // Variante outlined se ve bien con el fondo degradado/sombra
                    >
                        {error}
                    </Alert>
                )}

                {/* Formulario */}
                <Box component="form" onSubmit={handleSubmit} noValidate sx={{ width: '100%' }}>
                    <Stack spacing={2.5}>
                        <TextField
                            fullWidth
                            required
                            id="username"
                            label="Correo electrónico o Usuario"
                            name="username"
                            type="text"
                            autoComplete="username"
                            autoFocus
                            value={formData.username}
                            onChange={handleChange}
                            disabled={isLoading}
                            variant="outlined" // El tema ya lo define por defecto, pero es bueno ser explícito
                            error={!!error && !formData.username} // Marca error si hay error general y este campo está vacío
                            helperText={!!error && !formData.username ? "Este campo es requerido" : ""}
                        />
                        <TextField
                            fullWidth
                            required
                            id="password"
                            name="password"
                            label="Contraseña"
                            type={showPassword ? 'text' : 'password'}
                            autoComplete="current-password"
                            value={formData.password}
                            onChange={handleChange}
                            disabled={isLoading}
                            variant="outlined"
                            error={!!error && !formData.password} // Marca error si hay error general y este campo está vacío
                            helperText={!!error && !formData.password ? "Este campo es requerido" : ""}
                            InputProps={{
                                endAdornment: (
                                    <InputAdornment position="end">
                                        <IconButton
                                            aria-label="toggle password visibility"
                                            onClick={handleClickShowPassword}
                                            onMouseDown={handleMouseDownPassword}
                                            edge="end"
                                            size="medium"
                                        >
                                            {showPassword ? <VisibilityOff fontSize="inherit"/> : <Visibility fontSize="inherit"/>}
                                        </IconButton>
                                    </InputAdornment>
                                ),
                            }}
                        />
                        <Box sx={{ textAlign: 'right', mt: -1, mb: 1 }}>
                            <MuiLink
                                component={RouterLink}
                                to="/forgot-password" // Asegúrate que esta ruta exista
                                variant="body2"
                                // underline="hover" // Ya es default por el tema
                                sx={{ color: 'text.secondary' }} // Usar color secundario para menor énfasis
                            >
                                ¿Olvidaste tu contraseña?
                            </MuiLink>
                        </Box>

                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            color="primary"
                            size="large"
                            sx={{
                                py: 1.5,
                                fontWeight: 600,
                                textTransform: 'none', // Ya es default por el tema
                                borderRadius: '12px', // Bordes redondeados también para el botón
                                boxShadow: `0 4px 14px 0 ${alpha(theme.palette.primary.main, 0.3)}`,
                                transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
                                '&:hover': {
                                    boxShadow: `0 6px 20px 0 ${alpha(theme.palette.primary.main, 0.35)}`,
                                    transform: 'translateY(-2px)',
                                }
                            }}
                            disabled={isLoading || !formData.username || !formData.password} // Deshabilitar si carga o faltan campos
                            startIcon={isLoading ? <CircularProgress size={20} color="inherit" /> : null}
                        >
                            {isLoading ? 'Accediendo...' : 'Acceder'}
                        </Button>
                    </Stack>
                </Box>
            </Paper>
        </Fade>
    );
};

export default Login;
