// src/features/schedule/components/GeneralSummaryPanel.js
import React from 'react';
import {
    Box, Typography, Stack, LinearProgress, Tooltip, alpha, useTheme
} from '@mui/material';
import { calculateProgress, getUrgencyInfo } from '../utils/scheduleUtils.js';
import EventIcon from '@mui/icons-material/Event';
import { styled } from '@mui/material/styles';
import { parseISO, isValid } from 'date-fns'; // <--- Importar parseISO e isValid

// Estilo personalizado para la barra de progreso (más delgada)
const CustomLinearProgress = styled(LinearProgress)(({ theme, barcolor }) => ({
    height: 4, // Reducir altura
    borderRadius: 2, // Reducir radio
    backgroundColor: alpha(barcolor || theme.palette.grey[500], 0.2),
    '& .MuiLinearProgress-bar': {
        borderRadius: 2,
        backgroundColor: barcolor || theme.palette.grey[500],
    },
}));

// Componente para un item individual del resumen (Ajustado para ser más compacto)
const SummaryItem = ({ project }) => {
    const theme = useTheme();

    // --- Validación de datos (sin cambios) ---
    const projectId = project?.id_proyecto ?? 'unknown';
    const projectName = project?.nombre ?? 'Proyecto sin nombre';
    const projectStatus = project?.estado ?? 'desconocido';
    const projectFechaInicioOrig = project?.fecha_inicio_orig ?? null;
    const projectFechaFinOrig = project?.fecha_fin_orig ?? null;
    const projectFechaInicioDisplay = project?.fecha_inicio_display ?? 'N/A';
    const projectFechaFinDisplay = project?.fecha_fin_display ?? 'N/A';

    // --- Cálculos (sin cambios) ---
    const progress = calculateProgress(projectFechaInicioOrig, projectFechaFinOrig);
    const urgency = getUrgencyInfo(projectFechaInicioOrig, projectFechaFinOrig, projectStatus, true);
    const { colorName = 'grey', label: urgencyLabel = 'N/A', icon: UrgencyIcon = EventIcon } = urgency || {};

    // --- Obtener color (sin cambios) ---
    let projectColor = theme.palette.grey[600];
    const paletteColor = theme.palette[colorName];
    if (paletteColor && typeof paletteColor === 'object' && paletteColor.main) {
        projectColor = paletteColor.main;
    } else if (typeof paletteColor === 'string') {
        projectColor = paletteColor;
    } else if (colorName !== 'grey') {
        console.warn(`Project color name "${colorName}" invalid for project ${projectId}. Using grey.`);
    }
    if (typeof projectColor !== 'string') { projectColor = theme.palette.grey[600]; }

    return (
        <Box
            sx={{
                p: 1.25, // Padding reducido
                borderLeft: `3px solid ${projectColor}`, // Borde izquierdo más delgado
                border: `1px solid ${theme.palette.divider}`,
                borderLeftWidth: '3px',
                bgcolor: 'background.paper',
                transition: theme.transitions.create(['border-color', 'background-color', 'box-shadow']),
                '&:hover': {
                    borderColor: theme.palette.divider,
                    borderLeftColor: projectColor,
                    bgcolor: alpha(theme.palette.action.hover, 0.03),
                    boxShadow: theme.shadows[1],
                }
            }}
        >
            <Stack spacing={0.5}> {/* Espaciado interno reducido */}
                <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1}>
                    <Tooltip title={projectName}>
                        {/* Usar caption para el título para hacerlo más pequeño */}
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.primary', flexGrow: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {projectName}
                        </Typography>
                    </Tooltip>
                    <Tooltip title={`Estado: ${urgencyLabel}`}>
                        {/* Icono un poco más pequeño */}
                        {UrgencyIcon && <UrgencyIcon sx={{ fontSize: '0.9rem', color: projectColor, flexShrink: 0 }} />}
                    </Tooltip>
                </Stack>

                <Stack direction="row" spacing={0.75} alignItems="center"> {/* Espaciado reducido */}
                    <CustomLinearProgress variant="determinate" value={progress} barcolor={projectColor} sx={{ flexGrow: 1 }} />
                    <Typography variant="caption" sx={{ fontWeight: 500, color: projectColor, minWidth: '28px', textAlign: 'right' }}> {/* Ancho mínimo reducido */}
                        {progress}%
                    </Typography>
                </Stack>

                 {/* Fechas más pequeñas */}
                 <Typography variant="caption" color="text.secondary" sx={{ textAlign: 'right', fontSize: '0.65rem', lineHeight: 1.2 }}>
                    {projectFechaInicioDisplay} → {projectFechaFinDisplay}
                 </Typography>
            </Stack>
        </Box>
    );
};


// Componente principal
const GeneralSummaryPanel = ({ projects = [] }) => {

    if (!projects || projects.length === 0) {
        return ( <Box sx={{ p: 2, textAlign: 'center', color: 'text.disabled' }}><Typography>No hay información general de proyectos disponible.</Typography></Box> );
    }

    // *** NUEVO: Ordenar los proyectos ***
    const sortedProjects = [...projects].sort((a, b) => {
        // Intenta parsear las fechas de finalización
        const dateA = a.fecha_fin_orig ? parseISO(a.fecha_fin_orig.replace(' ', 'T')) : null;
        const dateB = b.fecha_fin_orig ? parseISO(b.fecha_fin_orig.replace(' ', 'T')) : null;

        const isValidA = dateA && isValid(dateA);
        const isValidB = dateB && isValid(dateB);

        // Si ambas fechas son válidas, ordena por fecha ascendente (más cercana primero)
        if (isValidA && isValidB) {
            return dateA.getTime() - dateB.getTime();
        }
        // Si solo A tiene fecha válida, A va primero
        if (isValidA && !isValidB) {
            return -1;
        }
        // Si solo B tiene fecha válida, B va primero
        if (!isValidA && isValidB) {
            return 1;
        }
        // Si ninguna tiene fecha válida, mantiene el orden original relativo
        return 0;
    });
    // *** FIN: Ordenar los proyectos ***

    return (
        <Stack spacing={1.5}> {/* Espaciado entre items reducido */}
            <Box sx={{ width: '100%' }}>
                <Stack spacing={1}> {/* Espaciado entre items reducido */}
                    {/* *** Usar sortedProjects en lugar de projects *** */}
                    {sortedProjects.map((project) => (
                        <SummaryItem key={project.id_proyecto || `proj-${Math.random()}`} project={project} />
                    ))}
                </Stack>
            </Box>
        </Stack>
    );
};

export default GeneralSummaryPanel;
