// src/features/schedule/components/Cronograma.js
import React, { useState, useCallback } from 'react';
import {
    Box, Typography, CircularProgress, Alert, ToggleButtonGroup, ToggleButton, Stack, useTheme, Paper, alpha
} from '@mui/material';
import { useScheduleData } from '../hooks/useScheduleData.js';
import ScheduleTimeline from './ScheduleTimeline.js';
import ScheduleProjectHeader from './ScheduleProjectHeader.js';
import ProjectDetailsPanel from './ProjectDetailsPanel.js';
import GeneralSummaryPanel from './GeneralSummaryPanel.js';
import ActivityLogDisplay from './ActivityLogDisplay.js';
import ActivityLogDetailDialog from './ActivityLogDetailDialog.js';
import {
    WarningAmber as WarningIcon,
    ErrorOutline as ErrorIcon,
    InfoOutlined as InfoIcon,
    FlagOutlined as FlagIcon,
    History as HistoryIcon,
    AssessmentOutlined as SummaryIcon,
} from '@mui/icons-material';

const Cronograma = ({ selectedProjectId = null, activityLog }) => {
    const theme = useTheme();
    const {
        timelineItems,
        selectedProjectDetails,
        generalProjectsData,
        projectProgress,
        projectUrgencyInfo,
        loading,
        error,
        filters,
        handleFilterChange,
        projectActivityLog
    } = useScheduleData(selectedProjectId);

    // --- Estado Diálogo Log (sin cambios) ---
    const [selectedLogEntry, setSelectedLogEntry] = useState(null);
    const [isLogDetailOpen, setIsLogDetailOpen] = useState(false);
    const handleLogItemClick = useCallback((logEntry) => {
        setSelectedLogEntry(logEntry);
        setIsLogDetailOpen(true);
    }, []);
    const handleCloseLogDetail = useCallback(() => {
        setIsLogDetailOpen(false);
        setTimeout(() => setSelectedLogEntry(null), theme.transitions.duration.leavingScreen);
    }, [theme.transitions.duration.leavingScreen]);

    // --- Renderizado Carga/Error (sin cambios) ---
    if (loading) {
        return ( <Box sx={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', p: 2 }}><CircularProgress size={50} thickness={4} /></Box> );
    }
    if (error) {
        return ( <Box sx={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', p: 2 }}><Alert severity="error" variant="outlined" icon={<ErrorIcon />} sx={{ width: '100%', maxWidth: 600 }}>Error al cargar datos: {error}</Alert></Box> );
    }

    // --- Renderizado Principal ---
    return (
        <Box sx={{
            width: '100%',
            height: '100%',
            display: 'flex',
            gap: 2.5, // Aumentar separación
            p: 0, // Quitar padding aquí, se maneja dentro
            overflow: 'hidden',
        }}>

            {/* === Columna Izquierda: Cabecera, Filtros y Timeline === */}
            <Box sx={{
                display: 'flex',
                flexDirection: 'column',
                gap: 2, // Aumentar separación interna
                flexBasis: { xs: '100%', sm: '55%', md: '60%' },
                flexShrink: 0,
                overflow: 'hidden',
                transition: 'flex-basis 0.3s ease-in-out',
                height: '100%',
            }}>
                {/* --- Cabecera y Filtros (en un Paper) --- */}
                {/* *** Paper con elevación y borde *** */}
                <Paper elevation={1} sx={{
                    p: 2, // Más padding
                    flexShrink: 0,
                }}>
                    <Stack spacing={2}> {/* Más espacio */}
                        {selectedProjectId && selectedProjectDetails && projectUrgencyInfo && (
                            <ScheduleProjectHeader
                                projectDetails={selectedProjectDetails}
                                urgencyInfo={projectUrgencyInfo}
                                progress={projectProgress}
                            />
                        )}
                        {!selectedProjectId && (
                            <Typography variant="h6" sx={{ fontWeight: 600, color: 'text.primary', fontSize: '1.1rem' }}>
                                Cronograma General
                            </Typography>
                        )}
                        {/* Filtros */}
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'flex-start', alignItems: 'center', gap: 1 }}>
                            <Typography variant="caption" sx={{ color: 'text.secondary', fontWeight: 500, mr: 1 }}>Prioridad Tarea:</Typography>
                            <ToggleButtonGroup
                                value={filters.priority}
                                exclusive
                                size="small"
                                onChange={(event, newPriority) => { if (newPriority !== null) { handleFilterChange('priority', newPriority); } }}
                                aria-label="Filtrar tareas por prioridad"
                                sx={{ '& .MuiToggleButton-root': { textTransform: 'none', fontWeight: 500, py: 0.25, px: 1, fontSize: '0.75rem' } }}
                            >
                                <ToggleButton value="all" aria-label="Todas">Todas</ToggleButton>
                                <ToggleButton value="alta" aria-label="Alta"><WarningIcon sx={{ mr: 0.5, fontSize: '1rem', color: 'warning.main' }} /> Alta</ToggleButton>
                                <ToggleButton value="media" aria-label="Media"><InfoIcon sx={{ mr: 0.5, fontSize: '1rem', color: 'info.main' }} /> Media</ToggleButton>
                                <ToggleButton value="baja" aria-label="Baja"><FlagIcon sx={{ mr: 0.5, fontSize: '1rem', color: 'success.light' }} /> Baja</ToggleButton>
                            </ToggleButtonGroup>
                        </Box>
                    </Stack>
                </Paper>

                {/* --- Timeline (en un Paper) --- */}
                {/* *** Paper con elevación y borde *** */}
                <Paper elevation={1} sx={{
                    flexGrow: 1,
                    overflow: 'hidden',
                    display: 'flex', // Para que Timeline ocupe espacio
                }}>
                    <ScheduleTimeline
                        items={timelineItems}
                        loading={false} // Loading ya se manejó arriba
                        error={null}    // Error ya se manejó arriba
                    />
                </Paper>
            </Box>

            {/* === Columna Derecha: Panel de Detalles O Resumen General + Historial Global === */}
            <Box sx={{
                flexGrow: 1,
                display: 'flex',
                flexDirection: 'column',
                overflow: 'hidden',
                minWidth: 320, // Ancho mínimo
                height: '100%',
            }}>
                {/* *** Paper con elevación y borde *** */}
                <Paper elevation={1} sx={{
                    p: 0,
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    overflow: 'hidden',
                }}>
                    {selectedProjectId && selectedProjectDetails ? (
                        // --- Vista Específica: Panel de Detalles ---
                        <ProjectDetailsPanel
                            project={selectedProjectDetails}
                            activityLog={projectActivityLog}
                            onLogItemClick={handleLogItemClick}
                        />
                    ) : (
                        // --- Vista Global: Resumen + Historial ---
                        <>
                            <Box sx={{ p: 2, flexShrink: 0, borderBottom: `1px solid ${theme.palette.divider}` }}>
                                <Typography variant="h6" sx={{ fontWeight: 600 }}>Vista General</Typography>
                            </Box>
                            {/* Contenedor para las dos secciones con scroll */}
                                <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden', p: 2, gap: 2 }}>
                                {/* Sección 1: Resumen General */}
                                <Box sx={{ height: 'calc(50% - 8px)', display: 'flex', flexDirection: 'column', overflow: 'hidden',  }}>
                                    <Stack direction="row" spacing={1} alignItems="center" sx={{ p: 1.5, borderBottom: `1px solid ${theme.palette.divider}`, flexShrink: 0 }}>
                                        <SummaryIcon sx={{ color: 'text.secondary' }} />
                                        <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>Progreso General</Typography>
                                    </Stack>
                                    <Box sx={{ flexGrow: 1, overflowY: 'auto', p: 1.5, '&::-webkit-scrollbar': { width: '6px' }, '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.2), borderRadius: '3px' } }}>
                                        <GeneralSummaryPanel projects={generalProjectsData} />
                                    </Box>
                                </Box>
                                {/* Sección 2: Historial Global */}
                                <Box sx={{ height: 'calc(50% - 8px)', display: 'flex', flexDirection: 'column', overflow: 'hidden',   }}>
                                    <Stack direction="row" spacing={1} alignItems="center" sx={{ p: 1.5, borderBottom: `1px solid ${theme.palette.divider}`, flexShrink: 0 }}>
                                        <HistoryIcon sx={{ color: 'text.secondary' }} />
                                        <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>Actividad Reciente</Typography>
                                    </Stack>
                                    <Box sx={{ flexGrow: 1, overflowY: 'auto', p: 1.5, '&::-webkit-scrollbar': { width: '6px' }, '&::-webkit-scrollbar-thumb': { backgroundColor: alpha(theme.palette.text.primary, 0.2), borderRadius: '3px' } }}>
                                        <ActivityLogDisplay
                                            // Pasar el log GLOBAL recibido de DashboardPage
                                            entries={activityLog?.entries}
                                            loading={activityLog?.loading}
                                            error={activityLog?.error}
                                            onLogItemClick={handleLogItemClick}
                                        />
                                    </Box>
                                </Box>
                            </Box>
                            
                        </>
                    )}
                </Paper>
            </Box>

            {/* Diálogo Detalles Log (sin cambios) */}
            <ActivityLogDetailDialog
                logEntry={selectedLogEntry}
                open={isLogDetailOpen}
                onClose={handleCloseLogDetail}
            />
        </Box>
    );
};

export default Cronograma;
