// src/services/apiClient.js
import { API_BASE_URL } from '../config/api.js';

import { getToken as retrieveToken } from '../utils/auth.js';

/**
 * Construye la URL final incluyendo los query parameters.
 * @param {string} baseUrl - La URL base de la API.
 * @param {string} endpoint - El endpoint específico.
 * @param {object} [params] - Objeto con los parámetros de consulta.
 * @returns {string} La URL completa.
 */
const buildUrl = (baseUrl, endpoint, params) => {
    // Asegura que el endpoint empiece con '/' y evita dobles barras
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    let finalUrl = `${baseUrl}${cleanEndpoint}`;

    if (params && Object.keys(params).length > 0) {
        // Filtra parámetros nulos o undefined antes de construir la query string
        const validParams = Object.entries(params).reduce((acc, [key, value]) => {
            if (value !== null && value !== undefined) {
                acc[key] = value;
            }
            return acc;
        }, {});

        if (Object.keys(validParams).length > 0) {
            const queryParams = new URLSearchParams(validParams).toString();
            finalUrl += `?${queryParams}`;
        }
    }
    return finalUrl;
};

const request = async (endpoint, options = {}) => {
    const token = retrieveToken();

    // *** CORRECCIÓN: Construir la URL final usando los params ***
    const finalUrl = buildUrl(API_BASE_URL, endpoint, options.params);

    // Log con la URL final que SÍ incluye los parámetros
    // Usar console.debug para logs menos intrusivos en producción si se configura
    console.debug(`API Request: ${options.method || 'GET'} ${finalUrl}`);

    const defaultHeaders = {
        'Accept': 'application/json',
    };

    // Solo añadir Content-Type si hay body y no es FormData
    if (options.body && !(options.body instanceof FormData)) {
        defaultHeaders['Content-Type'] = 'application/json';
    }

    // Añadir token si existe
    if (token) {
        defaultHeaders['Authorization'] = `Bearer ${token}`;
    } else {
        // Log importante si no hay token para peticiones que no sean login/registro
        // Ajusta las rutas públicas según tu aplicación
        const publicEndpoints = ['/login.php', '/usuarios.php'];
        const isPublicPost = options.method === 'POST' && endpoint.includes('/usuarios.php');

        if (!publicEndpoints.some(publicEp => endpoint.includes(publicEp)) && !isPublicPost) {
             console.warn(`API Client: No token found for request to ${endpoint}`);
             // Considera lanzar un error aquí o manejarlo según tu lógica de autenticación
        }
    }

    const headers = {
        ...defaultHeaders,
        ...options.headers, // Permite sobreescribir o añadir cabeceras
    };

    let body = options.body;
    // Convertir body a JSON si es necesario
    if (body && typeof body === 'object' && !(body instanceof FormData)) {
        try {
            body = JSON.stringify(body);
        } catch (error) {
            console.error("Error convirtiendo el cuerpo de la solicitud a JSON:", error);
            throw new Error("No se pudo procesar el cuerpo de la solicitud.");
        }
    }

    // Prepara las opciones para fetch, excluyendo 'params' que ya se usó en la URL
    const fetchOptions = {
        method: options.method || 'GET', // Asegura que el método esté definido
        headers,
        body,
        // *** CORRECCIÓN: Excluir 'params' de las opciones pasadas a fetch ***
        ...Object.keys(options)
               .filter(key => !['method', 'headers', 'body', 'params'].includes(key))
               .reduce((obj, key) => { obj[key] = options[key]; return obj; }, {}),
    };


    try {
        // *** CORRECCIÓN: Usar finalUrl en lugar de la url base ***
        const response = await fetch(finalUrl, fetchOptions);

        // Manejo de respuesta 204 No Content
        if (response.status === 204) {
            console.debug(`API Response: ${response.status} No Content for ${options.method || 'GET'} ${finalUrl}`);
            // Para DELETE o PUT exitosos sin contenido, devuelve un objeto consistente
            return { success: true, data: null, status: 204 };
        }

        let responseData = null;
        const contentType = response.headers.get("content-type");

        // Intentar parsear como JSON si el header lo indica
        if (contentType && contentType.includes("application/json")) {
            try {
                responseData = await response.json();
                // Log de la respuesta (opcional, útil para depuración)
                // console.log(`API Response Data (${response.status}) for ${options.method || 'GET'} ${finalUrl}:`, responseData);
            } catch (jsonError) {
                console.error(`API Client: Error al parsear respuesta JSON (${response.status}) desde ${finalUrl}:`, jsonError);
                // Si la respuesta era OK pero el JSON falló, es un error del backend
                if (response.ok) {
                    throw new Error("Respuesta inválida del servidor (JSON mal formado).");
                }
                // Si no era OK, el error HTTP se manejará abajo, responseData será null
            }
        } else if (response.ok) {
             // Si es OK pero no JSON, leer como texto (puede ser HTML de error PHP no esperado)
             try {
                 const textData = await response.text();
                 console.warn(`API Client: Respuesta OK pero no JSON (${contentType || 'N/A'}) desde ${finalUrl}:`, textData.substring(0, 500)); // Log limitado
                 // Considerar esto un error si siempre esperas JSON
                 throw new Error("Formato de respuesta inesperado del servidor (se esperaba JSON).");
                 // O devolver el texto si es un caso válido:
                 // responseData = { success: true, data: textData, status: response.status };
             } catch (textError) {
                 console.error(`API Client: Error al leer respuesta como texto (${response.status}) desde ${finalUrl}:`, textError);
                 throw new Error("Error al leer la respuesta del servidor.");
             }
        }
        // Si no es OK y no es JSON, responseData seguirá siendo null

        // Manejo de errores HTTP
        if (!response.ok) {
            // Intenta obtener el mensaje del JSON de error, si no, usa el statusText
            const errorMessage = responseData?.message || responseData?.error || `Error ${response.status}: ${response.statusText}`;
            const error = new Error(errorMessage);
            error.status = response.status; // Adjunta el código de estado HTTP
            error.data = responseData; // Adjunta el cuerpo del error si se pudo parsear
            console.error(`API Client Error Response (${response.status}) for ${options.method || 'GET'} ${finalUrl}:`, errorMessage, responseData || '(No response body)'); // Log detallado del error
            throw error; // Lanzar el error formateado
        }

        // Si todo fue OK, devuelve los datos (probablemente JSON)
        // El backend ya debería incluir 'success: true'
        // Añadimos el status por si es útil en el servicio/hook
        return { ...responseData, status: response.status };

    } catch (error) {
        // Captura errores de red (fetch falló), JSON parse, o los lanzados por !response.ok o JSON mal formado
        // No loguear aquí si ya se logueó en el bloque !response.ok
        if (!error.status) { // Solo loguear si es un error de red/proceso, no un error HTTP ya logueado
            console.error(`API Client Network/Processing Error (${options.method || 'GET'} ${endpoint}):`, error.message || error);
        }

        // Manejo específico de 401 Unauthorized (si no estamos ya en login)
        if (error.status === 401 && typeof window !== 'undefined' && !window.location.pathname.startsWith('/login')) {
            console.warn("API Client: Unauthorized (401). Clearing token and redirecting to login.");
            localStorage.removeItem('authToken');
            // Considera limpiar también `user` en AuthContext si tienes acceso o mediante un evento/callback
            // authContext.logout(); // Si tienes un método en tu contexto
            window.location.href = '/login'; // Redirección forzada
            // Devolver una promesa rechazada para detener el flujo en el punto de llamada original
            return Promise.reject(new Error("Sesión inválida o expirada. Redirigiendo a login..."));
        }

        // Relanza otros errores para que el servicio/hook los maneje
        // El error ya debería tener 'status' y 'data' si vino de una respuesta HTTP no-OK
        throw error;
    }
};

// Métodos helper (sin cambios, dependen de 'request' corregido)
const apiClient = {
    // Pasa 'params' dentro de las 'options' para GET y DELETE
    get: (endpoint, options = {}) => request(endpoint, { ...options, method: 'GET' }),
    post: (endpoint, body, options = {}) => request(endpoint, { ...options, method: 'POST', body }),
    put: (endpoint, body, options = {}) => request(endpoint, { ...options, method: 'PUT', body }),
    // DELETE también puede necesitar params en la URL
    delete: (endpoint, options = {}) => request(endpoint, { ...options, method: 'DELETE' }),
    patch: (endpoint, body, options = {}) => request(endpoint, { ...options, method: 'PATCH', body }),
};

export default apiClient;
