// src/layouts/Navbar.js
import React, { useState, useCallback } from 'react';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import {
    AppBar,
    Toolbar,
    Typography,
    Box,
    IconButton,
    useTheme,
    useMediaQuery,
    Menu,
    MenuItem,
    Divider,
    Badge,
    InputBase,
    alpha,
    Avatar,
    Stack,
    Tooltip,
    styled,
    Button
} from '@mui/material';
import {
    Menu as MenuIcon,
    Notifications as NotificationsIcon,
    Search as SearchIcon,
    Logout as LogoutIcon,
    Settings as SettingsIcon,
    AccountCircle as AccountCircleIcon,
    ChevronLeft as ChevronLeftIcon,
    MenuOpen as MenuOpenIcon,
    Science as ScienceIcon,
} from '@mui/icons-material';
import { useAuth } from '../contexts/AuthContext.js';

// --- Styled Components ---

// *** AppBar con fondo Papel, borde Y SOMBRA MÁS NOTORIA ***
const StyledAppBar = styled(AppBar)(({ theme }) => ({
    height: '64px',
    backgroundColor: theme.palette.background.paper, // Fondo Papel
    color: theme.palette.text.primary, // Color texto primario
    boxShadow: theme.shadows[2], // *** Sombra más pronunciada (ej. nivel 2) ***
    borderBottom: `1px solid ${theme.palette.divider}`, // Mantenemos borde inferior
    borderRadius: 0
}));

// --- (Resto de Styled Components sin cambios) ---
const StyledToolbar = styled(Toolbar)(({ theme }) => ({
    minHeight: '64px !important',
    justifyContent: 'space-between',
    padding: theme.spacing(0, 2),
    [theme.breakpoints.up('md')]: {
        padding: theme.spacing(0, 3),
    },
}));

const Search = styled('div')(({ theme }) => ({
    position: 'relative',
    borderRadius: theme.shape.borderRadius,
    backgroundColor: alpha(theme.palette.grey[500], 0.08),
    '&:hover': {
        backgroundColor: alpha(theme.palette.grey[500], 0.12),
    },
    marginLeft: theme.spacing(2),
    width: '100%',
    maxWidth: '400px',
    transition: theme.transitions.create('background-color'),
}));

const SearchIconWrapper = styled('div')(({ theme }) => ({
    padding: theme.spacing(0, 1.5),
    height: '100%',
    position: 'absolute',
    pointerEvents: 'none',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    color: theme.palette.text.secondary,
}));

const StyledInputBase = styled(InputBase)(({ theme }) => ({
    color: 'inherit',
    width: '100%',
    '& .MuiInputBase-input': {
        padding: theme.spacing(1, 1, 1, 0),
        paddingLeft: `calc(1em + ${theme.spacing(3.5)})`,
        fontSize: '0.9rem',
        height: '20px',
        '&::placeholder': {
            color: theme.palette.text.disabled,
            opacity: 1,
        },
    },
}));

const StyledBadge = styled(Badge)(({ theme }) => ({
    '& .MuiBadge-badge': {
        backgroundColor: theme.palette.error.main,
        color: theme.palette.error.contrastText,
        minWidth: '18px',
        height: '18px',
        fontSize: '0.65rem',
        fontWeight: '600',
        borderRadius: '6px',
        padding: '0 4px',
        right: 2,
        top: 2,
    },
}));

// --- Componente Navbar (Lógica sin cambios) ---
const Navbar = ({ sx, handleDrawerToggle, isSidebarCollapsed, ...props }) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('md'));
    const navigate = useNavigate();
    const { user, logout, isAuthenticated } = useAuth();
    const [anchorEl, setAnchorEl] = useState(null);

    const handleMenuOpen = useCallback((event) => {
        setAnchorEl(event.currentTarget);
    }, []);

    const handleMenuClose = useCallback(() => {
        setAnchorEl(null);
    }, []);

    const handleLogout = useCallback(async () => {
        handleMenuClose();
        await logout();
    }, [logout, handleMenuClose]);

    const handleNavigate = useCallback((path) => {
        handleMenuClose();
        navigate(path);
    }, [navigate, handleMenuClose]);

    const getInitials = (name) => {
        if (!name) return '?';
        const names = name.split(' ');
        if (names.length === 1) return names[0][0].toUpperCase();
        return (names[0][0] + names[names.length - 1][0]).toUpperCase();
    };

    return (
        <StyledAppBar sx={sx} {...props}>
            <StyledToolbar>
                {/* --- Sección Izquierda --- */}
                <Stack direction="row" alignItems="center" spacing={1}>
                    {/* Botón Menú/Colapsar */}
                    <Tooltip title={isMobile ? "Abrir menú" : (isSidebarCollapsed ? "Expandir menú" : "Colapsar menú")} arrow>
                        <IconButton
                            color="inherit" // Hereda color texto primario
                            edge="start"
                            onClick={handleDrawerToggle}
                            sx={{
                                // Hover estándar
                                '&:hover': {
                                    backgroundColor: alpha(theme.palette.action.hover, 0.06)
                                }
                            }}
                        >
                            {isMobile ? <MenuIcon /> : (isSidebarCollapsed ? <MenuOpenIcon /> : <ChevronLeftIcon />)}
                        </IconButton>
                    </Tooltip>

                    {/* Logo/Título (Solo en móvil) */}
                    {isMobile && (
                        <Stack
                            direction="row"
                            alignItems="center"
                            spacing={1}
                            component={RouterLink}
                            to="/"
                            sx={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            {/* Avatar con color primario */}
                            <Avatar sx={{ bgcolor: theme.palette.primary.main, width: 32, height: 32 }}>
                                <ScienceIcon sx={{ fontSize: '1.1rem', color: theme.palette.primary.contrastText }} />
                            </Avatar>
                        </Stack>
                    )}

                    {/* Barra de Búsqueda (Oculta en móvil) */}
                    {!isMobile && (
                        <Search>
                            <SearchIconWrapper>
                                <SearchIcon fontSize="small" />
                            </SearchIconWrapper>
                            <StyledInputBase
                                placeholder="Buscar..."
                                inputProps={{ 'aria-label': 'search' }}
                            />
                        </Search>
                    )}
                </Stack>

                {/* --- Sección Derecha --- */}
                <Stack direction="row" alignItems="center" spacing={isMobile ? 0.5 : 1.5}>
                    {/* Icono de Búsqueda (Móvil) */}
                    {isMobile && (
                        <Tooltip title="Buscar" arrow>
                            <IconButton
                                color="inherit"
                                sx={{ '&:hover': { backgroundColor: alpha(theme.palette.action.hover, 0.06) } }}
                            >
                                <SearchIcon />
                            </IconButton>
                        </Tooltip>
                    )}

                    {/* Notificaciones */}
                    <Tooltip title="Notificaciones" arrow>
                        <IconButton
                            color="inherit"
                            sx={{ '&:hover': { backgroundColor: alpha(theme.palette.action.hover, 0.06) } }}
                        >
                            <StyledBadge badgeContent={4} overlap="circular">
                                <NotificationsIcon />
                            </StyledBadge>
                        </IconButton>
                    </Tooltip>

                    {/* Menú de Usuario */}
                    {isAuthenticated && user ? (
                        <Tooltip title="Cuenta" arrow>
                            <IconButton
                                onClick={handleMenuOpen}
                                size="small"
                                sx={{ ml: 1 }}
                            >
                                {/* Avatar estándar */}
                                <Avatar
                                    sx={{
                                        width: 36,
                                        height: 36,
                                        fontSize: '0.9rem',
                                        bgcolor: alpha(theme.palette.primary.main, 0.1), // Fondo primario suave
                                        color: theme.palette.primary.dark, // Texto primario oscuro
                                        fontWeight: 500,
                                    }}
                                >
                                    {getInitials(user.nombre)}
                                </Avatar>
                            </IconButton>
                        </Tooltip>
                    ) : (
                        // Botón de Login estándar
                        <Button component={RouterLink} to="/login" color="primary" variant="outlined" size="small">
                            Iniciar Sesión
                        </Button>
                    )}

                    {/* Dropdown del Menú de Usuario (sin cambios) */}
                    <Menu
                        anchorEl={anchorEl}
                        open={Boolean(anchorEl)}
                        onClose={handleMenuClose}
                        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
                        slotProps={{
                            paper: {
                                elevation: 0,
                                sx: {
                                    overflow: 'visible',
                                    boxShadow: theme.shadows[3],
                                    mt: 1.5,
                                    border: `1px solid ${theme.palette.divider}`,
                                    width: 220,
                                    bgcolor: 'background.paper',
                                    color: 'text.primary',
                                    '& .MuiAvatar-root': { width: 32, height: 32, ml: -0.5, mr: 1.5 },
                                    '&:before': {
                                        content: '""', display: 'block', position: 'absolute',
                                        top: 0, right: 14, width: 10, height: 10,
                                        bgcolor: 'background.paper',
                                        transform: 'translateY(-50%) rotate(45deg)',
                                        zIndex: 0,
                                        borderLeft: `1px solid ${theme.palette.divider}`,
                                        borderTop: `1px solid ${theme.palette.divider}`,
                                    },
                                },
                            }
                        }}
                    >
                        {/* Cabecera del Menú */}
                        <Box sx={{ px: 2, py: 1.5 }}>
                            <Typography variant="subtitle2" fontWeight={600} noWrap>
                                {user?.nombre || 'Usuario'}
                            </Typography>
                            <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
                                {user?.email || ''}
                            </Typography>
                        </Box>
                        <Divider sx={{ borderStyle: 'dashed' }} />
                        {/* Opciones del Menú */}
                        <MenuItem
                            onClick={() => handleNavigate('/profile')}
                            sx={{ py: 1, px: 2, fontSize: '0.9rem', '&:hover': { backgroundColor: theme.palette.action.hover} }}
                        >
                            <AccountCircleIcon sx={{ mr: 1.5, color: 'text.secondary' }} fontSize="small" />
                            Mi Perfil
                        </MenuItem>
                        <MenuItem
                            onClick={() => handleNavigate('/settings')}
                            sx={{ py: 1, px: 2, fontSize: '0.9rem', '&:hover': { backgroundColor: theme.palette.action.hover} }}
                        >
                            <SettingsIcon sx={{ mr: 1.5, color: 'text.secondary' }} fontSize="small" />
                            Configuración
                        </MenuItem>
                        <Divider sx={{ borderStyle: 'dashed' }} />
                        {/* Logout */}
                        <MenuItem
                            onClick={handleLogout}
                            sx={{
                                py: 1, px: 2, fontSize: '0.9rem', color: 'error.main',
                                '&:hover': { backgroundColor: alpha(theme.palette.error.main, 0.08) }
                            }}
                        >
                            <LogoutIcon sx={{ mr: 1.5 }} fontSize="small" />
                            Cerrar Sesión
                        </MenuItem>
                    </Menu>
                </Stack>
            </StyledToolbar>
        </StyledAppBar>
    );
};

export default Navbar;
